      store(LS_VIEW, view);
    }
    qa('.kami-seg-item', root).forEach(function (b) {
      b.addEventListener('click', function (ev) { ev.stopPropagation(); setView(b.getAttribute('data-kami-mode')); });
    });
    setView(view);

