:where(.kami-root [data-kami-layout-kind="wrap"]) { flex-wrap:wrap;align-items:center; }
:where(.kami-root [data-kami-layout-kind="grid"]) { display:grid;grid-template-columns:repeat(var(--kami-layout-columns,auto-fit),minmax(min(100%,var(--kami-layout-min,14em)),1fr)); }
:where(.kami-root [data-kami-layout-kind="split"]) { flex-wrap:wrap; }
:where(.kami-root [data-kami-layout-kind="split"]>*) { flex:1 1 var(--kami-layout-min,18em); }
:where(.kami-root [data-kami-layout-kind="center"]) { justify-content:center;align-items:center; }
:where(.kami-root [data-kami-slot="decoration"]) { pointer-events:none; }
:where(.kami-root[data-kami-container="embedded"]) { position:relative;min-width:0;max-width:100%; }
:where(.kami-root[data-kami-container="dialog"]) { position:relative;width:100%;height:auto;min-height:0;margin:0;pointer-events:auto; }
:where(.kami-root[data-kami-container="dialog"]>.kami-shell) { display:flex;flex-direction:column;max-height:90dvh;min-height:0;margin:0; }
:where(.kami-root[data-kami-container="dialog"] .kami-body) { overflow:auto;min-height:0; }
:where(dialog.kami-ui-dialog) { border:0;padding:0;background-color:transparent;width:min(560px,calc(100vw - 24px));max-width:calc(100vw - 24px);max-height:90dvh;overflow:visible; }
:where(dialog.kami-ui-dialog::backdrop) { background-color:rgba(0,0,0,.58); }
