:where(.kami-root[data-kami-container="panel"]>.kami-drop) { position:absolute;left:var(--kami-panel-x,12px);top:var(--kami-panel-y,60px);width:var(--kami-panel-w,min(840px,calc(100% - 24px)));height:var(--kami-panel-h,min(1120px,85dvh));display:flex;flex-direction:column;max-width:calc(100% - 24px);max-height:calc(100% - 24px);pointer-events:auto; }
:where(.kami-root[data-kami-container="panel"]>.kami-drop[data-kami-open="0"]) { display:none; }
:where(.kami-root[data-kami-container="panel"]>.kami-drop>.kami-body) { flex:1 1 auto;min-height:0;overflow:auto; }
