        scopeEl.textContent=[record.world,record.scope].filter(Boolean).join(' · ');
        hide(scopeEl,false);
      }
      originEl.textContent=record.origin==='native'?'模型原生':'服务检索';
      hide(originEl,false);
      var localMap=Object.create(null);
      (Array.isArray(record.sources)?record.sources:[]).forEach(function(value){
        var source=webSearchSource(value);
        if(source&&source.id&&indexOf[source.id]){localMap[source.id]=source;}
      });
      (record.facts||[]).forEach(function(fact){
        if(!fact||typeof fact.text!=='string'){return;}
        factTotal++;
        var row=make('li','kami-fact');
        row.appendChild(make('span','kami-fact-n',String(factTotal)));
        var text=make('span','kami-fact-text',fact.text);
        /* 来源标记放进正文里（不是并列的第三个格子）：外层是两列网格，
           多一个子元素会被挤到下一行去。 */
        var ids=(Array.isArray(fact.source_ids)?fact.source_ids:[]).filter(function(id,i,list){return localMap[id]&&list.indexOf(id)===i;});
        if(ids.length){
          var marks=make('span','kami-fact-src');
          ids.forEach(function(id){
            var source=localMap[id];
            var mark=make('a','kami-src-mark','['+indexOf[id]+']');
            mark.href=source.url;
            mark.target='_blank';
            mark.rel='noopener noreferrer';
            mark.setAttribute('title',source.title+' · '+source.url);
            marks.appendChild(mark);
          });
          text.appendChild(marks);
        }
        row.appendChild(text);
        factsEl.appendChild(row);
        if(typeof fact.note==='string'&&fact.note){factsEl.appendChild(make('li','kami-fact-note kami-card-note',fact.note));}
      });
      if(!(record.facts||[]).length){
        var reason=record.status==='not_found'?'本次没有找到可用资料。':record.status==='budget_exceeded'?'资料超过本轮长度预算，未加入新事实。':'本次没有需要补充的新事实。';
        hide(emptyEl,false);emptyEl.textContent=reason;
      }
    });
    order.forEach(function(id,i){srcList.appendChild(sourceChip(merged[id],i+1));});
    hide(srcBox,order.length===0);
    countEl.textContent=factTotal+' 条';
    root.setAttribute('data-search-ready','1');
    root.setAttribute('data-search-sources',String(order.length));
  }

  async function boot(attempt){
    if(disposed){return;}
    var current=find('getCurrentMessageId'),messages=find('getChatMessages');
    if(!current||!messages){if(attempt<8){retry=setTimeout(function(){boot(attempt+1);},50);return;}countEl.textContent='未能读取';hide(emptyEl,false);emptyEl.textContent='无法读取本楼的搜索资料。';return;}
    try{
      var id=await current();
      if(!Number.isInteger(Number(id))||Number(id)<0){throw Error('Invalid message');}
      var rows=await messages(String(id));
      if(disposed){return;}
      var row=rows&&rows[0];
      var records=readWebSearchRecords(row&&(row.message!==undefined?row.message:row.mes));
      if(!records.length){throw Error('Invalid record');}
      show(records);
    }catch(e){
      if(!disposed){countEl.textContent='格式不完整';hide(emptyEl,false);emptyEl.textContent='本楼的搜索资料尚不完整，可在消息编辑中核对。';}
    }
  }
  window.addEventListener('pagehide',function(){disposed=true;if(retry!==null){clearTimeout(retry);}});
  boot(0);
})();
</script>
</body>
</html>

