}

/* ==========================================================================
 * 10 · 提示与空态
 * ======================================================================== */
html[data-kami-skin="civdawn"] .kami-toast {
  padding: 8px 12px;
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
