}

html[data-kami-skin="civdawn"] .kami-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 24px 16px;
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  text-align: center;
  border: 1px dashed var(--kami-line);
  border-radius: var(--kami-r-md);
  background-color: rgba(0, 0, 0, 0.08);
}
html[data-kami-skin="civdawn"] .kami-empty::before {
