  font-size: 20px;
  color: var(--kami-fg-mute);
  opacity: 0.6;
}

/* ==========================================================================
 * 11 · 语义色体系（7 种天然矿物与岩彩）
 * ======================================================================== */
/* 语义色变量映射 */
html[data-kami-skin="civdawn"] .kami-root [data-kami-kind="action"]  { --kami-kind-curr: var(--kami-kind-action); }
html[data-kami-skin="civdawn"] .kami-root [data-kami-kind="persona"] { --kami-kind-curr: var(--kami-kind-persona); }
html[data-kami-skin="civdawn"] .kami-root [data-kami-kind="plot"]    { --kami-kind-curr: var(--kami-kind-plot); }
html[data-kami-skin="civdawn"] .kami-root [data-kami-kind="info"]    { --kami-kind-curr: var(--kami-kind-info); }
html[data-kami-skin="civdawn"] .kami-root [data-kami-kind="fun"]     { --kami-kind-curr: var(--kami-kind-fun); }
html[data-kami-skin="civdawn"] .kami-root [data-kami-kind="nsfw"]    { --kami-kind-curr: var(--kami-kind-nsfw); }
