/* 语义徽章与标签（出现处 3） */
html[data-kami-skin="civdawn"] .kami-badge[data-kami-kind="action"],
html[data-kami-skin="civdawn"] .kami-chip[data-kami-kind="action"] {
  border-color: var(--kami-kind-action);
  color: var(--kami-kind-action);
}
html[data-kami-skin="civdawn"] .kami-badge[data-kami-kind="persona"],
html[data-kami-skin="civdawn"] .kami-chip[data-kami-kind="persona"] {
  border-color: var(--kami-kind-persona);
  color: var(--kami-kind-persona);
}
html[data-kami-skin="civdawn"] .kami-badge[data-kami-kind="plot"],
html[data-kami-skin="civdawn"] .kami-chip[data-kami-kind="plot"] {
  border-color: var(--kami-kind-plot);
  color: var(--kami-kind-plot);
}
html[data-kami-skin="civdawn"] .kami-badge[data-kami-kind="info"],
html[data-kami-skin="civdawn"] .kami-chip[data-kami-kind="info"] {
  border-color: var(--kami-kind-info);
  color: var(--kami-kind-info);
}
html[data-kami-skin="civdawn"] .kami-badge[data-kami-kind="fun"],
html[data-kami-skin="civdawn"] .kami-chip[data-kami-kind="fun"] {
  border-color: var(--kami-kind-fun);
  color: var(--kami-kind-fun);
}
html[data-kami-skin="civdawn"] .kami-badge[data-kami-kind="nsfw"],
html[data-kami-skin="civdawn"] .kami-chip[data-kami-kind="nsfw"] {
  border-color: var(--kami-kind-nsfw);
  color: var(--kami-kind-nsfw);
}
html[data-kami-skin="civdawn"] .kami-badge[data-kami-kind="other"],
html[data-kami-skin="civdawn"] .kami-chip[data-kami-kind="other"] {
  border-color: var(--kami-kind-other);
  color: var(--kami-kind-other);
}

/* 语义卡片左侧凿刻标记线（出现处 4） */
html[data-kami-skin="civdawn"] .kami-card[data-kami-kind="action"],
html[data-kami-skin="civdawn"] .kami-item[data-kami-kind="action"] {
  border-left: var(--kami-accent-mark) solid var(--kami-kind-action);
}
html[data-kami-skin="civdawn"] .kami-card[data-kami-kind="persona"],
html[data-kami-skin="civdawn"] .kami-item[data-kami-kind="persona"] {
  border-left: var(--kami-accent-mark) solid var(--kami-kind-persona);
}
html[data-kami-skin="civdawn"] .kami-card[data-kami-kind="plot"],
html[data-kami-skin="civdawn"] .kami-item[data-kami-kind="plot"] {
  border-left: var(--kami-accent-mark) solid var(--kami-kind-plot);
}
html[data-kami-skin="civdawn"] .kami-card[data-kami-kind="info"],
html[data-kami-skin="civdawn"] .kami-item[data-kami-kind="info"] {
  border-left: var(--kami-accent-mark) solid var(--kami-kind-info);
}
html[data-kami-skin="civdawn"] .kami-card[data-kami-kind="fun"],
html[data-kami-skin="civdawn"] .kami-item[data-kami-kind="fun"] {
