  display: block;
  width: 100%;
  border: 0;
}

/* 注释标记 ⓘ：行内记号（要能点）与右上角角标两种形态 */
html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note-mark] {
