}

html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note][hidden] { display: none; }

/* 面板条目卡的 emoji 角标（契约 §4.2 的 .kami-badge 机制）：钉角、不占宽 */
html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge {
  position: absolute;
  top: 1px;
  right: 3px;
  left: auto;
  z-index: 2;
  padding: 0;
  border: 0;
  background: transparent;
  font-size: var(--kami-fs-xs);
  line-height: 1.2;
  color: var(--kami-fg-mute);
  pointer-events: none;
}

html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="tl"],
html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 3px;
}

html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="br"],
html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 1px;
}

/* 上/下角标占高不占宽：给条目卡补对应的内边距 */
html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
