}

html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-lg-y) + 0.4em);
}

/* 非当前模型的条目：锁死（脚本写原生 disabled） */
html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled],
html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover,
html[data-kami-skin="crt80s"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:active {
