  transform: none;
  opacity: .42;
  color: var(--kami-fg-mute);
  font-weight: var(--kami-fw);
  cursor: not-allowed;
}

/* 窄屏兜底：脚本还没写入 data-kami-layout 时按贴底抽屉处理（几何骨架例外，与兜底皮肤同款） */
@media (max-width: 768px) {
  html[data-kami-skin="crt80s"] .kami-root .kami-drop.kami-drop:not([data-kami-layout]) {
    left: 0;
    right: 0;
    top: auto;
    bottom: 0;
    width: auto;
    height: 78%;
    max-height: 78%;
    border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
  }
}

/* ==========================================================================
 * 15 · 特效一：扫描线 + 玻璃弧面反光（身份符号）
 *      静态平铺暗线 + 顶部弧形高光 + 四角暗角；无逐帧动画、无 blur。
 *      玻璃叠在内容之上（真实 CRT 的玻璃在荧光粉前面），线宽 1px、低透明度，
 *      正文对比度按「底 + 最深扫描线」合成后仍 ≥ 4.5:1。
 * ======================================================================== */
html[data-kami-skin="crt80s"][data-kami-effects~="scan"] .kami-surface::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  background-image:
    /* 玻璃弧面高光：顶部一道横向弧光，越往下越快消失 */
    radial-gradient(120% 34% at 50% -6%, rgba(255, 255, 255, 0.085) 0%, rgba(255, 255, 255, 0) 62%),
    /* 四角暗角：玻璃屏的曲率阴影 */
    radial-gradient(140% 110% at 50% 46%, rgba(0, 0, 0, 0) 62%, rgba(0, 0, 0, calc(.22 * var(--kami-crt-scan-alpha) / 100)) 100%),
    /* 扫描线：1px 暗线平铺，线距可调 */
    repeating-linear-gradient(to bottom,
      rgba(0, 0, 0, calc(.15 * var(--kami-crt-scan-alpha) / 100)) 0 1px,
      transparent 1px var(--kami-crt-scan-gap));
}

/* ==========================================================================
 * 16 · 特效二：磷光辉光（text-shadow / box-shadow，静态，无逐帧 filter）
 * ======================================================================== */
html[data-kami-skin="crt80s"][data-kami-effects~="phosphor"] .kami-title,
html[data-kami-skin="crt80s"][data-kami-effects~="phosphor"] .kami-card-title {
  text-shadow: 0 0 calc(var(--kami-glow-size) * 1.2) var(--kami-glow);
}

html[data-kami-skin="crt80s"][data-kami-effects~="phosphor"] .kami-dot[data-kami-on="1"] {
  box-shadow: 0 0 calc(var(--kami-glow-size) * 1.6) var(--kami-glow);
}

html[data-kami-skin="crt80s"][data-kami-effects~="phosphor"] .kami-btn--primary {
  box-shadow: 0 0 calc(var(--kami-glow-size) * 1.4) var(--kami-glow);
}

/* ==========================================================================
 * 17 · 特效三：网格地平线（静态透视装饰，conic 射线 + 横向扫描线收窄）
 *      挂在组件底部 42% 的 ::after 上，透明度受参数控制，默认关。
 * ======================================================================== */
html[data-kami-skin="crt80s"][data-kami-effects~="grid"] .kami-surface::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 42%;
  z-index: 5;
  pointer-events: none;
  opacity: calc(.9 * var(--kami-crt-grid-alpha) / 100);
  background-image:
    /* 横向线：越靠近地平线越密（三层不同间距叠加近似透视压缩） */
    repeating-linear-gradient(to top, var(--kami-accent-line) 0 1px, transparent 1px 22px),
    repeating-linear-gradient(to top, var(--kami-accent-line) 0 1px, transparent 1px 13px),
    /* 纵向射线：从底部中心的消失点向上发散 */
    repeating-conic-gradient(from -86deg at 50% 118%, var(--kami-accent-line) 0deg .8deg, transparent .8deg 12deg);
  -webkit-mask-image: linear-gradient(to top, #000 0%, rgba(0, 0, 0, .45) 46%, transparent 100%);
  mask-image: linear-gradient(to top, #000 0%, rgba(0, 0, 0, .45) 46%, transparent 100%);
}

/* 网格特效在亮档用深琥珀线（亮底上亮线看不见） */
html[data-kami-skin="crt80s"][data-kami-scheme="light"][data-kami-effects~="grid"] .kami-surface::after {
  background-image:
    repeating-linear-gradient(to top, var(--kami-line-strong) 0 1px, transparent 1px 22px),
    repeating-linear-gradient(to top, var(--kami-line-strong) 0 1px, transparent 1px 13px),
    repeating-conic-gradient(from -86deg at 50% 118%, var(--kami-line-strong) 0deg .8deg, transparent .8deg 12deg);
}

@keyframes kami-crt-scan {
  0% { transform: translateY(-100%); }
  100% { transform: translateY(100%); }
}
html[data-kami-skin="crt80s"][data-kami-effects~="scan"] .kami-surface::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; height: 15%;
  background: linear-gradient(to bottom, transparent, rgba(255,255,255,0.1), transparent);
  pointer-events: none;
  animation: kami-crt-scan 4s linear infinite;
  z-index: 999;
}
html[data-kami-skin="crt80s"][data-kami-effects~="scan"][data-kami-motion="calm"] .kami-surface::before,
html[data-kami-skin="crt80s"][data-kami-effects~="scan"][data-kami-motion="off"] .kami-surface::before {
  animation: none !important;
  display: none;
}
@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="crt80s"][data-kami-effects~="scan"] .kami-surface::before {
    animation: none !important;
    display: none;
  }
}

/* markdown：强调与插图（2026-09-24 补齐 —— 覆盖矩阵原本缺这两项） */
html[data-kami-skin="crt80s"] .kami-md em { font-style: italic; color: var(--kami-accent); }
html[data-kami-skin="crt80s"] .kami-md del { color: var(--kami-fg-mute); text-decoration-thickness: 1px; }
html[data-kami-skin="crt80s"] .kami-md img {
  display: block;
  max-width: 100%;
  margin: .6em 0;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
  box-shadow: 0 0 var(--kami-glow-size) var(--kami-accent-soft);
}


/* 列表符号：显式声明，不依赖环境继承（酒馆楼层的列表样式可能被整链重置成 none，
   皮肤只给 ::marker 上色是不够的，符号必须自己声明、自己真的画出来）。
   无序：一级 disc / 二级 circle / 三级起 square；有序：decimal → lower-alpha → lower-roman */
html[data-kami-skin="crt80s"] .kami-md ul { list-style-type: disc; }
