 *      作为面的一层背景图（永远在内容之下），无额外节点、无动画。
 * ======================================================================== */
html[data-kami-skin="gemini"][data-kami-effects~="rings"] .kami-surface {
  --kami-gem-rings: repeating-radial-gradient(circle at 100% 0%, rgba(255, 255, 255, 0.055) 0 1px, rgba(0, 0, 0, 0) 1px 20px);
}

html[data-kami-skin="gemini"][data-kami-effects~="rings"][data-kami-scheme="light"] .kami-surface {
  --kami-gem-rings: repeating-radial-gradient(circle at 100% 0%, rgba(17, 20, 28, 0.05) 0 1px, rgba(0, 0, 0, 0) 1px 20px);
}

/* ==========================================================================
 * 17 · 特效四：缓慢呼吸（默认关）
 *      光谱带的亮度极慢地起伏。动效档 calm / off 与 prefers-reduced-motion 下整条停帧。
 * ======================================================================== */
html[data-kami-skin="gemini"][data-kami-effects~="pulse"] .kami-surface::after {
  animation: kami-gem-pulse var(--kami-gem-pulse) ease-in-out infinite alternate;
}

@keyframes kami-gem-pulse {
  from { opacity: .55; }
  to { opacity: 1; }
}

html[data-kami-skin="gemini"][data-kami-effects~="pulse"][data-kami-motion="calm"] .kami-surface::after,
html[data-kami-skin="gemini"][data-kami-effects~="pulse"][data-kami-motion="off"] .kami-surface::after {
  animation: none !important;
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="gemini"][data-kami-effects~="pulse"] .kami-surface::after {
    animation: none !important;
    opacity: 1;
  }
}

/* ==========================================================================
 * 18 · markdown：强调 / 删除线 / 插图 / 列表符号
 * ======================================================================== */
html[data-kami-skin="gemini"] .kami-md em { font-style: italic; color: var(--kami-fg); }
html[data-kami-skin="gemini"] .kami-md del { color: var(--kami-fg-mute); text-decoration-thickness: 1px; }

html[data-kami-skin="gemini"] .kami-md img {
  display: block;
  max-width: 100%;
  margin: .7em 0;
  border-radius: var(--kami-r-xs);
  box-shadow: var(--kami-shadow-sm);
}

/* 列表符号：显式声明，不依赖环境继承（酒馆楼层的列表样式可能被整链重置成 none，
   皮肤只给 ::marker 上色是不够的，符号必须自己声明、自己真的画出来）。
   无序：一级 disc / 二级 circle / 三级起 square；有序：decimal → lower-alpha → lower-roman */
html[data-kami-skin="gemini"] .kami-md ul { list-style-type: disc; }
html[data-kami-skin="gemini"] .kami-md ul ul { list-style-type: circle; }
html[data-kami-skin="gemini"] .kami-md ul ul ul { list-style-type: square; }
html[data-kami-skin="gemini"] .kami-md ol { list-style-type: decimal; }
html[data-kami-skin="gemini"] .kami-md ol ol { list-style-type: lower-alpha; }
html[data-kami-skin="gemini"] .kami-md ol ol ol { list-style-type: lower-roman; }
html[data-kami-skin="gemini"] .kami-md li::marker { color: var(--kami-fg-mute); }
html[data-kami-skin="gemini"] .kami-md li li::marker { color: var(--kami-line-strong); }

/* ==========================================================================
 * 19 · 特效页说明（.kami-field 里的那枚 .kami-sub）：375px 窄屏必须能换行读全。
 *      结构层的 .kami-sub 是 white-space:nowrap（标题栏计数确实要单行），
 *      这里只对「字段标签里的说明」这一处放开，不碰标题栏 / 页脚的。
 * ======================================================================== */
html[data-kami-skin="gemini"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-field .kami-field-label .kami-sub {
