 * —— 用色（这是本皮肤唯一的彩色，面积远低于 5%，主调仍是炭黑 × 纯白）——
 *   · 七个 data-kami-kind 各一个色相，只落在「徽章文字 + 一枚 4×10 实心小方块」上；
 *   · 另用青玉一枚做焦点环与「使用中 / 当前」胶囊（不另开第八个色相）；
 *   · 底色、正文、面板一律不上色；不用渐变（平面材料）。
 *   · 每个色相给两套取值，**按背景深浅**切，不按 scheme 切：
 *       深底（炭）＝亮级 ｜ 浅底（黏土白）＝暗级
 *     亮级七个色相对炭底实测 5.89–5.93；暗级七个对白底实测 4.97–5.03 ——
 *     故意压在同一条窄带里，七个放一起不打架（做法见 §1 语义色那段注释）。
 *
 * 纯 CSS：无 JS、无外部资源、无 url()、无 @import、无 vh、无 position:fixed 铺满。
 * 这套皮肤不用 filter / backdrop-filter：平面材料不需要模糊。
 * ========================================================================== */

/* ==========================================================================
 * 1 · 令牌
 * --------------------------------------------------------------------------
 * 默认（暗色方案）：底板 = 炭黑，压在上面的面 = 黏土白，强调 = 反相墨块。
 * 与参考图同一套：纯黑底、纯白面。
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-root {
  /* —— 风格性文案令牌（契约 §3.7：只此三处） —— */
  --kami-label-think-title: 思绪;
  --kami-label-think-title-open: 思绪展开;
  --kami-label-options-title: 抉择;

  /* —— 色彩：纯无彩色，只有明度差。全部实心 hex，不用半透明 —— */
  --kami-fg: #ecebe8;            /* 炭底上的主文字 */
  --kami-fg-dim: #c6c5c1;
  --kami-fg-mute: #a5a4a0;       /* 对 #202024 是 6.2:1 */
  --kami-accent: #f2f1ee;        /* 强调 = 黏土白（炭底上） */
  --kami-accent-fg: #16161a;     /* 黏土白 / 反相墨块上的字 */
  --kami-accent-soft: #2b2b30;
  --kami-accent-line: #6e6e78;   /* 强调描边：对底板 3.1:1，控件边够用 */

  --kami-bg: #131316;            /* 面板底板：纯炭黑 */
  --kami-bg-soft: #202024;       /* 控件常态底（按钮 / 输入框 / 未选中卡） */
  --kami-card: #1e1e22;          /* 面板里的卡片面 */
  --kami-card-2: #17171b;        /* 卡片内部正文块 */
  --kami-card-hover: #2a2a2e;    /* 悬停底必须不透明 */
  --kami-line: #37373d;          /* 1px 实线：对底板 1.6:1，只做分隔 */
  --kami-line-strong: #6e6e78;   /* 需要被看见的边（控件描边）：3.1:1 */
  --kami-t1: rgba(236, 235, 232, .04);
  --kami-t2: rgba(236, 235, 232, .08);
  --kami-t3: rgba(236, 235, 232, .17);
  --kami-warn: #ff9a94;          /* 唯一有色相的值，只做警示 */
  --kami-shadow: 0 2px 0 #08080a;   /* 极短、硬边的一档，不做发糊的软阴影 */
  --kami-shadow-sm: 0 1px 0 #08080a;
  --kami-blur: 0px;              /* 平面皮肤不用玻璃 */

  /* —— 黏土白那一片（压在炭底上的亮面） —— */
  --kami-clay-surface: #ecebe8;
  --kami-clay-surface-flat: #e6e5e1;
  --kami-clay-plate: #f2f1ee;
  --kami-clay-plate-flat: #f2f1ee;
  --kami-clay-sink: #d9d8d4;     /* 黏土白里的凹槽 */
  --kami-clay-hover: #f7f6f3;
  --kami-clay-ink: #16161a;      /* 黏土白上的主文字：15.1:1 */
  --kami-clay-ink-dim: #3f3f45;  /* 9.1:1 —— 次要文字也过 4.5 */
  --kami-clay-ink-mute: #56565c; /* 6.1:1 —— 最弱文字也过 4.5 */
  --kami-clay-line: #c3c2be;     /* 黏土白上的 1px 实线 */
  --kami-clay-line-strong: #62626a;
  --kami-clay-t1: rgba(22, 22, 26, .04);
  --kami-clay-t2: rgba(22, 22, 26, .08);
  --kami-clay-t3: rgba(22, 22, 26, .17);
  --kami-clay-accent: #16161a;   /* 亮面上的强调 = 反相墨块 */
  --kami-clay-accent-soft: rgba(22, 22, 26, .08);
  --kami-clay-accent-line: #8b8a87;
  --kami-clay-choice: #16161a;   /* 选中卡片 = 反相墨块 */

  /* —— 语义色：契约 §3.8 的七个 data-kami-kind，各给一个色相。
     用色纪律：这是这套皮肤**唯一**的彩色，只落在小徽章 / 小圆点这类「记号」上；
     底色、正文、面板一律保持黑白，彩色面积远低于 5%，主调仍是炭黑 × 纯白。

     和谐做法：固定饱和度 48%，但**不**套同一个 HSL 明度 —— 而是让七个色相去命中
     同一个目标相对亮度（同一 HSL L 的不同色相，人眼看着深浅差很多，黄和蓝能差 20 个 L*，
     只有锁定亮度才是真正的「同一档」）。实测：这七个对炭底的比值全落在 5.18–5.22，
     反相那一套对白底的全落在 4.97–5.03 —— 彼此不打架，也不会一个新一个旧。 */
  --kami-kind-action: #cb8e6b;   /* 行动 · 陶橙 */
  --kami-kind-fun: #b29b3f;      /* 搞笑 · 暗金 */
  --kami-kind-plot: #3daf85;     /* 推进 · 青玉 */
  --kami-kind-info: #5fa4c7;     /* 信息 · 钢蓝 */
  --kami-kind-persona: #be87d5;  /* 性格 · 兰紫 */
  --kami-kind-nsfw: #d484a2;     /* nsfw · 玫红 */
  --kami-kind-other: var(--kami-fg-dim);
  /* 焦点环 / 「使用中 · 当前」标记：复用青玉那一枚，不另开第八个色相 */
  --kami-kind-focus: #3daf85;

  /* —— 布局与尺寸：大圆角（不胶囊化一切）＋ 一条 4px 步进的间距梯 —— */
  --kami-r-xs: 8px;
  --kami-r-sm: 12px;
  --kami-r-md: 16px;
  --kami-r-lg: 22px;
  --kami-r-pill: 999px;
  --kami-panel-r: 24px;          /* 面板 = 参考图那块圆角方板；抽屉按它上圆下方 */

  --kami-border-w: 1px;          /* 「要看得见的边」一律 1px 实线，不用投影 */
  /* —— 内边距阶梯：一律 4px 步进，且「圆角越大、内边距越大」——
     实测口径：把**文字墨水盒**（不是 padding 盒）离圆角内缘的距离量出来，
     减掉 0.293×半径（半径 r 的圆角在 45° 处离外角 0.293r），正值＝肉眼看得见的余量。
     上一版 12/8 与 16/12 两档太小：-.kami-card（r=16）文字离圆角只剩 11.3px、
     .kami-shell（r=30 的歪 blob）只剩 5.2px、引导选项卡（r=16）7.3px ——
     用户看到的就是「字和圆角贴到一起」。现在抬到 14/10 与 20/16：
     r=16 的容器 ≥14px 余量，r=30 的 blob ≥11px，控件（按钮 / 徽章）≥14px 水平余量。 */
  --kami-pad-x: 14px;            /* 控件内边距（按钮 / 徽章 / 分段片），手机 ≥ 10，见 §19 */
  --kami-pad-y: 10px;
  --kami-pad-lg-x: 20px;         /* 容器内边距（卡片 / 头部 / tab 行 / 正文 / 页脚共用它） */
  --kami-pad-lg-y: 16px;
  --kami-gap: 8px;               /* 同行同列相邻控件：一律 8px，不混用 */
  --kami-gap-lg: 12px;           /* 卡片与卡片之间：一律 12px */
  --kami-row-h: 42px;            /* 可点区域 ≥ 40px（手机 44，见 §19） */
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 15rem;
  --kami-panel-w: 840px;
  --kami-panel-h: 1120px;
  --kami-list-dir: column;
  --kami-justify: stretch;

  /* —— 文本与排版：系统无衬线，标题不加衬线不加等宽，字距略开，不做全大写 —— */
  --kami-fs-scale: 1;
  --kami-fs: calc(15px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .8);
  --kami-fs-sm: calc(var(--kami-fs) * .9);
  --kami-fs-lg: calc(var(--kami-fs) * 1.12);
  --kami-lh: 1.62;
  --kami-ls: .012em;
  --kami-ls-title: .03em;
  --kami-font: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans SC", sans-serif;
  --kami-font-title: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans SC", sans-serif;
  --kami-font-mono: ui-monospace, SFMono-Regular, "Cascadia Mono", Consolas, "Roboto Mono", "DejaVu Sans Mono", monospace;
  --kami-fw: 400;
  --kami-fw-title: 700;          /* 选中 / 标题靠字重就能认出来，不只靠颜色 */
  --kami-title-transform: none;

  /* —— 装饰与特效：平面皮肤没有纹理，也没有形体偏差 —— */
  --kami-gb-grain: 4;
  --kami-gb-sheen: 40;
  --kami-gb-breathe: 55;   /* 呼吸幅度（%），与 skin.json 的 params.breathe 对应；缺了它滑杆写了也没处读 */
  --kami-texture:
    radial-gradient(circle at 22% 14%, rgba(255, 255, 255, calc(.14 * var(--kami-gb-grain) / 100)) 0 .7px, rgba(0, 0, 0, 0) 1.6px),
    radial-gradient(circle at 71% 43%, rgba(0, 0, 0, calc(.16 * var(--kami-gb-grain) / 100)) 0 .8px, rgba(0, 0, 0, 0) 1.7px),
    radial-gradient(circle at 38% 76%, rgba(255, 255, 255, calc(.12 * var(--kami-gb-grain) / 100)) 0 .6px, rgba(0, 0, 0, 0) 1.5px),
    radial-gradient(circle at 88% 88%, rgba(0, 0, 0, calc(.14 * var(--kami-gb-grain) / 100)) 0 .7px, rgba(0, 0, 0, 0) 1.6px);
  --kami-glow: #ffffff;
  --kami-glow-size: 0px;
  --kami-surface-clip: none;
  --kami-accent-mark: 3px;       /* 装饰性标记宽度（本皮肤当前未使用；引导向导的选中底线吃它） */

  /* —— 动画与过渡：干净利落，短 —— */
  --kami-dur-fast: .1s;
  --kami-dur: .16s;
  --kami-dur-slow: .3s;
  --kami-ease: cubic-bezier(.2, .7, .24, 1);
  --kami-ease-out: cubic-bezier(.16, 1, .3, 1);
  --kami-enter-y: 2px;
  --kami-enter-scale: .97;
  --kami-stagger: 26ms;

  box-sizing: border-box;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  font-weight: var(--kami-fw);
  line-height: var(--kami-lh);
  letter-spacing: var(--kami-ls);
  font-variant-numeric: tabular-nums;
  text-align: left;
  text-rendering: optimizeLegibility;
  word-break: break-word;
  -webkit-tap-highlight-color: transparent;
}
/* —— 语义色：**只有消息楼层是浅底时才用暗级** ——
   2026-09-26 用户裁定：**暗色方案下消息楼层也是炭底**（「默认暗色情况下，面板应该是黑色的、字体是白的，
   比如正文前端就该是黑底白字」）。所以那套「按 data-kami-comp 挂」的写法改了：
   暗色方案下消息楼层与面板同底，直接用 :root 那套亮级；只有亮色方案（楼层是黏土白）才换成暗级。
   七个色相各改一次，全部实测 ≥ 4.97:1。 */
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) {
  margin: 10px 0 8px;
  max-width: var(--kami-maxw);
}
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) {
  --kami-kind-action: #7f4b2d;
  --kami-kind-fun: #645723;
  --kami-kind-plot: #23634c;
  --kami-kind-info: #2a5d77;
  --kami-kind-persona: #7f379e;
  --kami-kind-nsfw: #963558;
  --kami-kind-other: var(--kami-fg-dim);
  --kami-kind-focus: #23634c;
}
html[data-kami-skin="grokbot"] .kami-root *,
html[data-kami-skin="grokbot"] .kami-root *::before,
html[data-kami-skin="grokbot"] .kami-root *::after { box-sizing: border-box; }
html[data-kami-skin="grokbot"] .kami-root button,
html[data-kami-skin="grokbot"] .kami-root input,
html[data-kami-skin="grokbot"] .kami-root select,
html[data-kami-skin="grokbot"] .kami-root textarea {
  font: inherit;
  color: inherit;
  letter-spacing: inherit;
  margin: 0;
}
html[data-kami-skin="grokbot"] .kami-root button { -webkit-appearance: none; appearance: none; }
html[data-kami-skin="grokbot"] .kami-root [hidden] { display: none !important; }
html[data-kami-skin="grokbot"] .kami-root img { max-width: 100%; }
html[data-kami-skin="grokbot"] .kami-root .kami-deco { display: none; }
/* 这套皮肤不声明 decor：就算槽位被别的皮肤升级过，也不再画任何东西 */
html[data-kami-skin="grokbot"] .kami-root .kami-d20::before,
html[data-kami-skin="grokbot"] .kami-root .kami-d20::after { content: none; }

/* 焦点：2px 实线 + 2px 偏移。用青玉那一枚色相（--kami-kind-focus），
   它在炭底与黏土白底上都 ≥ 5:1，一眼能找到焦点在哪 —— 这是这套皮肤里
   少数几个「颜色在做功能」的地方之一，不是装饰。 */
html[data-kami-skin="grokbot"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-kind-focus);
  outline-offset: 2px;
  border-radius: var(--kami-r-xs);
}

/* ==========================================================================
 * 2 · 表面：底板 = 纯炭黑方块，本体 = 纯黏土白 blob
 * --------------------------------------------------------------------------
 * 零渐变、零软阴影。本体与底板之间用 1px 实线 + 一档 2px 硬边投影分开，
 * 不是为了「体积」，是为了在深色酒馆里把块切干净。
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-surface {
  position: relative;
  isolation: isolate;
  clip-path: var(--kami-surface-clip);
}

/* 面板：纯炭黑 + 1px 实线边（参考图那块圆角方板） */
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-drop {
  background-color: var(--kami-bg);
  background-image: none;
  color: var(--kami-fg);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-panel-r);
  box-shadow: var(--kami-shadow);
}
/* 消息楼层里的组件外壳：纯黏土白 blob —— 四角不等值就是「歪」的那个形 */
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-shell {
  background-color: var(--kami-clay-surface);
  background-image: none;
  color: var(--kami-clay-ink);
  /* 「歪 blob」＝ 四角不等值的圆角。参考图那团土上缘偏平、右下兜得更满，
     所以右下半径给到最大、左下收小。形状一律用 CSS 造，不搬参考 SVG 的路径数据。 */
  border: var(--kami-border-w) solid rgba(0, 0, 0, .16);
  border-radius: 30px 24px 34px 20px / 26px 22px 30px 20px;
  box-shadow: var(--kami-shadow);
}
/* 面板里的卡片式容器：规整圆角，不走 blob 的歪 */
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-shell {
  background-color: var(--kami-bg-soft);
  background-image: none;
  color: var(--kami-fg);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  box-shadow: none;
}
html[data-kami-skin="grokbot"] .kami-shell { display: block; }

/* —— 炭字覆盖：凡是有黏土白底的地方，文字 / 线条 / 叠加层一并换成深色一套 ——
   这样上面那套「按深底定的令牌」在黏土白本体上依然读得清（契约 §2 第 7 条）。

   ⚠️ 这条规则必须点名 .kami-shell / .kami-surface：组件里到处都有**显式**的
   `color: var(--kami-fg)`（.kami-title / .kami-sub / .kami-field-label / .kami-chev …），
   显式值压过继承，所以只给外壳写 `color` 是没用的 ——
   真事故：消息 iframe 里外壳是黏土白，.kami-title 却显式吃 --kami-fg＝#ecebe8，
   于是「思绪」「抉择」两个标题成了白字压白底，肉眼完全看不见。
   教训：凡是背景是黏土白的那一层，就必须把**整套令牌**换掉，不能只靠 color 继承。

   ⚠️ 但 .kami-shell / .kami-surface 必须带 `:not([data-kami-comp="panel"],[data-kami-comp="dialog"])`：
   面板本体 `.kami-drop` 也挂着 kami-surface，不加这个限定就会把面板一起拖进
   「浅底那套」，选中标签页会变成浅字压浅底。（这是加这套色时真踩到的第二次。）

   ⚠️ 第三次：`--kami-accent-fg` 漏在翻转清单外。
   `--kami-accent` 在亮面上翻成 clay-accent＝#16161a（墨），而 `--kami-accent-fg`
   还是炭底那套的 #16161a（也是墨）—— 于是**强调底上的字和强调底同色**。
   实测（浏览器读计算样式）：皮肤管理面板「参数」页那枚分段开关，
   选中项「跟随皮肤」= 字 #16161a 压底 #16161a ＝ **1.00:1**，肉眼就是一整块黑；
   用户报的「暗色下开关背景是黑的、字体也是黑的」就是这里。
   同理受害的还有 .kami-btn.is-on / .kami-seg-item.is-on / .kami-tab[aria-selected]
   / .kami-switch 选中态 / 注释标记 hover —— 它们全都吃这一对令牌。
   修法：亮面把这一对**成对**翻过来（墨底 + 黏土白的字），不再只翻一半。 */
/* ── 2026-09-26 用户裁定：**暗色方案下消息楼层不翻黏土白，跟面板一样是炭底** ──
   （原话：「默认暗色情况下，面板应该是黑色的、字体是白的，比如正文前端就该是黑底白字」。）
   做法：把「黏土白那一族」整体**指回炭黑那一族**，一处改、处处生效 ——
   几十条组件规则读的都是 --kami-clay-*（按钮 / 分段 / 徽章 / 开关 / 正文块 / 空态…），
   逐条加 [data-kami-scheme="dark"] 既啰嗦又必漏。
   ⚠️ 这里不会成环：本作用域里 --kami-fg / --kami-bg-soft / --kami-card … 还是 :root 那套炭黑值，
   被它们赋值的才是 clay 那一族。反过来若让 clay 去赋 --kami-fg（下面的亮色块就是那么写的），
   两族互指就会双双失效 —— 所以**下面那两块必须只留给亮色方案**。 */
html[data-kami-skin="grokbot"][data-kami-scheme="dark"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) {
  --kami-clay-surface: var(--kami-bg-soft);
  --kami-clay-surface-flat: var(--kami-bg-soft);
  --kami-clay-plate: var(--kami-card);
  --kami-clay-plate-flat: var(--kami-card);
  --kami-clay-sink: var(--kami-card-2);
  --kami-clay-hover: var(--kami-card-hover);
  --kami-clay-ink: var(--kami-fg);
  --kami-clay-ink-dim: var(--kami-fg-dim);
  --kami-clay-ink-mute: var(--kami-fg-mute);
  --kami-clay-line: var(--kami-line);
  --kami-clay-line-strong: var(--kami-line-strong);
  --kami-clay-t1: var(--kami-t1);
  --kami-clay-t2: var(--kami-t2);
  --kami-clay-t3: var(--kami-t3);
  --kami-clay-accent: var(--kami-accent);
  --kami-clay-accent-soft: var(--kami-accent-soft);
  --kami-clay-accent-line: var(--kami-accent-line);
  --kami-clay-choice: var(--kami-accent);
}
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-shell,
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-surface,
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root .kami-card,
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root .kami-item,
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root .kami-card-note {
  --kami-fg: var(--kami-clay-ink);
  --kami-fg-dim: var(--kami-clay-ink-dim);
  --kami-fg-mute: var(--kami-clay-ink-mute);
  --kami-bg: var(--kami-clay-surface);
  --kami-bg-soft: var(--kami-clay-sink);
  --kami-card: var(--kami-clay-plate);
  --kami-card-2: var(--kami-clay-sink);
  --kami-card-hover: var(--kami-clay-hover);
  --kami-line: var(--kami-clay-line);
  --kami-line-strong: var(--kami-clay-line-strong);
  --kami-t1: var(--kami-clay-t1);
  --kami-t2: var(--kami-clay-t2);
  --kami-t3: var(--kami-clay-t3);
  --kami-accent: var(--kami-clay-accent);
  --kami-accent-fg: var(--kami-clay-plate);
  --kami-accent-soft: var(--kami-clay-accent-soft);
  --kami-accent-line: var(--kami-clay-accent-line);
}
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root .kami-md,
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root .kami-raw {
  --kami-fg: var(--kami-clay-ink);
  --kami-fg-dim: var(--kami-clay-ink-dim);
  --kami-fg-mute: var(--kami-clay-ink-mute);
  --kami-bg: var(--kami-clay-surface);
  --kami-bg-soft: var(--kami-clay-sink);
  --kami-card-2: var(--kami-clay-sink);
  --kami-line: var(--kami-clay-line);
  --kami-line-strong: var(--kami-clay-line-strong);
  --kami-t1: var(--kami-clay-t1);
  --kami-t2: var(--kami-clay-t2);
  --kami-t3: var(--kami-clay-t3);
  --kami-accent: var(--kami-clay-accent);
  --kami-accent-fg: var(--kami-clay-plate);
  --kami-accent-soft: var(--kami-clay-accent-soft);
  --kami-accent-line: var(--kami-clay-accent-line);
}

/* ==========================================================================
 * 3 · 头部 / 标题 / 状态点
 * --------------------------------------------------------------------------
 * 四段（头部 / tab 行 / 正文 / 页脚）左右内边距全部 = --kami-pad-lg-x，
 * 于是它们在面板里对齐成同一条竖线。
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}
html[data-kami-skin="grokbot"] .kami-head:not(.kami-collapse-head) {
  border-bottom: var(--kami-border-w) solid var(--kami-line);
}
html[data-kami-skin="grokbot"] .kami-collapse-head { cursor: pointer; user-select: none; }
html[data-kami-skin="grokbot"] .kami-head[data-kami-drag] { cursor: grab; }
html[data-kami-skin="grokbot"] .kami-head[data-kami-drag] .kami-icon-btn { cursor: pointer; }

/* —— 状态点：一枚圆角方块 ——
   2026-09-21 用户裁定「删掉所有眼睛，一处不留」：原来这里是「关着＝一只瞳孔、
   开着＝并排两只斜胶囊」，现在两态只靠**形状与明度**区分（方块 / 压亮），
   一个眼球都不画。面板里那一枚换成黏土白（底板更暗，抬一档才看得见）。 */
html[data-kami-skin="grokbot"] .kami-dot {
  flex: none;
  width: 13px;
  height: 13px;
  border: 0;
  border-radius: 4px;
  background-color: var(--kami-accent);
  background-image: none;
  box-shadow: none;
  transition: background-color var(--kami-dur) var(--kami-ease), transform var(--kami-dur) var(--kami-ease);
}
/* 面板里那一枚：底板更暗，点本身提亮一档 */
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-dot { background-color: var(--kami-clay-plate); }
/* 进度点容器里的点（引导向导）：一排小方块 */
html[data-kami-skin="grokbot"] .kami-root .kami-dots .kami-dot {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background-color: var(--kami-line-strong);
}
html[data-kami-skin="grokbot"] .kami-root .kami-dots .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  transform: scale(1.25);
}

/* 标题：系统无衬线、字距略开、不大写、不加投影（平面材料不发光） */
html[data-kami-skin="grokbot"] .kami-title {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls-title);
  text-transform: var(--kami-title-transform);
  color: var(--kami-fg);
}
html[data-kami-skin="grokbot"] .kami-head .kami-sub {
  flex: none;
  min-width: 0;
  padding: 2px 8px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.5;
  letter-spacing: .02em;
  white-space: nowrap;
}
html[data-kami-skin="grokbot"] .kami-foot .kami-sub,
html[data-kami-skin="grokbot"] .kami-card-note {
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-xs);
  letter-spacing: .02em;
}
html[data-kami-skin="grokbot"] .kami-actions {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-left: auto;
  flex: none;
}

/* ==========================================================================
 * 4 · 按钮：一块实色，不叠高光不叠投影
 * --------------------------------------------------------------------------
 * 常态 = --kami-bg-soft（#202024，对底板 1.5:1，靠 1px 实线边把它切出来）
 * 悬停 = --kami-card-hover（#2a2a2e，明显跳一档）
 * 按下 / 选中 = 反相墨块（黏土白底 + 炭字，15:1）
 * 禁用 = 面压住、字降到 --kami-fg-mute（对 #202024 是 6.2:1，仍然看得清）
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-btn,
html[data-kami-skin="grokbot"] .kami-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-bg-soft);
  background-image: none;
  color: var(--kami-fg);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls);
  cursor: pointer;
  box-shadow: none;
  transition:
    color var(--kami-dur-fast) var(--kami-ease),
    background-color var(--kami-dur-fast) var(--kami-ease),
    border-color var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="grokbot"] .kami-icon-btn {
  min-width: max(var(--kami-row-h), 40px);
  min-height: max(var(--kami-row-h), 40px);
  padding: 0;
  font-size: var(--kami-icon);
  line-height: 1;
  color: var(--kami-fg-dim);
}
/* 黏土白本体里的按钮：白面上的炭字 + 炭线边 */
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn,
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-icon-btn {
  background-color: var(--kami-clay-plate);
  background-image: none;
  border-color: var(--kami-clay-line-strong);
  color: var(--kami-clay-ink);
}
/* ghost 按钮：底透明，但**描边必须是控件那一档**（--kami-line-strong，3.1:1）。
   ⚠️ 2026-09-21 用户报「压缩面板里摘要小总结条目的开关情况字样看不清」：
   这里原来给的是 --kami-line（1.6:1，那是**分隔线**用的档），加上底是透明的，
   压缩面板里那排 ghost 按钮（开启/关闭条目、存为、删除、例外楼层增删…）就只剩一行字，
   跟旁边的字段标签长得一样、看不出是个开关。底仍保持透明（ghost 的身份），只把边界找回来。 */
html[data-kami-skin="grokbot"] .kami-btn--ghost { background-color: transparent; border-color: var(--kami-line-strong); }
/* 消息楼层（黏土白本体）同款：--kami-clay-line 只有 1.4:1，控件边用 --kami-clay-line-strong */
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn--ghost { background-color: transparent; border-color: var(--kami-clay-line-strong); }
/* 主按钮 = 一块反相墨块（炭底上给白、白底上给炭），和参考图的黑白关系一致 */
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn--primary {
  background-color: var(--kami-clay-choice);
  border-color: var(--kami-clay-ink);
  color: var(--kami-clay-plate);
  font-weight: var(--kami-fw-title);
}
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn--primary {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
}
@media (hover: hover) {
  html[data-kami-skin="grokbot"] .kami-btn:hover,
  html[data-kami-skin="grokbot"] .kami-icon-btn:hover {
    background-color: var(--kami-card-hover);
    color: var(--kami-fg);
    border-color: var(--kami-line-strong);
  }
  html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn:hover,
  html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-icon-btn:hover {
    background-color: var(--kami-clay-hover);
    color: var(--kami-clay-ink);
    border-color: var(--kami-clay-ink);
  }
  html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn--primary:hover {
    background-color: var(--kami-clay-ink);
    color: var(--kami-clay-plate);
  }
  html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn--primary:hover {
    background-color: #ffffff;
    color: var(--kami-accent-fg);
  }
  html[data-kami-skin="grokbot"] .kami-icon-btn[data-kami-act="close"]:hover {
    background-color: var(--kami-warn);
    border-color: var(--kami-warn);
    color: #2b1113;
  }
}
html[data-kami-skin="grokbot"] .kami-btn:active,
html[data-kami-skin="grokbot"] .kami-icon-btn:active { transform: translateY(1px); }
html[data-kami-skin="grokbot"] .kami-btn[disabled],
html[data-kami-skin="grokbot"] .kami-icon-btn[disabled] {
  /* 禁用的字仍然要看得见：面压住、字用 --kami-fg-mute（对 #202024 是 6.2:1），不整块降透明度 */
  opacity: 1;
  background-color: var(--kami-bg-soft);
  border-color: var(--kami-line);
  color: var(--kami-fg-mute);
  cursor: default;
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn[disabled] {
  background-color: var(--kami-clay-sink);
  border-color: var(--kami-clay-line);
  color: var(--kami-clay-ink-mute);
}
/* 选中 = 反相墨块；形状上也变（边框换色 + 字加粗），不只靠颜色 */
html[data-kami-skin="grokbot"] .kami-btn.is-on,
html[data-kami-skin="grokbot"] .kami-icon-btn[aria-pressed="true"] {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn.is-on,
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-icon-btn[aria-pressed="true"] {
  background-color: var(--kami-clay-choice);
  border-color: var(--kami-clay-ink);
  color: var(--kami-clay-plate);
}
/* 成功反馈：一次性实线加粗 + 轻微位移（不循环） */
html[data-kami-skin="grokbot"] .kami-btn.is-done {
  border-color: var(--kami-accent);
  box-shadow: inset 0 0 0 2px var(--kami-accent);
  animation: kami-grokbot-pop var(--kami-dur-slow) var(--kami-ease-out) both;
}
/* —— ⚠️ 选中按钮内的文字令牌必须**成对翻**（2026-09-21 用户报障）——
   选中态的底是 `--kami-accent`，在「卡 / 条目」作用域里它被重映射成
   `--kami-clay-accent` ＝ #16161a（墨）；而卡里的文字令牌也被重映射成
   `--kami-fg` ＝ --kami-clay-ink ＝ #16161a —— **同色**，实测 1.00:1。
   受害的就是引导「模型页」那张选中卡的标题栏：黑底黑字，用户完全看不到
   （`.kami-card-head` 是 `button.kami-btn.kami-btn--ghost`，选中加 `.is-on`，
   里面的 `.kami-card-title` 显式吃 `--kami-fg`，靠继承救不回来）。
   同族历史事故见文件头 §2 那三段警告（都是「底翻了、字没翻」）。
   翻法与 `.kami-item.is-on` 同款：底是墨，字与线一并换成 `--kami-accent-fg`
   （＝强调底上的那个色，浅块 / 墨块两种情形都成立）。 */
html[data-kami-skin="grokbot"] .kami-btn.is-on,
html[data-kami-skin="grokbot"] .kami-btn[aria-pressed="true"],
html[data-kami-skin="grokbot"] .kami-icon-btn[aria-pressed="true"] {
  --kami-fg: var(--kami-accent-fg);
  --kami-fg-dim: var(--kami-accent-fg);
  --kami-fg-mute: var(--kami-accent-fg);
  --kami-line: var(--kami-accent-fg);
  --kami-line-strong: var(--kami-accent-fg);
}
html[data-kami-skin="grokbot"] .kami-root .kami-btn.is-on .kami-card-title,
html[data-kami-skin="grokbot"] .kami-root .kami-btn[aria-pressed="true"] .kami-card-title {
  color: var(--kami-accent-fg);
}
html[data-kami-skin="grokbot"] .kami-root .kami-btn.is-on .kami-chip,
html[data-kami-skin="grokbot"] .kami-root .kami-btn[aria-pressed="true"] .kami-chip {
  background-color: transparent;
  border-color: currentColor;
  color: var(--kami-accent-fg);
}

/* ==========================================================================
 * 5 · 分段切换：一枚实色凹槽 + 一块反相滑块
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-seg {
  display: inline-flex;
  gap: 3px;
  padding: 3px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-bg-soft);
  background-image: none;
  box-shadow: none;
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-seg {
  background-color: var(--kami-clay-sink);
  border-color: var(--kami-clay-line);
}
html[data-kami-skin="grokbot"] .kami-seg-item {
  border: 0;
  border-radius: var(--kami-r-pill);
  min-height: 32px;
  /* 胶囊片：内边距抬到控件那一档（14/10 的 10 给上下，左右 14），
     圆角＝半径 16，文字离圆弧留 9.3px 余量（上一版 13px 只剩 8.3）。 */
  padding: 6px var(--kami-pad-x);
  background-color: transparent;
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  letter-spacing: var(--kami-ls);
  cursor: pointer;
  transition: color var(--kami-dur-fast) var(--kami-ease), background-color var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-seg-item { color: var(--kami-clay-ink-dim); }
html[data-kami-skin="grokbot"] .kami-seg-item.is-on {
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-seg-item.is-on {
  background-color: var(--kami-clay-choice);
  color: var(--kami-clay-plate);
}
@media (hover: hover) {
  html[data-kami-skin="grokbot"] .kami-seg-item:hover:not(.is-on) { color: var(--kami-fg); }
  html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-seg-item:hover:not(.is-on) { color: var(--kami-clay-ink); }
}

/* ==========================================================================
 * 6 · 卡片 / 列表 / 网格：一块块实色面 + 1px 实线边
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-card {
  position: relative;
  display: block;
  width: 100%;
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-clay-line-strong);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-clay-plate-flat);
  background-image: none;
  color: var(--kami-clay-ink);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  box-shadow: none;
}
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  color: var(--kami-fg);
  box-shadow: none;
}
html[data-kami-skin="grokbot"] button.kami-card { cursor: pointer; }
html[data-kami-skin="grokbot"] .kami-item {
  position: relative;
  display: grid;
  grid-template-columns: 1fr;
  gap: 4px;
  width: 100%;
  cursor: pointer;
  overflow: hidden;
  transition: background-color var(--kami-dur-fast) var(--kami-ease), border-color var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="grokbot"] .kami-card-head {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  min-width: 0;
}
html[data-kami-skin="grokbot"] .kami-card-title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs-sm);
  letter-spacing: .02em;
  color: var(--kami-fg);
}
html[data-kami-skin="grokbot"] .kami-card-body {
  display: block;
  font-size: var(--kami-fs-sm);
  line-height: 1.6;
  color: var(--kami-fg-dim);
  overflow-wrap: anywhere;
  text-wrap: pretty;
}
html[data-kami-skin="grokbot"] .kami-card-note { display: block; }
html[data-kami-skin="grokbot"] .kami-item-main { flex: 1 1 auto; min-width: 0; color: var(--kami-fg); }
html[data-kami-skin="grokbot"] .kami-item-side {
  flex: none;
  margin-left: auto;
  padding-left: 6px;
  font-size: var(--kami-fs-sm);
  line-height: 1;
  color: var(--kami-fg-mute);
  transition: color var(--kami-dur-fast) var(--kami-ease);
}
/* 示例数据 = 还没被选中的一块：压暗一档、框线降到最淡，光标也不给「可点」的样子 */
html[data-kami-skin="grokbot"] .kami-item.is-demo {
  cursor: default;
  background-color: var(--kami-bg-soft);
  border-color: var(--kami-line);
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item.is-demo {
  background-color: var(--kami-clay-sink);
  border-color: var(--kami-clay-line);
  color: var(--kami-clay-ink-mute);
}
html[data-kami-skin="grokbot"] .kami-item.is-demo .kami-item-side { color: transparent; }
@media (hover: hover) {
  html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:hover {
    background-color: var(--kami-clay-hover);
    border-color: var(--kami-clay-ink);
  }
  html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-line-strong);
  }
  html[data-kami-skin="grokbot"] .kami-item:hover .kami-item-side { color: var(--kami-fg); }
}
html[data-kami-skin="grokbot"] .kami-item:active { transform: translateY(1px); }
html[data-kami-skin="grokbot"] .kami-item:focus-visible,
html[data-kami-skin="grokbot"] .kami-card:focus-visible { z-index: 2; }

html[data-kami-skin="grokbot"] .kami-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap-lg);
  align-items: stretch;
}
html[data-kami-skin="grokbot"] .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  justify-content: var(--kami-justify);
  gap: var(--kami-gap-lg);
}
html[data-kami-skin="grokbot"] .kami-grid.kami-list { display: grid; grid-auto-flow: row; }

/* ==========================================================================
 * 7 · 徽章 / 小标签：中性底色 + 该类型的一个色相
 * --------------------------------------------------------------------------
 * 用色只落在两处记号上：① 文字用该 kind 的色相；② 前面一枚实心小方块（＝记号语言）
 * 也用同一色相。底色仍是中性的 --kami-bg-soft / --kami-clay-sink，
 * 这样「文字 vs 它实际所在的那块底」的比值是可控的、可复算的（见文件头）。
 * 角标位置的 emoji 徽章不画这枚小胶囊（那里本来就只有 emoji）。
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-badge,
html[data-kami-skin="grokbot"] .kami-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  padding: 2px 9px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-bg-soft);
  background-image: none;
  font-size: var(--kami-fs-xs);
  line-height: 1.5;
  letter-spacing: .02em;
  color: var(--kami-kind-other);
  white-space: nowrap;
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-badge,
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-chip {
  background-color: var(--kami-clay-sink);
  border-color: var(--kami-clay-line);
}
html[data-kami-skin="grokbot"] .kami-chip { color: var(--kami-fg-dim); }
/* 类型记号：一枚 4×10 的实心圆角方块，和状态点是同一种元件（不再是斜胶囊眼） */
html[data-kami-skin="grokbot"] .kami-root .kami-badge[data-kami-kind]::before {
  content: "";
  flex: none;
  width: 4px;
  height: 10px;
  margin-right: 1px;
  border-radius: 1.5px;
  background-color: currentColor;
}
html[data-kami-skin="grokbot"] .kami-root .kami-badge[data-kami-corner]::before { content: none; }
html[data-kami-skin="grokbot"] .kami-root :is(.kami-badge, .kami-chip)[data-kami-kind="action"] { color: var(--kami-kind-action); }
html[data-kami-skin="grokbot"] .kami-root :is(.kami-badge, .kami-chip)[data-kami-kind="persona"] { color: var(--kami-kind-persona); }
html[data-kami-skin="grokbot"] .kami-root :is(.kami-badge, .kami-chip)[data-kami-kind="plot"] { color: var(--kami-kind-plot); }
html[data-kami-skin="grokbot"] .kami-root :is(.kami-badge, .kami-chip)[data-kami-kind="info"] { color: var(--kami-kind-info); }
html[data-kami-skin="grokbot"] .kami-root :is(.kami-badge, .kami-chip)[data-kami-kind="fun"] { color: var(--kami-kind-fun); }
html[data-kami-skin="grokbot"] .kami-root :is(.kami-badge, .kami-chip)[data-kami-kind="nsfw"] { color: var(--kami-kind-nsfw); }
html[data-kami-skin="grokbot"] .kami-root :is(.kami-badge, .kami-chip)[data-kami-kind="other"] { color: var(--kami-kind-other); }

/* ==========================================================================
 * 8 · 折叠区 / 选中态
 * --------------------------------------------------------------------------
 * 选中 = 面反相（面板里 白 / 消息层里 墨块）+ 字重 600 + 边换墨色。
 * （原来这里还有「左缘两只实心胶囊眼」当作选中标记，2026-09-21 用户裁定删除，
 *  且**没有替代画法** —— 见下面那条规则上方的说明。）
 * 选中态另有「字重加粗 + 面反相」两样非颜色差别。
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-collapse[data-kami-open="0"] > .kami-collapse-body { display: none; }
html[data-kami-skin="grokbot"] .kami-collapse[data-kami-open="1"] > .kami-collapse-body {
  display: block;
  animation: kami-grokbot-unseal var(--kami-dur-slow) var(--kami-ease) both;
}
html[data-kami-skin="grokbot"] .kami-chev {
  flex: none;
  font-size: calc(var(--kami-icon) * .82);
  line-height: 1;
  color: var(--kami-fg-dim);
  transition: transform var(--kami-dur) var(--kami-ease), color var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="grokbot"] .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev {
  transform: rotate(90deg);
  color: var(--kami-fg);
}

/* 默认选中（黏土白本体）：一块炭，白字 —— 对比 15:1 */
html[data-kami-skin="grokbot"] .kami-item.is-on,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] {
  background-color: var(--kami-clay-choice);
  background-image: none;
  border-color: var(--kami-clay-ink);
  color: var(--kami-clay-plate);
}
html[data-kami-skin="grokbot"] .kami-item.is-on .kami-item-main,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] .kami-item-main {
  color: var(--kami-clay-plate);
  font-weight: 600;
}
html[data-kami-skin="grokbot"] .kami-item.is-on .kami-card-title,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] .kami-card-title { color: var(--kami-clay-plate); }
html[data-kami-skin="grokbot"] .kami-item.is-on .kami-card-body,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] .kami-card-body { color: var(--kami-clay-sink); }
/* 选中卡是「反相墨块」（炭面），所以里面徽章的色相要换回**亮级那一套**，
   否则暗级色压在炭面上会掉到 2:1 左右。 */
html[data-kami-skin="grokbot"] .kami-item.is-on,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] {
  --kami-kind-action: #cb8e6b;
  --kami-kind-fun: #b29b3f;
  --kami-kind-plot: #3daf85;
  --kami-kind-info: #5fa4c7;
  --kami-kind-persona: #be87d5;
  --kami-kind-nsfw: #d484a2;
  --kami-kind-other: #c6c5c1;
}
html[data-kami-skin="grokbot"] .kami-item.is-on .kami-chip,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] .kami-chip {
  background-color: transparent;
  border-color: var(--kami-clay-line-strong);
  color: var(--kami-clay-sink);
}
/* 面板（炭底）里的选中条目卡：反过来 —— 一块黏土白，炭字。
   底色是浅的，所以徽章的七个色相要换回**暗级那一套**。 */
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item.is-on,
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[aria-pressed="true"] {
  background-color: var(--kami-clay-plate-flat);
  border-color: var(--kami-clay-plate-flat);
  color: var(--kami-clay-ink);
  --kami-kind-action: #7f4b2d;
  --kami-kind-fun: #645723;
  --kami-kind-plot: #23634c;
  --kami-kind-info: #2a5d77;
  --kami-kind-persona: #7f379e;
  --kami-kind-nsfw: #963558;
  --kami-kind-other: #3f3f45;
}
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item.is-on .kami-item-main,
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[aria-pressed="true"] .kami-item-main,
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item.is-on .kami-card-title,
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[aria-pressed="true"] .kami-card-title {
  color: var(--kami-clay-ink);
  font-weight: 600;
}

/* ⚠️ 2026-09-21：原来这里挂着「选中条目卡左缘那两只眼」（一条 10×13 的 ::before +
   给文字让位的 15px 左内边距）。用户裁定删掉，已整段移除，**没有替代画法** ——
   开 / 关两态现在靠三样区分：① 面反相（面板里 白 ⇄ 凹槽灰，实测对白卡 1.30:1 的填充差）；
   ② 边换成墨色（对白卡 15.79:1）；③ 字重 600。前两样是颜色与明度，第三样不是，
   所以「不只靠颜色」这条纪律仍然成立。 */
/* 没选中的条目：字降到「次要」而不是「看不清」，仍然 ≥ 4.5:1 */
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="false"] .kami-item-main { color: var(--kami-fg-dim); }

/* —— 面板里的条目卡：103 张卡看的就是「开着的这张一眼认出来」 —— */
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[aria-pressed="false"] {
  background-color: var(--kami-bg-soft);
  background-image: none;
  border-color: var(--kami-line);
}
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[aria-pressed="false"] .kami-item-main {
  color: var(--kami-fg-dim);
}
/* 非当前模型的条目：锁死。面压住、字仍看得清（对 #202024 是 6.2:1），
   光标与悬停反馈全部收掉，但不整块降透明度（那会把字一起弄糊） */
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled],
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover,
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:active {
  background-color: var(--kami-bg-soft);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: 1;
  cursor: not-allowed;
}
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled] .kami-item-main { color: var(--kami-fg-mute); }

/* —— 未选中 / 选中的卡片：边界必须看得见（第三处报障）——
   ⚠️ 面板里的卡是**套着**的：`.kami-card > .kami-card-body > .kami-grid > .kami-item.kami-card`，
   而上面那套令牌翻转对**两层都生效** —— 内外两层都吃 --kami-card，翻出来都是 #f2f1ee，
   于是内层卡的填充和外层容器**一模一样**（实测 1.00:1），边又只有 --kami-line 那一档
   （对白卡 1.6:1）—— 整张卡就这么「融」进容器里，用户报的就是这一处。
   （同一份实测里另有一条对照：面板里的皮肤卡单独贴在炭底上时是 16.42:1，看得见；
   问题只出在「卡里的卡」。）

   定调：**一档明度的填充 + 一条看得见的边**，两样都写死成 clay 令牌，不跟着翻转走 ——
     · 未选中：填充 --kami-clay-sink（凹槽那一档）＝对白卡 1.30:1、对炭底 13.00:1；
       边 --kami-clay-line-strong ＝对白卡 5.90:1、对炭底 3.20:1；两种底上都过 3:1。
     · 选中：填充仍是黏土白／墨块，但边改用墨色 --kami-clay-ink（对白卡 15.79:1），
       免得「白卡里的选中卡」也只靠填充差说话。
   开/关两态的差别**不只靠颜色**：选中态另有「字重 600」这一样（2026-09-21 起，
   原来的「左缘两只眼 + 文字左让 15px」已按用户裁定删除）。 */
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[aria-pressed="false"],
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:not(.is-on):not([aria-pressed="true"]),
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card .kami-card[data-kami-card-role="choice"]:not(.is-on):not([aria-pressed="true"]) {
  background-color: var(--kami-clay-sink);
  background-image: none;
  border-color: var(--kami-clay-line-strong);
}
/* 折叠设置是容器，沿用深浅档的正文底；不能套用按钮卡的黏土凹槽。 */
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card .kami-card:is([data-kami-card-role="container"],[data-kami-card-role="collapse"]):not(.is-on):not([aria-pressed="true"]) {
  background-color: var(--kami-card-2);
  color: var(--kami-fg);
  border-color: var(--kami-line-strong);
}
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item.is-on,
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[aria-pressed="true"] {
  border-color: var(--kami-clay-ink);
}
/* 引导面板里的「行式开关」也走同一条规矩：关态原来只有 --kami-line（对炭底 1.57:1），
   整行边界等于没有，和背景连成一片。关/开两态的**非颜色**差别另有状态文案
   （已开启 / 已关闭），所以这里只补边界，不动它的高亮。

   ⚠️ 这一条必须带 !important：引导的排版层是 `50-引导.js` 用 `#kami-guide-panel …`
   （带 id）注入的，id 特异性压过任何纯类名选择器，而契约 §4.4 又不许皮肤规则挂面板 id ——
   没有别的杠杆。取值与引导自己给开态描边用的 --kami-accent-line 在暗色下同值（#6e6e78），
   亮色下也同为 #62626a，所以开态外观一点没变，只有关态从 1.57:1 抬到 3.68:1。 */
html[data-kami-skin="grokbot"] .kami-root .kami-guide-switchrow {
  border-color: var(--kami-line-strong) !important;
}

/* 注释入口与注释正文（两块面板共用 —— 不写 #kami-preset-panel，
   否则引导面板里的 ⓘ 吃不到样式，用户已经报过这个不一致） */
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note-mark] {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5em;
  height: 1.5em;
  margin-left: 6px;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note-mark]:hover,
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note-mark]:focus-visible {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
}
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note] {
  display: block;
  margin: var(--kami-gap) 0 0;
  /* 注释正文块：圆角 r=8，内边距跟控件那一档走（10/14），
     文字离圆弧 9.7px（上一版写死 8/12，只剩 7.7px）。 */
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line);
  border-left: 3px solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-card-2);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.56;
