html[data-kami-skin="grokbot"] .kami-md th { font-weight: var(--kami-fw-title); background-color: var(--kami-clay-sink); }
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-md th,
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-md td { border-color: var(--kami-line); }
html[data-kami-skin="grokbot"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-md th { background-color: var(--kami-bg-soft); }
html[data-kami-skin="grokbot"] .kami-md img { max-width: 100%; border-radius: var(--kami-r-sm); }

html[data-kami-skin="grokbot"] .kami-raw {
  margin: 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border: var(--kami-border-w) solid var(--kami-clay-line);
  border-radius: var(--kami-r-md);
