  --kami-bg: #0f1422;            /* 深空星夜底 */
  --kami-bg-soft: #161c2e;       /* 次级深穹底 */
  --kami-card: #192035;          /* 星辰水晶卡 */
  --kami-card-2: #121829;        /* 内嵌暗夜底 */
  --kami-card-hover: #202942;    /* 悬停星空底（不透明色） */
  --kami-line: rgba(147, 180, 248, 0.16);
  --kami-line-strong: rgba(147, 180, 248, 0.45);
  --kami-t1: rgba(147, 180, 248, 0.06);
  --kami-t2: rgba(147, 180, 248, 0.12);
  --kami-t3: rgba(147, 180, 248, 0.20);
  --kami-warn: #fb7185;
  --kami-shadow: 0 10px 30px -4px rgba(0, 0, 0, 0.45), 0 3px 10px rgba(0, 0, 0, 0.25);
  --kami-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.30);

  --kami-texture: linear-gradient(135deg, rgba(25, 32, 53, 0.8) 0%, rgba(15, 20, 34, 0.6) 100%);
  --kami-glow: rgba(79, 140, 246, 0.55);

  --kami-kind-action: #60a5fa;
  --kami-kind-persona: #f472b6;
  --kami-kind-plot: #4ade80;
  --kami-kind-info: #38bdf8;
  --kami-kind-fun: #fbbf24;
  --kami-kind-nsfw: #fb7185;
  --kami-kind-other: #94a3b8;
}

/* 密度档位 */
html[data-kami-skin="isekai"][data-kami-density="compact"] .kami-root {
  --kami-pad-x: 9px;
  --kami-pad-y: 5px;
  --kami-pad-lg-x: 12px;
  --kami-pad-lg-y: 10px;
  --kami-gap: 6px;
  --kami-gap-lg: 9px;
  --kami-row-h: 36px;
}

html[data-kami-skin="isekai"][data-kami-density="roomy"] .kami-root {
  --kami-pad-x: 15px;
  --kami-pad-y: 10px;
  --kami-pad-lg-x: 20px;
  --kami-pad-lg-y: 18px;
  --kami-gap: 10px;
  --kami-gap-lg: 15px;
  --kami-row-h: 46px;
}

/* 动效档位 */
html[data-kami-skin="isekai"][data-kami-motion="calm"] .kami-root {
  --kami-dur-fast: .06s;
  --kami-dur: .12s;
  --kami-dur-slow: .18s;
  --kami-enter-y: 2px;
  --kami-stagger: 8ms;
}

html[data-kami-skin="isekai"][data-kami-motion="off"] .kami-root {
  --kami-dur-fast: 1ms;
  --kami-dur: 1ms;
  --kami-dur-slow: 1ms;
  --kami-enter-y: 0px;
  --kami-enter-scale: 1;
  --kami-stagger: 0ms;
  animation: none !important;
  transition: none !important;
}

html[data-kami-skin="isekai"][data-kami-motion="off"] .kami-root *,
html[data-kami-skin="isekai"][data-kami-motion="off"] .kami-root *::before,
html[data-kami-skin="isekai"][data-kami-motion="off"] .kami-root *::after {
  animation: none !important;
  transition: none !important;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="isekai"] .kami-root {
    --kami-dur-fast: 1ms;
    --kami-dur: 1ms;
    --kami-dur-slow: 1ms;
    --kami-enter-y: 0px;
    --kami-enter-scale: 1;
    --kami-stagger: 0ms;
    animation: none !important;
    transition: none !important;
  }
  html[data-kami-skin="isekai"] .kami-root *,
  html[data-kami-skin="isekai"] .kami-root *::before,
  html[data-kami-skin="isekai"] .kami-root *::after {
    animation: none !important;
    transition: none !important;
  }
}

/* ==========================================================================
 * 4 · 焦点与可访问性
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
  border-radius: var(--kami-r-xs);
}

/* ==========================================================================
 * 5 · 控件对比度四件套（硬性三项 !important：阻击宿主与用户自定义深色 CSS 污染）
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-number,
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-text,
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-textarea,
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
  background-color: var(--kami-card) !important;
  color: var(--kami-fg) !important;
  color-scheme: light !important;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  padding: 6px 10px;
  box-shadow: var(--kami-shadow-sm);
  transition: border-color var(--kami-dur-fast) var(--kami-ease), box-shadow var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-number:focus,
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-text:focus,
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-textarea:focus,
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select:focus {
  border-color: var(--kami-accent);
  box-shadow: 0 0 0 2px var(--kami-accent-soft);
}

html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) input.kami-number[type="number"] {
  text-align: right;
}

html[data-kami-skin="isekai"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-number,
html[data-kami-skin="isekai"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-text,
html[data-kami-skin="isekai"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-textarea,
html[data-kami-skin="isekai"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
  color-scheme: dark !important;
}

/* 控件通用排版 */
html[data-kami-skin="isekai"] input.kami-text,
html[data-kami-skin="isekai"] textarea.kami-textarea,
html[data-kami-skin="isekai"] .kami-select {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="isekai"] textarea.kami-textarea {
  resize: vertical;
}

/* 下拉选单自绘动漫微光 V 形箭头 */
html[data-kami-skin="isekai"] .kami-select {
  -webkit-appearance: none;
  appearance: none;
  padding-right: calc(var(--kami-pad-x) + 18px);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg-dim) 50%),
    linear-gradient(135deg, var(--kami-fg-dim) 50%, transparent 50%);
  background-size: 5px 5px, 5px 5px;
  background-position: calc(100% - 14px) calc(50% - 1px), calc(100% - 9px) calc(50% - 1px);
  background-repeat: no-repeat;
  cursor: pointer;
}

/* ==========================================================================
 * 6 · 禁用与锁死状态（契约 §4.2 & 用户友好性：必须一眼看出点不动）
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-root .kami-btn[disabled],
html[data-kami-skin="isekai"] .kami-root .kami-icon-btn[disabled] {
  opacity: var(--kami-dim-lock, .42);
  color: var(--kami-fg-mute);
  cursor: default;
  pointer-events: none;
  transform: none !important;
  box-shadow: none !important;
}

html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled],
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover,
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: var(--kami-dim-lock, .42);
  color: var(--kami-fg-mute);
  cursor: default;
}

html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover::before,
html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover::after {
  transform: none;
  opacity: 0;
}

html[data-kami-skin="isekai"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover > .kami-badge {
  transform: none;
}

/* ==========================================================================
 * 7 · 结构与等高约束（契约 §4.2 硬规则）
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

html[data-kami-skin="isekai"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}

html[data-kami-skin="isekai"] .kami-root .kami-pv,
html[data-kami-skin="isekai"] .kami-root .kami-pv-frame,
html[data-kami-skin="isekai"] .kami-root .kami-guide-pv,
html[data-kami-skin="isekai"] .kami-root .kami-guide-pv-frame {
  pointer-events: none;
}

html[data-kami-skin="isekai"] .kami-root .kami-deco {
  display: none;
}

html[data-kami-skin="isekai"] .kami-root .kami-d20 {
  pointer-events: auto;
}

html[data-kami-skin="isekai"] .kami-d20-face {
  background: var(--kami-accent);
}

html[data-kami-skin="isekai"] .kami-d20-face > i {
  background: var(--kami-card);
  color: var(--kami-fg);
  font-family: var(--kami-font-title);
}

/* ==========================================================================
 * 8 · 外壳、通透水晶面与通用头部
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-shell {
  position: relative;
  display: block;
  background-color: var(--kami-bg);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
  overflow: hidden;
  transition: border-color var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}

@supports ((backdrop-filter: blur(2px)) or (-webkit-backdrop-filter: blur(2px))) {
  html[data-kami-skin="isekai"] .kami-shell {
    -webkit-backdrop-filter: blur(var(--kami-blur));
    backdrop-filter: blur(var(--kami-blur));
  }
}

html[data-kami-skin="isekai"] .kami-surface {
  background-image: var(--kami-texture);
}

html[data-kami-skin="isekai"] .kami-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
