  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  color: var(--kami-fg);
}
html[data-kami-skin="isekai"] .kami-md h1 { font-size: calc(var(--kami-fs) * 1.18); }
html[data-kami-skin="isekai"] .kami-md h2 { font-size: calc(var(--kami-fs) * 1.08); }
html[data-kami-skin="isekai"] .kami-md h4,
html[data-kami-skin="isekai"] .kami-md h5,
html[data-kami-skin="isekai"] .kami-md h6 { font-size: var(--kami-fs); }

html[data-kami-skin="isekai"] .kami-md code {
  font-family: var(--kami-font-mono);
  font-size: .88em;
  padding: 2px 6px;
  border-radius: var(--kami-r-xs);
  background: var(--kami-t2);
  color: var(--kami-accent);
  font-weight: 600;
}

html[data-kami-skin="isekai"] .kami-md pre {
  margin: .6em 0;
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border-radius: var(--kami-r-sm);
  background: var(--kami-card);
  border: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
}

html[data-kami-skin="isekai"] .kami-md pre code {
  background: none;
  padding: 0;
  color: var(--kami-fg);
  font-weight: normal;
}

html[data-kami-skin="isekai"] .kami-md blockquote {
  margin: .6em 0;
  padding: 4px 0 4px 12px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  color: var(--kami-fg-mute);
  background: var(--kami-t1);
  border-radius: 0 var(--kami-r-xs) var(--kami-r-xs) 0;
}

html[data-kami-skin="isekai"] .kami-md ul,
html[data-kami-skin="isekai"] .kami-md ol {
  margin: .5em 0;
  padding-left: 1.4em;
}

html[data-kami-skin="isekai"] .kami-md li {
  margin: .2em 0;
}
/* 嵌套层级：缩进加深一档，圆点/序号压暗一档，条目行距收紧 */
html[data-kami-skin="isekai"] .kami-md li > ul,
html[data-kami-skin="isekai"] .kami-md li > ol {
  margin-top: .25em;
  margin-bottom: .15em;
}
html[data-kami-skin="isekai"] .kami-md li::marker { color: var(--kami-accent); }
html[data-kami-skin="isekai"] .kami-md li li::marker { color: var(--kami-fg-mute); }

html[data-kami-skin="isekai"] .kami-md em {
  font-style: italic;
  color: var(--kami-fg-dim);
}
html[data-kami-skin="isekai"] .kami-md img {
  max-width: 100%;
  height: auto;
  display: inline-block;
  border-radius: var(--kami-r-sm);
  border: var(--kami-border-w) solid var(--kami-line);
}

html[data-kami-skin="isekai"] .kami-md strong {
  color: var(--kami-fg);
  font-weight: 700;
}

html[data-kami-skin="isekai"] .kami-md a {
  color: var(--kami-accent);
  text-decoration: underline;
  text-underline-offset: 3px;
  font-weight: 600;
}

html[data-kami-skin="isekai"] .kami-md hr {
  border: 0;
  border-top: var(--kami-border-w) solid var(--kami-line);
  margin: .9em 0;
}

html[data-kami-skin="isekai"] .kami-md table {
  border-collapse: collapse;
  width: 100%;
  font-size: var(--kami-fs-xs);
}

html[data-kami-skin="isekai"] .kami-md th,
html[data-kami-skin="isekai"] .kami-md td {
  border: var(--kami-border-w) solid var(--kami-line);
  padding: 5px 8px;
}
/* 窄屏表格不撑破：手机档把表变成可横滚的块 */
@media (max-width: 560px) {
  html[data-kami-skin="isekai"] .kami-md table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
  }
}

html[data-kami-skin="isekai"] .kami-raw {
  margin: 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: var(--kami-r-md);
  background: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  line-height: 1.6;
  color: var(--kami-fg-dim);
  white-space: pre-wrap;
  overflow-x: auto;
}

/* ==========================================================================
 * 13 · 表单控件（字段、滑杆、开关）
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-field {
