  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="isekai"] .kami-field-value {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* 滑杆 */
html[data-kami-skin="isekai"] .kami-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100px;
  height: 6px;
  border-radius: var(--kami-r-pill);
  background: var(--kami-bg-soft);
  cursor: pointer;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.1);
}

html[data-kami-skin="isekai"] .kami-range::-webkit-slider-thumb {
