}

/* 开关（Switch） */
html[data-kami-skin="isekai"] .kami-switch {
  display: inline-flex;
  align-items: center;
  cursor: pointer;
}

html[data-kami-skin="isekai"] .kami-switch-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

html[data-kami-skin="isekai"] .kami-switch {
  position: relative;
  width: 40px;
  height: 22px;
  border-radius: var(--kami-r-pill);
  background: var(--kami-bg-soft);
  border: 1px solid var(--kami-line);
  transition: background var(--kami-dur) var(--kami-ease), border-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="isekai"] .kami-switch-thumb {
  position: absolute;
  top: 2px;
