}

html[data-kami-skin="isekai"] .kami-scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

html[data-kami-skin="isekai"] .kami-scroll::-webkit-scrollbar-thumb {
  background: var(--kami-t3);
