 *   次要文字（#444750）= 8.7:1 ｜ 最弱文字（#6c707d）= 4.8:1
 *   朱红底（#d92534）上的纯白字（#ffffff）= 5.1:1
 *   黑墨底（#111215）上的纯白字（#ffffff）= 18.0:1
 *   分镜粗线（#111215）对纸白底 = 18.0:1（硬朗分明）
 *   选中态具有「墨块反白 / 朱笔加粗 / 45° 网点纸阴影」多重可视差别，不只靠颜色。
 *
 * 纯 CSS 实现：零外部网络请求、无 JS、无 @import、无 @font-face、无 vh、无 position:fixed 铺满。
 * 契约规范：docs/皮肤契约.md（作用域前缀 / 令牌全集 / 风格性文案槽 / 对比度防线）。
 * ========================================================================== */

/* ==========================================================================
 * 1 · 令牌全集（默认亮色：原稿白底配粗黑线与网点纸）
 * ======================================================================== */
html[data-kami-skin="manga"] .kami-root {
  /* —— 风格性文案槽位（契约 §3.7） —— */
  --kami-label-think-title: 原稿分镜;
  --kami-label-think-title-open: 分镜草案;
  --kami-label-options-title: 决策分格;

  /* —— 色彩：原稿白 + 漫画墨黑 + 修正朱红 —— */
  --kami-fg: #111215;            /* 主文字：深沉墨线黑，对纸白底 > 18.0:1 */
  --kami-fg-dim: #444750;        /* 次要文字：深铅笔灰，对纸白底 > 8.5:1 */
  --kami-fg-mute: #6c707d;       /* 最弱文字：浅铅笔灰，对纸白底 >= 4.8:1 */
  --kami-accent: #d92534;        /* 强调色：原稿校对朱红，纯白字在其上 5.1:1 */
  --kami-accent-fg: #ffffff;     /* 强调底上的文字：纯白反字 */
  --kami-accent-soft: rgba(217, 37, 52, 0.10); /* 朱红淡晕 */
  --kami-accent-line: #d92534;   /* 朱红修正线 */

  --kami-bg: #f5f6f8;            /* 容器背景：原稿草案纸灰白底 */
  --kami-bg-soft: #eaedf2;       /* 次级容器背景：浅灰网点衬底 */
  --kami-card: #ffffff;          /* 卡片背景：洁白漫画分镜格 */
  --kami-card-2: #eceef2;        /* 卡片内正文/引用块网点浅底 */
  --kami-card-hover: #ffffff;    /* 卡片悬停：洁白纸面（不透明色） */
  --kami-line: #111215;          /* 常规分隔线：硬朗分镜黑线 */
  --kami-line-strong: #111215;   /* 强调描边：2px 粗黑墨线 >= 18:1 */
  --kami-t1: rgba(17, 18, 21, 0.05);
  --kami-t2: rgba(17, 18, 21, 0.10);
  --kami-t3: rgba(17, 18, 21, 0.18);
  --kami-warn: #d92534;          /* 警示色：原稿警告朱红 */
  --kami-shadow: 4px 4px 0px #111215;     /* 漫画硬投影：4px 无模糊实黑 */
  --kami-shadow-sm: 2px 2px 0px #111215;  /* 按钮/徽章硬投影：2px 实黑 */
  --kami-blur: 0px;

  /* —— 布局与尺寸 —— */
  --kami-r-xs: 2px;
  --kami-r-sm: 3px;
  --kami-r-md: 4px;
  --kami-r-lg: 6px;
  --kami-r-pill: 999px;
  --kami-border-w: 2px;          /* 手绘分镜粗黑线基准 2px */
  --kami-pad-x: 12px;
  --kami-pad-y: 8px;
  --kami-pad-lg-x: 16px;
  --kami-pad-lg-y: 14px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 40px;            /* 控件行高基准 >= 40px */
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 15.5rem;
  --kami-panel-w: 840px;
  --kami-panel-h: 1120px;
  --kami-list-dir: column;
  --kami-justify: stretch;

  /* —— 文本与排版 —— */
  --kami-fs-scale: 1;
  --kami-fs: calc(15px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .78);
  --kami-fs-sm: calc(var(--kami-fs) * .88);
  --kami-fs-lg: calc(var(--kami-fs) * 1.15);
  --kami-lh: 1.62;
  --kami-ls: .015em;
  --kami-ls-title: .05em;
  --kami-font: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "WenQuanYi Micro Hei", sans-serif;
  --kami-font-title: "Impact", -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", "SimHei", "Heiti SC", sans-serif;
  --kami-font-mono: ui-monospace, SFMono-Regular, "Cascadia Mono", Consolas, "Liberation Mono", "Courier New", monospace;
  --kami-fw: 500;
  --kami-fw-title: 800;
  --kami-title-transform: uppercase;

  /* —— 装饰与网点纸（Halftone 45° 阵列） —— */
  --kami-texture: radial-gradient(circle at center, rgba(17, 18, 21, calc(var(--kami-mg-dot-op, 35) * 0.003)) 1.2px, transparent 1.3px);
  --kami-glow: rgba(217, 37, 52, 0.40);
  --kami-glow-size: 4px;
  --kami-surface-clip: none;
  --kami-accent-mark: 3px;

  /* —— 动效 —— */
  --kami-dur-fast: .10s;
  --kami-dur: .18s;
  --kami-dur-slow: .30s;
  --kami-ease: cubic-bezier(.18, .89, .32, 1.15);
  --kami-ease-out: cubic-bezier(.16, 1, .3, 1);
  --kami-enter-y: 6px;
  --kami-enter-scale: .97;
  --kami-stagger: 22ms;

  /* —— 语义色（漫画彩色网点色谱，对白底对比度均 >= 5.0:1） —— */
  --kami-kind-action: #1863a1;   /* 热血行动 · 少年蓝 (7.2:1) */
  --kami-kind-persona: #942350;  /* 人物性格 · 少女品红 (7.5:1) */
  --kami-kind-plot: #167543;     /* 剧情推进 · 机械森绿 (6.5:1) */
  --kami-kind-info: #177186;     /* 侦探信息 · 苍青墨色 (6.0:1) */
  --kami-kind-fun: #9a5a07;      /* 搞笑日常 · 燃金橙黄 (5.3:1) */
  --kami-kind-nsfw: #c01834;     /* 核心焦点 · 绯红热烈 (5.8:1) */
  --kami-kind-other: #4b505c;    /* 漫格次要 · 铅墨灰 (7.8:1) */

  /* —— 皮肤私有参数默认值 —— */
  --kami-mg-dot-size: 4px;
  --kami-mg-dot-op: 35;
  --kami-mg-line-w: 2px;

  /* —— 关态/锁死压淡兜底 —— */
  --kami-dim-soft: .60;
  --kami-dim-lock: .42;

  box-sizing: border-box;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  font-weight: var(--kami-fw);
  line-height: var(--kami-lh);
  letter-spacing: var(--kami-ls);
  font-variant-numeric: tabular-nums;
  text-align: left;
  text-rendering: optimizeLegibility;
  word-break: break-word;
  -webkit-tap-highlight-color: transparent;
}

