  scrollbar-color: var(--kami-line) transparent;
}

html[data-kami-skin="manga"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-scroll::-webkit-scrollbar {
  width: 6px;
}

html[data-kami-skin="manga"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-scroll::-webkit-scrollbar-thumb {
