    linear-gradient(135deg, transparent 10px, var(--kami-line) 10px, var(--kami-line) 12px, transparent 12px);
}

/* 列表与分镜卡片 */
html[data-kami-skin="manga"] .kami-root .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  gap: var(--kami-gap);
}

html[data-kami-skin="manga"] .kami-root .kami-card {
  position: relative;
  display: block;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-card);
  box-shadow: 3px 3px 0px var(--kami-line);
  transition: transform var(--kami-dur-fast) var(--kami-ease), box-shadow var(--kami-dur-fast) var(--kami-ease), border-color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-root .kami-card:not(.kami-item) {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  margin-bottom: var(--kami-gap);
}

/* 卡片主体 */
html[data-kami-skin="manga"] .kami-card-body {
