}

html[data-kami-skin="manga"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-head,
html[data-kami-skin="manga"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-title,
html[data-kami-skin="manga"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-note {
  padding-left: 0;
  padding-right: 0;
}

/* 面板卡头：与卡同宽的矩形条，不做悬空胶囊 */
html[data-kami-skin="manga"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) button.kami-card-head.kami-btn {
  width: 100%;
  min-height: 0;
  border-radius: var(--kami-r-xs);
  justify-content: flex-start;
