}

/* 激活选中态（开关开着）：必须有可视差别，翻转字色 */
html[data-kami-skin="manga"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item.is-on,
html[data-kami-skin="manga"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-head.is-on {
