"},{"id":"memo","name":"记事本","button":"记事本","scheme":"light","tagline":"一页刚印好的方格手账：纸面平整，印着裁切标记与荧光笔痕。","effects":[{"id":"grid","label":"方格底纹","desc":"纸面底层的淡色方格网纹，正文区域会自动覆盖格线。","default":true},{"id":"crop","label":"裁切线","desc":"纸张四角显示十字裁切标记，呈现印制裁剪的对齐参考线。","default":true},{"id":"ink","label":"印刷重影","desc":"标题文字带有轻微红青双色重影，展开时伴随错位复位动效。","default":true},{"id":"dice","label":"翻牌入场","desc":"行动选项展开时，左侧编号按顺序逐枚翻牌落位。","default":true},{"id":"bleed","label":"纸边洇墨","desc":"纸张外边缘呈现不规则的暗色墨水渗透与晕染痕迹。","default":false},{"id":"grain","label":"影印颗粒","desc":"整张纸面覆盖一层微细的复印噪点与油墨杂质纹理。","default":false}],"params":[{"id":"grid-step","label":"格线间距","group":"纸面","token":"--kami-grid-step","unit":"px","min":10,"max":40,"step":2,"value":20},{"id":"corner","label":"右下裁角","group":"纸面","token":"--kami-corner","unit":"px","min":0,"max":22,"step":1,"value":9},{"id":"marker","label":"荧光笔浓度","group":"印记","token":"--kami-marker","unit":"%","min":0,"max":60,"step":2,"value":30},{"id":"tilt","label":"印章倾角","group":"印记","token":"--kami-stamp-tilt","unit":"deg","min":-4,"max":0,"step":0.2,"value":-1.2}],"css":"/* ============================================================
 * 卡密预设 · 皮肤「记事本」  id = memo
 * ------------------------------------------------------------
 * 概念：装不下 —— 一页刚出打印机、被印得太满的模组纸。
 *   机器的笔触：格线 / 双规线 / 裁切角 / 套准标记 / 流水编号（直、准、等距）
 *   她的笔触：荧光笔 / 橡皮章 / 便利贴 / 手抖的下划线（歪 1~1.2° / 出界 1px）
 *   恐怖不在光里 —— --kami-glow 的取值就是透明的零。
 *
 * 作用域：html[data-kami-skin="memo"] .kami-root
 * 明暗不是反色，是灯：dark 只是同一张纸在关灯后的房间里。
 * 聊天楼层 iframe 内 filter / backdrop-filter 用量 = 0（按楼层线性付费）；
 *   唯一的 backdrop-filter 在 .kami-drop（酒馆页面上的面板，全场景 <= 3 个实例）。
 * ============================================================ */

/* ============================================================
 * 0. 令牌
 * ============================================================ */

html[data-kami-skin="memo"] .kami-root {
  /* ---- 3.1 色彩与背景（默认 = 台灯下的桌子） ---- */
  --kami-fg: #241f1a;
  --kami-fg-dim: #5a5046;
  --kami-fg-mute: #625848;
  --kami-accent: #c03a2b;
  --kami-accent-fg: #fdf8ee;
  --kami-accent-soft: rgba(233, 178, 65, var(--kami-marker));
  --kami-accent-line: rgba(192, 58, 43, .55);

  --kami-bg: #f5f0e4;
  --kami-bg-soft: #ece5d5;
  --kami-card: #fbf8f0;
  --kami-card-2: #fffdf7;
  --kami-card-hover: #fff9e6;
  --kami-line: rgba(36, 31, 26, .22);
  --kami-line-strong: rgba(36, 31, 26, .54);
  --kami-t1: rgba(36, 31, 26, .045);
  --kami-t2: rgba(36, 31, 26, .085);
  --kami-t3: rgba(36, 31, 26, .16);
  --kami-warn: #a04a12;
  --kami-shadow: 0 2px 0 rgba(36, 31, 26, .10), 0 8px 20px rgba(64, 44, 24, .10);
  --kami-shadow-sm: 0 1px 0 rgba(36, 31, 26, .12);
  --kami-blur: 6px;

  /* ---- 本皮肤的内部令牌（不属于契约，但由参数面板驱动） ---- */
  --kami-marker: 30%;           /* 荧光笔浓度 */
  --kami-stamp-tilt: -1.2deg;   /* 印章歪斜 */
  --kami-corner: 9px;           /* 右下裁角 */
  --kami-grid-step: 20px;       /* 格线间距 */
  --kami-fiber: rgba(36, 31, 26, .022);
  --kami-seal: rgba(36, 31, 26, .05);
  --kami-crop: rgba(36, 31, 26, .38);
  --kami-grid-c: rgba(36, 31, 26, .075);
  --kami-ink-cy: rgba(31, 122, 134, .34);
  --kami-ink-mg: rgba(192, 58, 43, .26);
  --kami-wobble: url("data:image/svg+xml,%3Csvg xmlns='http%3A//www.w3.org/2000/svg' viewBox='0 0 60 6' preserveAspectRatio='none'%3E%3Cpath d='M0 4.3C9 1.7 17 5.2 26 3.1 35 1 45 5.1 60 2.4' fill='none' stroke='%23c03a2b' stroke-width='1.4' stroke-linecap='round'/%3E%3C/svg%3E");
  --kami-hl-ease: cubic-bezier(.6, 0, .3, 1);   /* 笔迹：有笔压着纸 */
  --kami-kind: var(--kami-accent);

  /* ---- 3.2 布局与尺寸 ---- */
  --kami-r-xs: 1px;
  --kami-r-sm: 2px;
  --kami-r-md: 3px;
  --kami-r-lg: 4px;
  --kami-r-pill: 2px;           /* 刻意的：本皮肤没有药丸形 */
  --kami-border-w: 1px;
  --kami-pad-x: 9px;
  --kami-pad-y: 6px;
  --kami-pad-lg-x: 14px;
  --kami-pad-lg-y: 12px;
  --kami-gap: 8px;
  --kami-gap-lg: 14px;
  --kami-row-h: 44px;
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 230px;
  --kami-panel-w: 840px;
  --kami-panel-h: 1120px;
  --kami-list-dir: column;
  --kami-justify: flex-start;

  /* ---- 3.3 文本与排版 ---- */
  --kami-fs-scale: 1;
  --kami-fs: calc(15px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .74);
  --kami-fs-sm: calc(var(--kami-fs) * .86);
  --kami-fs-lg: calc(var(--kami-fs) * 1.16);
  --kami-lh: 1.78;
  --kami-ls: .012em;
  --kami-ls-title: .08em;
  --kami-font: "Songti SC", "Source Han Serif SC", "Noto Serif CJK SC", "SimSun", ui-serif, Georgia, serif;
  --kami-font-title: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  --kami-font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  --kami-fw: 400;
  --kami-fw-title: 600;
  --kami-title-transform: uppercase;

  /* ---- 3.4 装饰与特效 ---- */
  --kami-texture:
    repeating-linear-gradient(58deg, var(--kami-fiber) 0 1px, transparent 1px 11px),
    repeating-linear-gradient(-32deg, var(--kami-fiber) 0 1px, transparent 1px 17px);
  --kami-glow: rgba(192, 58, 43, 0);   /* 零辉光：本皮肤没有一个像素是发光的 */
  --kami-glow-size: 0px;
  --kami-surface-clip: polygon(0 0, 100% 0, 100% calc(100% - var(--kami-corner)), calc(100% - var(--kami-corner)) 100%, 0 100%);
  --kami-accent-mark: 3px;

  /* ---- 3.5 动画与过渡 ---- */
  --kami-dur-fast: 130ms;
  --kami-dur: 200ms;
  --kami-dur-slow: 320ms;
  --kami-ease: cubic-bezier(.22, .68, .24, 1);        /* 重物：被手推到位，绝不弹跳 */
  --kami-ease-out: cubic-bezier(.28, 1.16, .42, 1);   /* 轻物：允许一次 <= 6% 过冲 */
  --kami-enter-y: -7px;
  --kami-enter-scale: 1;
  --kami-stagger: 42ms;

  /* ---- 3.8 语义色 ---- */
  --kami-kind-action: #2f5fa8;
  --kami-kind-persona: #8a4a86;
  --kami-kind-plot: #2f7d5c;
  --kami-kind-info: #1f7a86;
  --kami-kind-fun: #b5780f;
  --kami-kind-nsfw: #ab3a63;
  --kami-kind-other: #6d6357;

  /* ---- 3.7 文案令牌：只剩三个风格性标题（其余界面文字由前端写死，皮肤不得覆盖） ---- */
  --kami-label-think-title: 速记;
  --kami-label-think-title-open: 速记正文;
  --kami-label-options-title: 待办;
}

/* ---- 明暗：不是反色，是灯 ---- */
html[data-kami-skin="memo"][data-kami-scheme="dark"] .kami-root {
  color-scheme: dark;
  --kami-fg: #ece3d4;
  --kami-fg-dim: #b3a795;
