  --kami-ink-mg: rgba(232, 112, 92, .24);
  --kami-wobble: url("data:image/svg+xml,%3Csvg xmlns='http%3A//www.w3.org/2000/svg' viewBox='0 0 60 6' preserveAspectRatio='none'%3E%3Cpath d='M0 4.3C9 1.7 17 5.2 26 3.1 35 1 45 5.1 60 2.4' fill='none' stroke='%23e8705c' stroke-width='1.4' stroke-linecap='round'/%3E%3C/svg%3E");

  --kami-kind-action: #7ea6e8;
