/* Native search/model menu rows: keep an opaque surface and a paired foreground. */
html[data-kami-skin="memo"] .kami-root select option,
html[data-kami-skin="memo"] .kami-root select optgroup {
  color: var(--kami-fg) !important;
  background-color: var(--kami-card-2) !important;
  color-scheme: inherit !important;
}
html[data-kami-skin="memo"] .kami-root select option:checked {
  color: var(--kami-accent-fg) !important;
  background-color: var(--kami-accent) !important;
}
html[data-kami-skin="memo"] .kami-root select option:disabled:not(:checked) { color: var(--kami-fg-dim) !important; }/* Shared component roles: descriptions follow the selectable surface foreground. */
html[data-kami-skin="memo"] .kami-root [data-kami-ui="choiceCard"][data-kami-card-role="choice"] > .kami-card-note { color:inherit; opacity:1; }
html[data-kami-skin="memo"] .kami-root [data-kami-ui="field"] > .kami-card-note { color:var(--kami-fg-dim); opacity:1; }
html[data-kami-skin="memo"] .kami-root [data-kami-ui="tabs"] .kami-tab[aria-selected="true"] { color:var(--kami-fg); }

html[data-kami-skin="memo"] .kami-root [data-kami-ui="empty"] { color:var(--kami-fg-dim); }
html[data-kami-skin="memo"] .kami-root [data-kami-ui="steps"] .is-current :is(strong,small) { color:var(--kami-fg); }

