}

/* calm：时长降一档 + 去掉循环动画 */
html[data-kami-skin="mileng"][data-kami-motion="calm"] .kami-root {
  --kami-dur-fast: .07s;
  --kami-dur: .11s;
  --kami-dur-slow: .16s;
  --kami-enter-y: 1px;
  --kami-stagger: 8ms;
}

/* off：全部压到 1ms 且无位移；循环动画直接 animation:none（契约 §3.6） */
html[data-kami-skin="mileng"][data-kami-motion="off"] .kami-root {
  --kami-dur-fast: 1ms;
  --kami-dur: 1ms;
  --kami-dur-slow: 1ms;
  --kami-enter-y: 0px;
  --kami-enter-scale: 1;
  --kami-stagger: 0ms;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="mileng"] .kami-root {
    --kami-dur-fast: 1ms;
    --kami-dur: 1ms;
    --kami-dur-slow: 1ms;
    --kami-enter-y: 0px;
    --kami-enter-scale: 1;
    --kami-stagger: 0ms;
  }
  /* 循环动画一律直接停：压到 1ms 仍然是无限循环，reduce 下不许跑 */
  html[data-kami-skin="mileng"] .kami-root *,
  html[data-kami-skin="mileng"] .kami-root *::before,
  html[data-kami-skin="mileng"] .kami-root *::after {
    animation: none !important;
    transition-duration: 1ms !important;
  }
}

/* ==========================================================================
 * 4 · 关键帧（信号灯收放 / 斜纹爬行 / 入场）
 * ======================================================================== */
@keyframes kami-mil-in {
  from { opacity: 0; transform: translateY(calc(var(--kami-enter-y) * -1)); }
  to { opacity: 1; transform: none; }
}

@keyframes kami-mil-beacon {
  0%, 100% { box-shadow: 0 0 2px var(--kami-glow); }
  50% { box-shadow: 0 0 var(--kami-glow-size) var(--kami-glow); }
}

@keyframes kami-mil-hatch {
  from { background-position-x: 0px; }
  to { background-position-x: 16px; }
}

/* ==========================================================================
 * 5 · 焦点与可访问性
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

html[data-kami-skin="mileng"] .kami-root .kami-switch:focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

/* ==========================================================================
 * 6 · 控件对比度四件套（panel 作用域 + 三项 !important）
 *    阻击两层抢色：① 酒馆「自定义 CSS」给四类控件上的 !important 深漆；
 *    ② 皮肤头部 input { color: inherit } 把文字压成 fg-dim。
 *    background-color 必须长写：简写会把 .kami-select 自绘箭头一起重置掉。
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) input.kami-number,
html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) select.kami-number,
html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) textarea.kami-number,
html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) input.kami-text,
html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) textarea.kami-textarea,
html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
  color: var(--kami-fg) !important;
  background-color: var(--kami-bg-soft) !important;
