}

html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) input.kami-number,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) select.kami-number,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) textarea.kami-number,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) input.kami-text,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) textarea.kami-textarea,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
  color-scheme: light !important;
}

/* 右对齐只属于数字框（契约 §4.2：不许挂在裸类名上） */
html[data-kami-skin="mileng"] .kami-root input.kami-number[type="number"] {
  text-align: right;
}

/* ==========================================================================
 * 7 · 结构与等高约束
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-root .kami-item-note {
