  gap: var(--kami-gap);
  margin-left: auto;
  flex: none;
}

html[data-kami-skin="mileng"] .kami-body {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="mileng"] .kami-foot {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-lg-x) var(--kami-pad-lg-y);
  border-top: var(--kami-border-w) solid var(--kami-line-strong);
