}

/* —— 状态点 = 信号灯：关态空心方框，开态沙黄实心方块（形状占一样） —— */
html[data-kami-skin="mileng"] .kami-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border: var(--kami-border-w) solid var(--kami-fg-mute);
  border-radius: var(--kami-r-xs);
  background-color: transparent;
  transition: background-color var(--kami-dur) var(--kami-ease), border-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="mileng"] .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  box-shadow: 0 0 var(--kami-glow-size) var(--kami-glow);
}

/* 引导向导的进度点复用 .kami-dot：回小方点，不跟信号灯闪 */
html[data-kami-skin="mileng"] .kami-dots .kami-dot {
  width: 6px;
  height: 6px;
  border-color: var(--kami-fg-mute);
  opacity: 0.38;
}

html[data-kami-skin="mileng"] .kami-dots .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  opacity: 1;
}

/* —— 折叠箭头 —— */
html[data-kami-skin="mileng"] .kami-chev {
  flex: none;
  font-size: calc(var(--kami-icon) * 0.8);
  color: var(--kami-fg-mute);
  transition: transform var(--kami-dur) var(--kami-ease), color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="mileng"] .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev {
  transform: rotate(90deg);
  color: var(--kami-accent);
}

/* —— 正文头部的横向操作行 —— */
html[data-kami-skin="mileng"] .kami-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-lg-x);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-bg-soft);
}

/* ==========================================================================
 * 10 · 按钮
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-btn,
html[data-kami-skin="mileng"] .kami-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  line-height: 1.2;
  cursor: pointer;
  user-select: none;
  transition: background-color var(--kami-dur-fast) var(--kami-ease),
              border-color var(--kami-dur-fast) var(--kami-ease),
              color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="mileng"] .kami-icon-btn {
  min-width: var(--kami-row-h);
  padding: 0;
  font-size: var(--kami-icon);
}

@media (hover: hover) {
  html[data-kami-skin="mileng"] .kami-btn:hover,
  html[data-kami-skin="mileng"] .kami-icon-btn:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent);
  }
}

html[data-kami-skin="mileng"] .kami-btn:active,
html[data-kami-skin="mileng"] .kami-icon-btn:active {
  transform: translateY(1px);
}

html[data-kami-skin="mileng"] .kami-btn--ghost {
  background-color: transparent;
}

/* 主按钮：整块强调底 → 文字一族成对翻过去（同型事故三次的教训） */
html[data-kami-skin="mileng"] .kami-root .kami-btn--primary {
  --kami-fg: var(--kami-accent-fg);
  --kami-fg-dim: var(--kami-accent-fg);
  --kami-fg-mute: var(--kami-accent-fg);
  --kami-line: var(--kami-accent-fg);
  --kami-line-strong: var(--kami-accent-fg);
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
}

@media (hover: hover) {
  html[data-kami-skin="mileng"] .kami-btn--primary:hover {
    filter: brightness(1.08);
    color: var(--kami-accent-fg);
  }
}

/* 选中态：淡染底 + 内环 + 加粗，三条里三条不是颜色（不改 border-width） */
html[data-kami-skin="mileng"] .kami-root .kami-btn.is-on {
  background-color: var(--kami-accent-soft);
  border-color: var(--kami-accent);
  color: var(--kami-fg);
  font-weight: var(--kami-fw-title);
  box-shadow: inset 0 0 0 1px var(--kami-accent);
}

/* 锁死的主按钮 / 图标按钮：一眼看出点不动 */
html[data-kami-skin="mileng"] .kami-root .kami-btn[disabled],
html[data-kami-skin="mileng"] .kami-root .kami-icon-btn[disabled] {
  opacity: var(--kami-dim-lock, .42);
  color: var(--kami-fg-mute);
  cursor: default;
  box-shadow: none;
  filter: none;
  transform: none;
}

html[data-kami-skin="mileng"] .kami-root .kami-btn[disabled]:hover,
html[data-kami-skin="mileng"] .kami-root .kami-icon-btn[disabled]:hover {
  background-color: var(--kami-card);
  border-color: var(--kami-line-strong);
  color: var(--kami-fg-mute);
}

html[data-kami-skin="mileng"] .kami-root .kami-btn--ghost[disabled],
html[data-kami-skin="mileng"] .kami-btn--primary[disabled] {
  background-color: var(--kami-card);
  border-color: var(--kami-line-strong);
  color: var(--kami-fg-mute);
}

/* ==========================================================================
 * 11 · 分段切换（渲染 / 原文、填入 / 发送）
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-seg {
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border: var(--kami-border-w) solid var(--kami-line);
