  color: var(--kami-fg-dim);
  white-space: pre-wrap;
  overflow-x: auto;
}

/* —— 列表 / 网格 —— */
html[data-kami-skin="mileng"] .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  justify-content: var(--kami-justify);
  gap: var(--kami-gap);
}

html[data-kami-skin="mileng"] .kami-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
  align-items: stretch;
}

/* 编号刻度：每个直系条目一支计数器；卡头左侧盖一枚 01 式钢印编号 */
html[data-kami-skin="mileng"] .kami-root .kami-grid {
