  }
}

/* 选中态：淡染底 + 内环 + 加粗，形状/边线/字重三样占齐 */
html[data-kami-skin="mileng"] .kami-root .kami-item.is-on,
html[data-kami-skin="mileng"] .kami-root .kami-item[aria-pressed="true"] {
  border-color: var(--kami-accent);
