html[data-kami-skin="mileng"] .kami-root [data-kami-kind="action"]  { --kami-kind-curr: var(--kami-kind-action); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="persona"] { --kami-kind-curr: var(--kami-kind-persona); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="plot"]    { --kami-kind-curr: var(--kami-kind-plot); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="info"]    { --kami-kind-curr: var(--kami-kind-info); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="fun"]     { --kami-kind-curr: var(--kami-kind-fun); }
