  border: 2px solid var(--kami-bg);
  box-shadow: var(--kami-shadow-sm);
  cursor: pointer;
}

html[data-kami-skin="mileng"] .kami-range::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-accent);
  border: 2px solid var(--kami-bg);
  cursor: pointer;
}

/* —— 滚动区 —— */
html[data-kami-skin="mileng"] .kami-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-line-strong) transparent;
}

html[data-kami-skin="mileng"] .kami-scroll::-webkit-scrollbar { width: 8px; height: 8px; }

html[data-kami-skin="mileng"] .kami-scroll::-webkit-scrollbar-track { background: transparent; }

html[data-kami-skin="mileng"] .kami-scroll::-webkit-scrollbar-thumb {
  background-color: var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
}

/* —— 尺寸把手 —— */
html[data-kami-skin="mileng"] .kami-resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
  background-image: linear-gradient(135deg, transparent 46%, var(--kami-line-strong) 46%, var(--kami-line-strong) 54%, transparent 54%);
}

/* —— 皮肤预览缩略 —— */
html[data-kami-skin="mileng"] .kami-preview {
  position: relative;
  border-radius: var(--kami-r-md);
  border: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-card);
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

html[data-kami-skin="mileng"] .kami-preview i {
  display: block;
  height: 6px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t3);
}

html[data-kami-skin="mileng"] .kami-preview i:first-child {
  width: 58%;
  background-color: var(--kami-accent);
}

/* —— 贴底抽屉（脚本下发的 data-kami-layout="sheet"） —— */
html[data-kami-skin="mileng"] .kami-root .kami-drop.kami-drop[data-kami-layout="sheet"] {
  left: 0;
  right: 0;
  top: auto;
  bottom: 0;
  width: auto;
  height: 78%;
  max-height: 78%;
  border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
}

/* 兜底：面板脚本还没跑起来（元素上还没有 data-kami-layout）时按 768px 贴底 */
@media (max-width: 768px) {
  html[data-kami-skin="mileng"] .kami-root .kami-drop.kami-drop:not([data-kami-layout]) {
    left: 0;
    right: 0;
    top: auto;
    bottom: 0;
    width: auto;
    height: 78%;
    max-height: 78%;
    border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
  }
}

/* ==========================================================================
 * 13 · 容器查询与窄屏（320px 必须成立；手机档选择器必须与
 *      基准规则逐字相同，否则 .kami-root 祖先声明会吃掉元素自己的值）
 * ======================================================================== */
@container (max-width: 360px) {
  html[data-kami-skin="mileng"] .kami-root .kami-title {
    letter-spacing: calc(var(--kami-ls-title) * 0.5);
  }
}

@media (max-width: 560px) {
  html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 152px;
  }
}

@media (max-width: 380px) {
  html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 108px;
  }
  html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) {
    --kami-row-h: 44px;
  }
  html[data-kami-skin="mileng"] .kami-root .kami-bar {
    flex-wrap: wrap;
  }
}

/* ==========================================================================
 * 14 · 特效实现（每个 id 都有 data-kami-effects~= 规则）
 * ========================================================================== */

/* 1. 刻度带（ticks）：头部下缘一道量程刻度尺；浓度静态、零动画 */
html[data-kami-skin="mileng"][data-kami-effects~="ticks"] .kami-head::after {
  content: "";
  position: absolute;
  left: var(--kami-pad-lg-x);
  right: var(--kami-pad-lg-x);
  bottom: 0;
  height: 5px;
  pointer-events: none;
  background-image:
    repeating-linear-gradient(90deg,
      var(--kami-accent-line) 0 1px,
      transparent 1px var(--kami-mil-tick-l)),
    linear-gradient(180deg, var(--kami-line) 0 1px, transparent 1px);
  background-size: auto 3px, auto 1px;
  background-position: 0 100%, 0 0;
  background-repeat: repeat-x, no-repeat;
  opacity: 0.8;
}

/* markdown 栏目级标题也带一小段刻度，把身份符号延到正文 */
html[data-kami-skin="mileng"][data-kami-effects~="ticks"] .kami-md h1::after,
html[data-kami-skin="mileng"][data-kami-effects~="ticks"] .kami-md h2::after {
  content: "";
  display: block;
  height: 4px;
  margin-top: 4px;
  background-image: repeating-linear-gradient(90deg,
    var(--kami-accent-line) 0 1px,
    transparent 1px calc(var(--kami-mil-tick) * 1px));
  background-repeat: repeat-x;
}

/* 2. 警示斜纹（hazard）：只画边条 —— 脚条上缘一道、警示提示左缘一段；
      浓度走无单位参数（crt80s 的教训：unit 写 % 会让 alpha 失真） */
html[data-kami-skin="mileng"][data-kami-effects~="hazard"] .kami-root .kami-foot::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: -3px;
  height: 3px;
  pointer-events: none;
  background-image: repeating-linear-gradient(45deg,
    rgba(216, 169, 60, calc(0.85 * var(--kami-mil-hatch) / 100)) 0 6px,
    transparent 6px 12px);
}

html[data-kami-skin="mileng"][data-kami-effects~="hazard"] .kami-root .kami-toast {
  border-image: none;
}

html[data-kami-skin="mileng"][data-kami-effects~="hazard"] .kami-root .kami-toast.is-bad {
  box-shadow: inset 4px 0 0 var(--kami-warn);
}

html[data-kami-skin="mileng"][data-kami-effects~="hazard"] .kami-root .kami-item.is-on {
  background-image: repeating-linear-gradient(90deg,
    rgba(216, 169, 60, calc(0.28 * var(--kami-mil-hatch) / 100)) 0 2px,
    transparent 2px 14px);
}

/* 3. 喷漆颗粒（grain）：静态、零动画；浓度走无单位参数 */
html[data-kami-skin="mileng"][data-kami-effects~="grain"] .kami-surface::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    repeating-linear-gradient(0deg,
      rgba(233, 225, 200, calc(0.05 * var(--kami-mil-grain) / 100)) 0 1px,
      transparent 1px 3px),
    repeating-linear-gradient(90deg,
      rgba(233, 225, 200, calc(0.05 * var(--kami-mil-grain) / 100)) 0 1px,
      transparent 1px 3px);
}

/* 4. 信号灯（beacon）：状态点的循环辉光；是本皮肤唯一的循环动画 */
html[data-kami-skin="mileng"][data-kami-effects~="beacon"] .kami-root .kami-dot[data-kami-on="1"] {
  animation: kami-mil-beacon 1.8s var(--kami-ease) infinite;
}

/* 循环动画在 calm / off 与 prefers-reduced-motion 下必须直接停（契约 §3.6）；
   off 档是全场打包压到 1ms，这里对循环动画补一刀 animation:none */
html[data-kami-skin="mileng"][data-kami-motion="calm"] .kami-root .kami-dot[data-kami-on="1"],
html[data-kami-skin="mileng"][data-kami-motion="off"] .kami-root .kami-dot[data-kami-on="1"] {
  animation: none !important;
}

/* markdown：强调与插图（2026-09-24 补齐 —— 覆盖矩阵原本缺这两项） */
html[data-kami-skin="mileng"] .kami-md em { font-style: italic; color: var(--kami-accent); letter-spacing: .02em; }
html[data-kami-skin="mileng"] .kami-md del { color: var(--kami-fg-mute); text-decoration-thickness: 1px; }
html[data-kami-skin="mileng"] .kami-md img {
  display: block;
  max-width: 100%;
  margin: .6em 0;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  box-shadow: 0 4px 0 var(--kami-line);
}


/* 列表符号：显式声明，不依赖环境继承（酒馆楼层的列表样式可能被整链重置成 none，
   皮肤只给 ::marker 上色是不够的，符号必须自己声明、自己真的画出来）。
   无序：一级 disc / 二级 circle / 三级起 square；有序：decimal → lower-alpha → lower-roman */
html[data-kami-skin="mileng"] .kami-md ul { list-style-type: disc; }
html[data-kami-skin="mileng"] .kami-md ul ul { list-style-type: circle; }
html[data-kami-skin="mileng"] .kami-md ul ul ul { list-style-type: square; }
html[data-kami-skin="mileng"] .kami-md ol { list-style-type: decimal; }
html[data-kami-skin="mileng"] .kami-md ol ol { list-style-type: lower-alpha; }
html[data-kami-skin="mileng"] .kami-md ol ol ol { list-style-type: lower-roman; }
html[data-kami-skin="mileng"] .kami-md li::marker { color: var(--kami-accent); }
html[data-kami-skin="mileng"] .kami-md li li::marker { color: var(--kami-fg-mute); }

/* 特效页说明（.kami-field 里的那枚 .kami-sub）：375px 窄屏必须能换行读全。
   结构层的 .kami-sub 是 white-space:nowrap（标题栏计数确实要单行），
   这里只对「字段标签里的说明」这一处放开，不碰标题栏 / 页脚的。 */
html[data-kami-skin="mileng"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-field .kami-field-label .kami-sub {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  min-width: 0;
}

