/* 非当前模型的条目：锁死（脚本写原生 disabled） */
html[data-kami-skin="moonside"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled],
html[data-kami-skin="moonside"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover,
