/* 窄屏兜底：脚本还没写入 data-kami-layout 时按贴底抽屉处理 */
@media (max-width: 768px) {
  html[data-kami-skin="moonside"] .kami-root .kami-drop.kami-drop:not([data-kami-layout]) {
