/* 特效页说明（.kami-field 里的那枚 .kami-sub）：窄屏必须能换行读全。
   结构层的 .kami-sub 是 white-space:nowrap，这里只放开「字段标签里的说明」这一处。 */
html[data-kami-skin="moonside"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-field .kami-field-label .kami-sub {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  min-width: 0;
}

/* ==========================================================================
 * 14 · 装饰槽 = 棱镜事件（prism，身份符号）
 *      按《月之暗面》封面的画法，三段分开画在三个层上：
 *        槽位本体  ① 一条白线斜着射入 —— 角度渐变的硬边；图层的**宽只有 35.5%**，
 *                     右缘就是三角的左面，所以白线一斜到底正好停在入射面上，不悬空也不穿透；
 *                  ② 七条实色光柱 —— 锥形渐变 + 硬断点，条内没有渐变、彼此不重叠；
 *                     汇聚点在**三角内部**（自入射点沿光路往里 2px），所以七色穿过右面时
 *                     已经张开到 7.8px 高（不再是尖点），再往右继续变宽、末端渐隐收口；
 *        ::before  ③ 玻璃三角 —— clip-path 裁的 △，内边缘一条渐变白条当玻璃厚度；
 *        ::after   ④ 玻璃内的光路 —— 梯形，进场截面贴左面的入射点、出场截面贴右面的出射带，
 *                     沿 10° 走（白线 20°），一头接住白线、一头接住七色，是一条连贯光路。
 *
 *      槽位是前端在每个 .kami-head 里留的空 span（别的皮肤在这里放骰子），本皮肤不声明
 *      decor、不注入 JS，只用 CSS 把它画成棱镜，所以要先压掉结构层的 .kami-deco{display:none}。
 *      几何（槽位 126×31.5 @ fs=15，四个尺寸档同比例）：三角顶点 (41%, 11%)、两底角 (30%, 89%) / (52%, 89%)；
 *      白线止于左面 y=50% 处的入射点 E；七色汇聚点在 E 沿 10° 光路往里 2px 的三角内部；
 *      出射带落在右面上 (58.37, 15.35)–(62.75, 23.13)，竖高 7.77px。
 *      每层楼都渲染一份：零 backdrop-filter、零常驻 filter，只有 40×30 上下的
 *      blur(.4px) 一块，以及一层 mask（右端收口 + 入射光长短）。
 * ======================================================================== */
html[data-kami-skin="moonside"][data-kami-effects~="prism"] .kami-root .kami-deco[data-kami-deco="d20"] {
  display: inline-block;
  position: relative;
  flex: 0 1 auto;
  width: var(--kami-moon-prism-w);
  height: var(--kami-moon-prism-h);
  min-width: calc(var(--kami-fs) * 5.2);
  margin: 0 2px 0 0;
  pointer-events: none;
  /* 白线的斜度与停点：20deg 的图层里，65.9% 那道硬边正好穿过「右缘 × 中线」，
     也就是三角左面的入射点。四个尺寸档都是 4:1，所以改尺寸不用改这里。 */
  background-image:
    linear-gradient(20deg, rgba(255, 255, 255, 0) 62.8%, rgba(255, 255, 255, .55) 64.1%, #fff 65.9%, rgba(255, 255, 255, .5) 67.7%, rgba(255, 255, 255, 0) 69%),
    conic-gradient(from 86.35deg at 37.1% 51.1%,
      rgba(255, 45, 45, calc(var(--kami-moon-spec-alpha) / 100)) 0deg 3.9deg,
      rgba(255, 140, 26, calc(var(--kami-moon-spec-alpha) / 100)) 3.9deg 7.8deg,
      rgba(255, 214, 10, calc(var(--kami-moon-spec-alpha) / 100)) 7.8deg 11.7deg,
      rgba(53, 211, 74, calc(var(--kami-moon-spec-alpha) / 100)) 11.7deg 15.6deg,
      rgba(34, 199, 214, calc(var(--kami-moon-spec-alpha) / 100)) 15.6deg 19.5deg,
      rgba(47, 125, 255, calc(var(--kami-moon-spec-alpha) / 100)) 19.5deg 23.4deg,
      rgba(164, 91, 255, calc(var(--kami-moon-spec-alpha) / 100)) 23.4deg 27.3deg,
      rgba(164, 91, 255, 0) 27.3deg 90deg);
  background-size: 35.5% 100%, 100% 100%;
  background-position: 0 0, 0 0;
  background-repeat: no-repeat;
  /* 两块遮罩求交：一块把光柱右端渐隐收口，一块管入射光的长短（--kami-moon-beam-len）。
     认不得 mask-composite 的浏览器退化成并集 —— 只是右端收口变硬，构图不受影响。 */
  -webkit-mask-image:
    linear-gradient(90deg, #000 0 58%, rgba(0, 0, 0, .45) 84%, rgba(0, 0, 0, 0) 100%),
    linear-gradient(90deg, rgba(0, 0, 0, 0) calc(35.5% - var(--kami-moon-beam-len) - 9%), #000 calc(35.5% - var(--kami-moon-beam-len) + 9%), #000 100%);
  -webkit-mask-composite: source-in;
  mask-image:
    linear-gradient(90deg, #000 0 58%, rgba(0, 0, 0, .45) 84%, rgba(0, 0, 0, 0) 100%),
    linear-gradient(90deg, rgba(0, 0, 0, 0) calc(35.5% - var(--kami-moon-beam-len) - 9%), #000 calc(35.5% - var(--kami-moon-beam-len) + 9%), #000 100%);
  mask-composite: intersect;
}

/* ③ 玻璃三角：118deg 的渐变与左面平行，2px 白条贴着内边缘（玻璃厚度），
   底下再压一层冷色玻璃体、越往下越暗 —— 就是封面那颗深色玻璃。 */
html[data-kami-skin="moonside"][data-kami-effects~="prism"] .kami-root .kami-deco[data-kami-deco="d20"]::before {
  content: "";
  position: absolute;
  left: 30%;
  top: 11%;
  width: 22%;
  height: 78%;
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
  background-image:
    linear-gradient(118deg, rgba(255, 255, 255, .92) 0 1.6px, rgba(255, 255, 255, .30) 2.6px, rgba(255, 255, 255, 0) 10px),
    linear-gradient(62deg, rgba(255, 255, 255, .5) 0 1.2px, rgba(255, 255, 255, 0) 8px),
    linear-gradient(180deg, rgba(190, 215, 255, .10), rgba(6, 9, 14, .55) 70%);
  background-repeat: no-repeat;
}

/* ④ 玻璃内的光路：一个梯形，**进场截面贴在入射点所在的左面上、出场截面贴在出射带所在的右面上**，
   四角与两条侧面各差 0.00px —— 一头接住白线、一头接住七色带：
   入射点 E(44.73, 15.75) → 出射带 (58.37, 15.35)–(62.75, 23.13)。
   走向沿 10° 的光路（白线是 20°），入射点上留一个 10° 的折射折角。
   填充从 .95 白渐变到 .42：进场处把白线压成白色，出场处七色正好接管。 */
html[data-kami-skin="moonside"][data-kami-effects~="prism"] .kami-root .kami-deco[data-kami-deco="d20"]::after {
  content: "";
  position: absolute;
  left: 30%;
  top: 11%;
  width: 22%;
  height: 78%;
  /* 四角 = 玻璃盒坐标：入场上/下、出场上/下（由上面那四个像素坐标换算而来） */
  clip-path: polygon(27.2% 45.5%, 74.2% 48.4%, 90% 80%, 22.8% 54.5%);
  background-image: linear-gradient(100deg, rgba(255, 255, 255, .95), rgba(255, 255, 255, .62) 55%, rgba(255, 255, 255, .42) 100%);
  filter: blur(.4px);
}

/* 亮档（内页纸）：白线印成墨线，七色换印刷油墨色，玻璃改成受光的银灰三角
   （白条照旧压在灰玻璃上，折射小三角仍是白的 —— 纸上也看得见）。 */
html[data-kami-skin="moonside"][data-kami-scheme="light"][data-kami-effects~="prism"] .kami-root .kami-deco[data-kami-deco="d20"] {
  background-image:
    linear-gradient(20deg, rgba(20, 22, 27, 0) 62.8%, rgba(20, 22, 27, .5) 64.1%, rgba(20, 22, 27, .92) 65.9%, rgba(20, 22, 27, .45) 67.7%, rgba(20, 22, 27, 0) 69%),
    conic-gradient(from 86.35deg at 37.1% 51.1%,
      rgba(208, 38, 31, calc(var(--kami-moon-spec-alpha) / 100)) 0deg 3.9deg,
      rgba(201, 106, 6, calc(var(--kami-moon-spec-alpha) / 100)) 3.9deg 7.8deg,
      rgba(168, 132, 0, calc(var(--kami-moon-spec-alpha) / 100)) 7.8deg 11.7deg,
      rgba(31, 143, 56, calc(var(--kami-moon-spec-alpha) / 100)) 11.7deg 15.6deg,
      rgba(15, 143, 156, calc(var(--kami-moon-spec-alpha) / 100)) 15.6deg 19.5deg,
      rgba(28, 95, 208, calc(var(--kami-moon-spec-alpha) / 100)) 19.5deg 23.4deg,
      rgba(122, 63, 208, calc(var(--kami-moon-spec-alpha) / 100)) 23.4deg 27.3deg,
      rgba(122, 63, 208, 0) 27.3deg 90deg);
}

html[data-kami-skin="moonside"][data-kami-scheme="light"][data-kami-effects~="prism"] .kami-root .kami-deco[data-kami-deco="d20"]::before {
  background-image:
    linear-gradient(118deg, rgba(255, 255, 255, .95) 0 1.6px, rgba(255, 255, 255, .35) 2.6px, rgba(255, 255, 255, 0) 10px),
    linear-gradient(62deg, rgba(255, 255, 255, .6) 0 1.2px, rgba(255, 255, 255, 0) 8px),
    linear-gradient(180deg, rgba(120, 132, 152, .30), rgba(52, 58, 70, .45) 70%);
}

/* 窄屏兜底：消息楼层就是手机宽度时整块缩到 6.3em 宽（仍是 4:1），
   别把题头的标题与右侧动作区挤出面板。 */
@media (max-width: 420px) {
  html[data-kami-skin="moonside"][data-kami-effects~="prism"] .kami-root .kami-deco[data-kami-deco="d20"] {
    width: calc(var(--kami-fs) * 6.3);
    height: calc(var(--kami-fs) * 1.575);
  }
}


/* ==========================================================================
 * 15 · 特效二：黑胶刻槽（vinyl）
 *      外壳上一组偏心同心圆刻槽（圆心在右上角外侧，像唱片压在灯下）+ 一道斜向扫光。
 *      纯静态渐变，浓度由 --kami-moon-groove-alpha 控制（同样要 /100）。
 *      z-index:-1 让刻槽落在「面之上、字之下」—— .kami-surface 的 isolation 兜住作用域。
 * ======================================================================== */
html[data-kami-skin="moonside"][data-kami-effects~="vinyl"] .kami-surface::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  opacity: calc(var(--kami-moon-groove-alpha) / 100);
  background-image:
    repeating-radial-gradient(circle at 112% -22%, rgba(255, 255, 255, .085) 0 1px, rgba(0, 0, 0, 0) 1px 11px),
    repeating-radial-gradient(circle at 118% -30%, rgba(255, 255, 255, .06) 0 1px, rgba(0, 0, 0, 0) 1px 7px),
    linear-gradient(118deg, rgba(255, 255, 255, 0) 34%, rgba(255, 255, 255, .05) 52%, rgba(255, 255, 255, 0) 70%);
}

/* 亮档：内页纸上的刻槽是压出来的暗痕，扫光改成提亮纸面 */
html[data-kami-skin="moonside"][data-kami-scheme="light"][data-kami-effects~="vinyl"] .kami-surface::before {
  background-image:
    repeating-radial-gradient(circle at 112% -22%, rgba(20, 22, 27, .085) 0 1px, rgba(0, 0, 0, 0) 1px 11px),
    repeating-radial-gradient(circle at 118% -30%, rgba(20, 22, 27, .06) 0 1px, rgba(0, 0, 0, 0) 1px 7px),
    linear-gradient(118deg, rgba(255, 255, 255, 0) 34%, rgba(255, 255, 255, .20) 52%, rgba(255, 255, 255, 0) 70%);
}

/* ==========================================================================
 * 16 · 特效三：心跳线（pulse）
 *      页脚上方一条 2px 的频谱细带，用 clip-path 裁成心电波形 —— 只走状态区这一条线，
 *      绝不铺满。默认动效档下让色带沿波形缓慢流过（往返，不跳帧）；calm / off /
 *      prefers-reduced-motion 下停帧，波形仍在原处。
 *      只在**面板页脚**上动画：消息楼层每个「行动选项」组件都有一份页脚，
 *      那边保持静态（省掉按楼层线性增长的逐帧重绘）。
 * ======================================================================== */
html[data-kami-skin="moonside"][data-kami-effects~="pulse"] .kami-root .kami-foot {
  position: relative;
  padding-top: calc(var(--kami-pad-y) + 10px);
}

html[data-kami-skin="moonside"][data-kami-effects~="pulse"] .kami-root .kami-foot::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 16px;
  transform: translateY(-50%);
  pointer-events: none;
  background-image: linear-gradient(90deg,
    rgba(255, 47, 47, calc(var(--kami-moon-spec-alpha) / 100)),
    rgba(255, 122, 31, calc(var(--kami-moon-spec-alpha) / 100)),
    rgba(255, 226, 61, calc(var(--kami-moon-spec-alpha) / 100)),
    rgba(63, 219, 118, calc(var(--kami-moon-spec-alpha) / 100)),
    rgba(63, 141, 255, calc(var(--kami-moon-spec-alpha) / 100)),
    rgba(168, 107, 255, calc(var(--kami-moon-spec-alpha) / 100)));
  background-size: 200% 100%;
  background-repeat: no-repeat;
  clip-path: polygon(0 44%, 30% 44%, 34% 44%, 37% 12%, 40% 76%, 43% 44%, 58% 44%, 62% 44%, 65% 26%, 68% 62%, 71% 44%, 100% 44%, 100% 56%, 71% 56%, 68% 74%, 65% 38%, 62% 56%, 58% 56%, 43% 56%, 40% 88%, 37% 24%, 34% 56%, 30% 56%, 0 56%);
  opacity: .85;
}

/* 面板页脚这一条会走：色带沿波形往返流动 */
html[data-kami-skin="moonside"][data-kami-effects~="pulse"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-foot::before {
  animation: kami-moon-trace 5.2s ease-in-out infinite alternate;
}

@keyframes kami-moon-trace {
  from { background-position-x: 0%; }
  to { background-position-x: 100%; }
}

/* 动效关 / calm / 减动效：波形留着，但不再流动 */
html[data-kami-skin="moonside"][data-kami-effects~="pulse"][data-kami-motion="calm"] .kami-root .kami-foot::before,
html[data-kami-skin="moonside"][data-kami-effects~="pulse"][data-kami-motion="off"] .kami-root .kami-foot::before {
  animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="moonside"][data-kami-effects~="pulse"] .kami-root .kami-foot::before { animation: none !important; }
}

/* ==========================================================================
 * 17 · 特效四：失焦拖影（ghost，默认关）
 *      题头文字轻微拖影：一条贴边的锐影 + 两条错位的柔影，不引入任何彩色。
 * ======================================================================== */
html[data-kami-skin="moonside"][data-kami-effects~="ghost"] .kami-title,
html[data-kami-skin="moonside"][data-kami-effects~="ghost"] .kami-card-title {
  text-shadow: 0 0 .6px rgba(255, 255, 255, .55), 1.4px 0 2.4px rgba(255, 255, 255, .22), -1px 0 2px rgba(255, 255, 255, .14);
}

/* 亮档：纸上的拖影是墨影 */
html[data-kami-skin="moonside"][data-kami-scheme="light"][data-kami-effects~="ghost"] .kami-title,
html[data-kami-skin="moonside"][data-kami-scheme="light"][data-kami-effects~="ghost"] .kami-card-title {
  text-shadow: 0 0 .6px rgba(20, 22, 27, .5), 1.4px 0 2.4px rgba(20, 22, 27, .18), -1px 0 2px rgba(20, 22, 27, .12);
}

/* ==========================================================================
 * 18 · 窄面板（容器查询）：面板本体是查询容器（container-type 见 §13）
 *      窄到放不下「序号列 + 棱镜 + 标题」时：棱镜再收一档、序号列隐去，
 *      让标题与右侧的动作区先活下来。不支持容器查询的浏览器直接吃上面的默认值。
 * ======================================================================== */
@container (max-width: 340px) {
  html[data-kami-skin="moonside"][data-kami-effects~="prism"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-deco[data-kami-deco="d20"] {
    width: calc(var(--kami-fs) * 5.6);
    height: calc(var(--kami-fs) * 1.4);
  }

  html[data-kami-skin="moonside"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-head::before,
  html[data-kami-skin="moonside"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-field::before {
    display: none;
  }
}

/* Native search/model menu rows: keep an opaque surface and a paired foreground. */
html[data-kami-skin="moonside"] .kami-root select option,
html[data-kami-skin="moonside"] .kami-root select optgroup {
  color: var(--kami-fg) !important;
  background-color: var(--kami-card-2) !important;
  color-scheme: inherit !important;
}
html[data-kami-skin="moonside"] .kami-root select option:checked {
  color: var(--kami-accent-fg) !important;
  background-color: var(--kami-accent) !important;
}
html[data-kami-skin="moonside"] .kami-root select option:disabled:not(:checked) { color: var(--kami-fg-dim) !important; }/* Shared component roles: descriptions follow the selectable surface foreground. */
html[data-kami-skin="moonside"] .kami-root [data-kami-ui="choiceCard"][data-kami-card-role="choice"] > .kami-card-note { color:inherit; opacity:1; }
html[data-kami-skin="moonside"] .kami-root [data-kami-ui="field"] > .kami-card-note { color:var(--kami-fg-dim); opacity:1; }
html[data-kami-skin="moonside"] .kami-root [data-kami-ui="tabs"] .kami-tab[aria-selected="true"] { color:var(--kami-fg); }

html[data-kami-skin="moonside"] .kami-root [data-kami-ui="empty"] { color:var(--kami-fg-dim); }
html[data-kami-skin="moonside"] .kami-root [data-kami-ui="steps"] .is-current :is(strong,small) { color:var(--kami-fg); }

/* ==== 全局层令牌上提（build/sync-tavern.mjs 生成，勿手改；把 --kami-* 令牌同时定义到 <html>，契约 §3）==== */
html[data-kami-skin="moonside"] {
