"},{"id":"nixie","name":"辉光管","button":"辉光管","scheme":"dark","tagline":"一台老式计数仪器：暗金属外壳配蚀刻铭牌，真空管内亮着暖橙色的阴极读数。","effects":[{"id":"idle","label":"市电呼吸","desc":"发光数码管呈现缓慢起伏的明暗闪烁与极微弱的电压瞬闪。","default":true},{"id":"strike","label":"起辉动效","desc":"面板展开与切换时，一道琥珀色光带自上而下扫过金属外壳。","default":true},{"id":"vacuum","label":"真空玻璃","desc":"灯管顶部呈现弧形反光高光、管壁暗角与内部透视灯丝。","default":true},{"id":"stack","label":"阴极层叠","desc":"选项卡片底层叠加未通电金属暗层，悬停时向外滑出抽离。","default":true},{"id":"counter","label":"阴极编号","desc":"选项左侧显示蚀刻金属编号，悬停激活时通电点亮为暖橙数码。","default":false},{"id":"halo","label":"过载溢光","desc":"辉光管周围向暗金属面板漫射大面积琥珀色柔和强光晕。","default":false}],"params":[{"id":"glow","label":"辉光半径","group":"光照","token":"--kami-glow-size","unit":"px","min":0,"max":24,"step":1,"value":9},{"id":"halo","label":"溢光强度","group":"光照","token":"--kami-nixie-halo","unit":"%","min":0,"max":100,"step":5,"value":55},{"id":"stack","label":"层叠间距","group":"材质","token":"--kami-nixie-stack","unit":"px","min":0,"max":10,"step":1,"value":4},{"id":"mesh","label":"阳极网浓度","group":"材质","token":"--kami-nixie-mesh","unit":"%","min":0,"max":140,"step":5,"value":100}],"css":"/* ============================================================================
 * 卡密预设 · 皮肤：辉光管 (nixie)
 * ----------------------------------------------------------------------------
 * 概念：一个位置叠着十片阴极，同一时刻只允许一片通电。
 *   · 状态律：每个位置上只有一个「亮」，其余保持为可见的暗金属。
 *   · 光律：光只向下、向外洒（灯丝在面板上方），永不对称。
 *   · 排版律：铭牌是蚀刻的，只有数字发光。
 * 纯 CSS：无 JS、无外部资源、无 @import、无 vh、无 position:fixed 铺满。
 * 消息楼层 iframe 内不使用 filter / backdrop-filter（只在面板作用域内出现）。
 * ========================================================================== */

/* ==========================================================================
 * 1 · 令牌（暗色 = 正典）
 * ======================================================================== */
html[data-kami-skin="nixie"] .kami-root {
  /* —— 风格性文案令牌（契约 §3.7：只此三处；中性占位值，等专职文案 Agent 统一重写） —— */
  --kami-label-think-title: 演算;
  --kami-label-think-title-open: 演算明细;
  --kami-label-options-title: 指令;

  /* —— 色彩与背景：暖调暗金属漆，不是纯黑 —— */
  --kami-fg: #d9d2c4;
  --kami-fg-dim: #a49c8e;
  --kami-fg-mute: #9c9384;
  --kami-accent: #e8862c;
  --kami-accent-fg: #1b1105;
  --kami-accent-soft: rgba(232, 134, 44, .13);
  --kami-accent-line: rgba(232, 134, 44, .42);
  --kami-bg: #191612;
  --kami-bg-soft: #120f0c;
  --kami-card: #1f1b15;
  --kami-card-2: #13100d;
  --kami-card-hover: #272119;
  --kami-line: rgba(255, 228, 196, .10);
  --kami-line-strong: rgba(255, 186, 112, .46);
  --kami-t1: rgba(255, 235, 210, .035);
  --kami-t2: rgba(255, 235, 210, .075);
  --kami-t3: rgba(255, 235, 210, .145);
  --kami-warn: #e2705c;
  --kami-shadow: 0 14px 30px -18px rgba(0, 0, 0, .9), 0 2px 6px -2px rgba(0, 0, 0, .55);
  --kami-shadow-sm: 0 3px 8px -4px rgba(0, 0, 0, .75);
  --kami-blur: 0px;

  /* —— 布局与尺寸 —— */
  --kami-r-xs: 2px;
  --kami-r-sm: 3px;
  --kami-r-md: 4px;
  --kami-r-lg: 6px;
  --kami-r-pill: 2px;
  --kami-border-w: 1px;
  --kami-pad-x: 10px;
  --kami-pad-y: 7px;
  --kami-pad-lg-x: 13px;
  --kami-pad-lg-y: 11px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 40px;
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 15.5rem;
  --kami-panel-w: 840px;
  --kami-panel-h: 1120px;
  --kami-list-dir: column;
  --kami-justify: stretch;

  /* —— 文本与排版（只有一套字体：靠字重/字距/蚀刻与发光区分层级） —— */
  --kami-fs-scale: 1;
  --kami-fs: calc(15px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .78);
  --kami-fs-sm: calc(var(--kami-fs) * .88);
  --kami-fs-lg: calc(var(--kami-fs) * 1.12);
  --kami-lh: 1.68;
  --kami-ls: .012em;
  --kami-ls-title: .18em;
  --kami-font: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans SC", sans-serif;
  --kami-font-title: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans SC", sans-serif;
  --kami-font-mono: ui-monospace, SFMono-Regular, "Cascadia Mono", Consolas, "Roboto Mono", "DejaVu Sans Mono", monospace;
  --kami-fw: 400;
  --kami-fw-title: 600;
  --kami-title-transform: uppercase;

  /* —— 皮肤私有材质/光照旋钮（面板参数页会写这三个） —— */
  --kami-nixie-mesh: 100;
  --kami-nixie-stack: 4px;
  --kami-nixie-halo: 55;
  --kami-nixie-halo-cap: 1;
  --kami-nixie-glow-cap: 1;
  --kami-nixie-halo-r: calc(var(--kami-glow-size) * var(--kami-nixie-glow-cap));

  /* —— 装饰与特效：拉丝 + 阳极竖丝 + 支撑横丝 + 顶光 —— */
  --kami-texture:
    repeating-linear-gradient(0deg, rgba(255, 255, 255, calc(.010 * var(--kami-nixie-mesh) / 100)) 0 1px, transparent 1px 3px),
    repeating-linear-gradient(90deg, rgba(255, 232, 204, calc(.022 * var(--kami-nixie-mesh) / 100)) 0 1px, transparent 1px 4px),
    repeating-linear-gradient(0deg, rgba(255, 232, 204, calc(.030 * var(--kami-nixie-mesh) / 100)) 0 1px, transparent 1px 24px),
    radial-gradient(140% 100% at 50% -10%, rgba(255, 138, 32, calc(.055 * var(--kami-nixie-halo) / 100 * var(--kami-nixie-halo-cap))), transparent 62%);
  --kami-glow: #ff8a20;
  --kami-glow-size: 9px;
  --kami-surface-clip: none;
  --kami-accent-mark: 3px;

  /* —— 动画与过渡：机械落位，永不过冲（开关是唯一例外） —— */
  --kami-dur-fast: .09s;
  --kami-dur: .17s;
  --kami-dur-slow: .34s;
  --kami-ease: cubic-bezier(.2, .72, .24, 1);
  --kami-ease-out: cubic-bezier(.4, 0, .1, 1);
  --kami-enter-y: 2px;
  --kami-enter-scale: 1;
  --kami-stagger: 32ms;

  /* —— 语义色：七只不同充气的小指示灯，不是彩虹 —— */
  --kami-kind-action: #e8862c;
  --kami-kind-persona: #a685d8;
  --kami-kind-plot: #6fb98a;
  --kami-kind-info: #63b9c9;
  --kami-kind-fun: #d9b23f;
  --kami-kind-nsfw: #d9637f;
  --kami-kind-other: #9a9186;

  box-sizing: border-box;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  font-weight: var(--kami-fw);
  line-height: var(--kami-lh);
  letter-spacing: var(--kami-ls);
  font-variant-numeric: tabular-nums;
  text-align: left;
  text-rendering: optimizeLegibility;
  word-break: break-word;
  -webkit-tap-highlight-color: transparent;
}
html[data-kami-skin="nixie"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) {
  margin: 10px 0 8px;
