/* 焦点：1px 琥珀描边 + 2px 偏移 + 1px 底板隔离环（几何，不是色相） */
html[data-kami-skin="nixie"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
