}

/* ==========================================================================
 * 2 · 表面：仪器面板（材质在这里出现一次，卡片一律是平的）
 * ======================================================================== */
html[data-kami-skin="nixie"] .kami-surface {
  position: relative;
  isolation: isolate;
  clip-path: var(--kami-surface-clip);
}
html[data-kami-skin="nixie"] .kami-shell,
html[data-kami-skin="nixie"] .kami-drop {
  background-color: var(--kami-bg);
  background-image: var(--kami-texture);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  color: var(--kami-fg);
  box-shadow:
    inset 0 1px 0 rgba(255, 236, 214, .055),
    inset 0 -1px 0 rgba(0, 0, 0, .5),
    var(--kami-shadow-sm);
}
html[data-kami-skin="nixie"] .kami-shell { display: block; }

/* 真空玻璃：顶部接光高光 + 内壁暗角 + 玻璃环（静态内阴影，零运行时；不占用伪元素） */
html[data-kami-skin="nixie"][data-kami-effects~="vacuum"] .kami-root .kami-surface {
  box-shadow:
    inset 0 1px 0 rgba(255, 240, 220, .085),
    inset 1px 0 0 rgba(255, 236, 214, .02),
