    inset 0 -14px 26px -20px rgba(0, 0, 0, .95),
    inset 0 0 34px -14px rgba(0, 0, 0, .6);
}
/* 面板与外壳本身的不透明底色 + 顶部接光，就是「玻璃罩」的全部；不用模糊、不用模糊层 */

/* ==========================================================================
 * 3 · 头部 / 铭牌 / 读数窗
 * ======================================================================== */
html[data-kami-skin="nixie"] .kami-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  background-image: linear-gradient(90deg, var(--kami-line) 0, var(--kami-line) 62%, rgba(255, 228, 196, 0) 100%);
  background-repeat: no-repeat;
  background-position: 0 100%;
  background-size: 100% 1px;
}
html[data-kami-skin="nixie"] .kami-head:not(.kami-collapse-head) {
  min-height: calc(var(--kami-row-h) - 6px);
  padding-top: var(--kami-pad-y);
  padding-bottom: var(--kami-pad-y);
}
html[data-kami-skin="nixie"] .kami-collapse-head { cursor: pointer; user-select: none; }
html[data-kami-skin="nixie"] .kami-collapse[data-kami-open="0"] > .kami-collapse-head {
