/* 灯珠：玻璃珠 + 灯丝（未通电也看得见那根丝） */
html[data-kami-skin="nixie"] .kami-dot {
  position: relative;
  flex: none;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background-color: #1b1611;
  background-image: radial-gradient(circle at 50% 46%, #8a5c2c, #2a1d12 66%, #15110d 100%);
