}
html[data-kami-skin="nixie"] .kami-dot::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 1px;
  height: 5px;
  margin: -2.5px 0 0 -.5px;
  background: rgba(255, 206, 158, .55);
  box-shadow: 0 0 2px rgba(255, 190, 130, .45);
