  border-radius: var(--kami-r-lg);
  border-color: var(--kami-line-strong);
  background-image:
    radial-gradient(circle at 7px 7px, rgba(255, 236, 214, .10) 0 1px, rgba(0, 0, 0, 0) 1.7px),
    radial-gradient(circle at calc(100% - 7px) 7px, rgba(255, 236, 214, .10) 0 1px, rgba(0, 0, 0, 0) 1.7px),
    radial-gradient(circle at 7px calc(100% - 7px), rgba(255, 236, 214, .07) 0 1px, rgba(0, 0, 0, 0) 1.7px),
    radial-gradient(circle at calc(100% - 7px) calc(100% - 7px), rgba(255, 236, 214, .07) 0 1px, rgba(0, 0, 0, 0) 1.7px),
