  box-shadow: var(--kami-shadow-sm), inset 0 -1px 0 var(--kami-accent), 0 calc(var(--kami-nixie-halo-r) * .35) var(--kami-nixie-halo-r) -4px rgba(255, 138, 32, .5);
  animation: kami-nixie-sweep var(--kami-dur) var(--kami-ease-out) both;
}
