  mix-blend-mode: screen;
  background-image: radial-gradient(140% 100% at 50% -8%, rgba(255, 138, 32, calc(.075 * var(--kami-nixie-halo) / 100 * var(--kami-nixie-halo-cap))), rgba(0, 0, 0, 0) 62%);
  opacity: .9;
  animation: kami-nixie-mains 9.3s var(--kami-ease) infinite;
}

/* —— strike · 起辉：一道 1px 琥珀前缘从上往下扫过（纯 transform） —— */
html[data-kami-skin="nixie"][data-kami-effects~="strike"] .kami-root .kami-surface::before {
  content: "";
  position: absolute;
  inset: 0;
