  16% { box-shadow: inset 0 1px 0 rgba(255, 236, 214, .16), inset 0 -1px 0 rgba(0, 0, 0, .5), var(--kami-shadow-sm), 0 0 calc(var(--kami-nixie-halo-r) * 2.2) -4px rgba(255, 138, 32, .55); }
  100% { box-shadow: inset 0 1px 0 rgba(255, 236, 214, .055), inset 0 -1px 0 rgba(0, 0, 0, .5), var(--kami-shadow-sm); }
}

/* —— halo · 过载溢光：加大电流，只在大屏上有意义 —— */
