}

/* ==========================================================================
 * 15 · 关键帧
 * ======================================================================== */
@keyframes kami-nixie-mains {
  0% { opacity: .92; }
  7% { opacity: .85; }
  13% { opacity: .96; }
  28% { opacity: .9; }
  41% { opacity: .95; }
  57% { opacity: .88; }
  63% { opacity: .97; }
  79% { opacity: .89; }
  93% { opacity: .94; }
  96% { opacity: .58; }
