}

/* ==========================================================================
 * 3 · 档位响应：明暗方案 / 密度档位 / 动效档位
 * ======================================================================== */
/* 3.1 明暗方案：暗色（宵樱古社） */
html[data-kami-skin="senren"][data-kami-scheme="dark"] .kami-root {
  --kami-fg: #f7edf1;            /* 粉白樱墨，对 bg 15.12:1，对 card 12.84:1 */
  --kami-fg-dim: #cbbbc2;        /* 淡粉雾灰，对 card-2 8.53:1 */
  --kami-fg-mute: #9e8e95;       /* 暮色灰，对 card 5.20:1 */
  --kami-accent: #e67897;        /* 宵樱粉，对暗底 8.21:1 */
  --kami-accent-fg: #1c1116;     /* 樱粉底上的黑墨字，9.82:1 */
  --kami-accent-soft: rgba(230, 120, 151, 0.18);
  --kami-accent-line: rgba(230, 120, 151, 0.55);

  --kami-bg: #1c1619;            /* 宵樱玄色底 */
  --kami-bg-soft: #251e22;       /* 次级暗和纸底 */
  --kami-card: #2c2328;          /* 暗紫樱和纸卡面 */
  --kami-card-2: #20181d;        /* 卡片内暗墨底 */
  --kami-card-hover: #382d33;    /* 暗档悬停底 */
  --kami-line: rgba(247, 237, 241, 0.15);
  --kami-line-strong: rgba(212, 175, 55, 0.55); /* 暗夜描金线 */
  --kami-t1: rgba(247, 237, 241, 0.05);
  --kami-t2: rgba(247, 237, 241, 0.09);
  --kami-t3: rgba(247, 237, 241, 0.18);
  --kami-warn: #ff7588;          /* 明绯红 */
  --kami-shadow: 0 8px 24px -8px rgba(0, 0, 0, 0.65), 0 2px 8px rgba(0, 0, 0, 0.4);
  --kami-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.35);

  /* 暗档七种语义色 */
  --kami-kind-action: #7ab4f2;
  --kami-kind-persona: #ea8ac2;
  --kami-kind-plot: #6ec999;
  --kami-kind-info: #5bc3db;
  --kami-kind-fun: #e8a855;
  --kami-kind-nsfw: #f26b80;
  --kami-kind-other: #b5a6ad;
}

/* 3.2 密度档位 */
html[data-kami-skin="senren"][data-kami-density="compact"] .kami-root {
  --kami-pad-x: 9px;
  --kami-pad-y: 5px;
  --kami-pad-lg-x: 12px;
  --kami-pad-lg-y: 10px;
  --kami-gap: 6px;
  --kami-gap-lg: 9px;
  --kami-row-h: 32px;
}

html[data-kami-skin="senren"][data-kami-density="roomy"] .kami-root {
  --kami-pad-x: 15px;
  --kami-pad-y: 10px;
  --kami-pad-lg-x: 20px;
  --kami-pad-lg-y: 18px;
  --kami-gap: 10px;
  --kami-gap-lg: 15px;
  --kami-row-h: 44px;
}

/* 3.3 动效档位与减动效响应 */
html[data-kami-skin="senren"][data-kami-motion="calm"] .kami-root {
  --kami-dur-fast: 0.08s;
  --kami-dur: 0.14s;
  --kami-dur-slow: 0.2s;
  --kami-enter-y: 2px;
  --kami-stagger: 10ms;
}

html[data-kami-skin="senren"][data-kami-motion="off"] .kami-root {
  --kami-dur-fast: 1ms;
  --kami-dur: 1ms;
  --kami-dur-slow: 1ms;
  --kami-enter-y: 0px;
  --kami-enter-scale: 1;
  --kami-stagger: 0ms;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="senren"] .kami-root {
    --kami-dur-fast: 1ms;
    --kami-dur: 1ms;
    --kami-dur-slow: 1ms;
    --kami-enter-y: 0px;
    --kami-enter-scale: 1;
    --kami-stagger: 0ms;
  }
}

/* ==========================================================================
 * 4 · 焦点与可访问性
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

/* ==========================================================================
 * 5 · 控件对比度四件套（!important 阻击宿主与用户自定义 CSS 污染）
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-number,
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-text,
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-textarea,
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
