  color: var(--kami-fg) !important;
  color-scheme: light !important;
}

html[data-kami-skin="senren"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-number,
html[data-kami-skin="senren"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-text,
html[data-kami-skin="senren"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-textarea,
html[data-kami-skin="senren"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
  background-color: var(--kami-card) !important;
  color: var(--kami-fg) !important;
  color-scheme: dark !important;
}

/* 数字框右对齐仅挂在 input.kami-number[type="number"] 上 */
html[data-kami-skin="senren"] .kami-root input.kami-number[type="number"] {
  text-align: right;
}

/* ==========================================================================
 * 6 · 结构与等高约束、预览窗隔离
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

html[data-kami-skin="senren"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}

html[data-kami-skin="senren"] .kami-root .kami-pv,
html[data-kami-skin="senren"] .kami-root .kami-pv-frame,
html[data-kami-skin="senren"] .kami-root .kami-guide-pv,
html[data-kami-skin="senren"] .kami-root .kami-guide-pv-frame {
  pointer-events: none;
}

/* ==========================================================================
 * 7 · 关键帧动画定义（入场 / 强调 / 循环 / 流光）
 * ======================================================================== */
@keyframes kami-senren-in {
  from {
    opacity: 0;
    transform: translateY(var(--kami-enter-y)) scale(var(--kami-enter-scale));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes kami-senren-drift {
  0% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-2px) rotate(2deg); }
  100% { transform: translateY(0) rotate(0deg); }
}

@keyframes kami-senren-glow {
  0%, 100% {
    opacity: 0.85;
    box-shadow: 0 0 calc(var(--kami-glow-size) * 0.7) var(--kami-glow);
  }
  50% {
    opacity: 1;
    box-shadow: 0 0 calc(var(--kami-glow-size) * 1.3) var(--kami-glow), 0 0 2px rgba(184, 138, 68, 0.4);
  }
}

@keyframes kami-senren-shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

@keyframes kami-senren-beat {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.18); }
}

/* 循环动画在 calm / off 与 prefers-reduced-motion 下直接停用 */
html[data-kami-skin="senren"][data-kami-motion="calm"] .kami-root .kami-dot[data-kami-on="1"],
html[data-kami-skin="senren"][data-kami-motion="off"] .kami-root .kami-dot[data-kami-on="1"],
html[data-kami-skin="senren"][data-kami-motion="calm"][data-kami-effects~="sakura"] .kami-shell::before,
html[data-kami-skin="senren"][data-kami-motion="calm"][data-kami-effects~="sakura"] .kami-drop::before,
html[data-kami-skin="senren"][data-kami-motion="off"][data-kami-effects~="sakura"] .kami-shell::before,
html[data-kami-skin="senren"][data-kami-motion="off"][data-kami-effects~="sakura"] .kami-drop::before {
  animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="senren"] .kami-root .kami-dot[data-kami-on="1"],
  html[data-kami-skin="senren"][data-kami-effects~="sakura"] .kami-shell::before,
  html[data-kami-skin="senren"][data-kami-effects~="sakura"] .kami-drop::before {
    animation: none !important;
  }
}

/* ==========================================================================
 * 8 · 消息楼层外壳与纸面
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-shell {
  position: relative;
  display: block;
  background-color: var(--kami-bg);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
  overflow: hidden;
  transition: border-color var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}

/* 和纸材质纹理层 */
html[data-kami-skin="senren"] .kami-surface {
  background-image: var(--kami-texture);
}

html[data-kami-skin="senren"] .kami-head {
