html[data-kami-skin="senren"] .kami-root:not([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-title::before,
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-drop > .kami-head .kami-title::before {
  content: "";
