}

html[data-kami-skin="senren"] .kami-actions {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-left: auto;
}

/* 状态点：和风朱砂小印 */
html[data-kami-skin="senren"] .kami-dot {
  flex: none;
  width: 10px;
  height: 10px;
  border-radius: 50%;
