  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  overflow-x: auto;
}

html[data-kami-skin="senren"] .kami-md pre code {
  background: transparent;
  padding: 0;
  color: inherit;
}

html[data-kami-skin="senren"] .kami-md ul,
html[data-kami-skin="senren"] .kami-md ol {
  margin: 0.6em 0;
  padding-left: 1.4em;
}

html[data-kami-skin="senren"] .kami-md li {
  margin: 0.25em 0;
}

html[data-kami-skin="senren"] .kami-md strong {
  color: var(--kami-fg);
  font-weight: 700;
}

html[data-kami-skin="senren"] .kami-md a {
  color: var(--kami-accent);
  text-decoration: underline;
  text-underline-offset: 3px;
}

html[data-kami-skin="senren"] .kami-md hr {
  border: 0;
  border-top: var(--kami-border-w) solid var(--kami-line);
  margin: 1em 0;
}

html[data-kami-skin="senren"] .kami-md table {
  border-collapse: collapse;
  width: 100%;
  font-size: var(--kami-fs-sm);
  margin: 0.8em 0;
}

html[data-kami-skin="senren"] .kami-md th,
html[data-kami-skin="senren"] .kami-md td {
  border: var(--kami-border-w) solid var(--kami-line);
  padding: 6px 10px;
}

html[data-kami-skin="senren"] .kami-md th {
  background-color: var(--kami-bg-soft);
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
}

/* ── 2026-09-25 补齐（原缺 em / img / ::marker / 嵌套列表 / 首尾边距）──────
   造型走千恋万花自己的语言：樱色 ::marker、和纸卡底引用、描金细线表格。 */
html[data-kami-skin="senren"] .kami-md > :first-child { margin-top: 0; }
html[data-kami-skin="senren"] .kami-md > :last-child { margin-bottom: 0; }

html[data-kami-skin="senren"] .kami-md em {
  font-style: italic;
  color: var(--kami-fg-dim);
}

html[data-kami-skin="senren"] .kami-md del {
  opacity: .7;
  text-decoration-thickness: 1px;
}

/* 列表：行距、::marker 上樱色、嵌套层换形状 + 换淡墨 */
html[data-kami-skin="senren"] .kami-md li {
  margin: 0.28em 0;
  line-height: var(--kami-lh);
}

html[data-kami-skin="senren"] .kami-md ul { list-style-type: disc; }
html[data-kami-skin="senren"] .kami-md ul ul { list-style-type: circle; }
html[data-kami-skin="senren"] .kami-md ol { list-style-type: decimal; }
html[data-kami-skin="senren"] .kami-md ol ol { list-style-type: lower-alpha; }

html[data-kami-skin="senren"] .kami-md li::marker {
  color: var(--kami-accent);
  font-weight: 700;
}

/* 嵌套层的记号再淡一档：子级一眼可辨 */
html[data-kami-skin="senren"] .kami-md ul ul > li::marker,
html[data-kami-skin="senren"] .kami-md ol ol > li::marker,
html[data-kami-skin="senren"] .kami-md ul ul ul > li::marker,
html[data-kami-skin="senren"] .kami-md ol ol ol > li::marker {
  color: var(--kami-fg-mute);
  font-weight: 400;
}

html[data-kami-skin="senren"] .kami-md ul ul,
html[data-kami-skin="senren"] .kami-md ul ol,
html[data-kami-skin="senren"] .kami-md ol ul,
html[data-kami-skin="senren"] .kami-md ol ol {
  margin: 0.2em 0;
  padding-left: 1.25em;
}

/* 图片：描金细框 */
html[data-kami-skin="senren"] .kami-md img {
  max-width: 100%;
  height: auto;
  display: block;
  margin: 0.6em 0;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
}

html[data-kami-skin="senren"] .kami-raw {
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-sm);
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-all;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  background-color: var(--kami-card-2);
  border-radius: var(--kami-r-sm);
  border: var(--kami-border-w) solid var(--kami-line);
  color: var(--kami-fg-dim);
}

/* ==========================================================================
 * 12 · 列表与卡片系统
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  gap: var(--kami-gap);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="senren"] .kami-card {
  position: relative;
  background-color: var(--kami-card);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  box-shadow: var(--kami-shadow-sm);
  transition: border-color var(--kami-dur) var(--kami-ease),
              box-shadow var(--kami-dur) var(--kami-ease),
              transform var(--kami-dur) var(--kami-ease),
              background-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="senren"] .kami-item {
  display: flex;
  align-items: flex-start;
  gap: var(--kami-gap);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  cursor: pointer;
  text-align: left;
  user-select: none;
  border-left: var(--kami-accent-mark) solid transparent;
}

@media (hover: hover) {
  html[data-kami-skin="senren"] .kami-item:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-line-strong);
    border-left-color: var(--kami-accent);
    transform: translateY(-1px);
    box-shadow: var(--kami-shadow);
  }
}

html[data-kami-skin="senren"] .kami-item:active {
  transform: translateY(1px);
}

/* 选中态：四重可视差异（字重 + 樱红左边条 + 浅樱底色 + 描金细边） */
html[data-kami-skin="senren"] .kami-item.is-on,
html[data-kami-skin="senren"] .kami-item[aria-pressed="true"] {
  border-color: var(--kami-accent);
  border-left-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
  font-weight: var(--kami-fw-title);
  box-shadow: inset 0 0 0 1px var(--kami-accent-line);
}

html[data-kami-skin="senren"] .kami-item.is-done {
  border-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
}

html[data-kami-skin="senren"] .kami-item[data-kami-busy="1"] {
  opacity: 0.7;
  pointer-events: none;
}

html[data-kami-skin="senren"] .kami-item.is-demo {
  opacity: 0.65;
  cursor: default;
}

html[data-kami-skin="senren"] .kami-item-main {
  flex: 1 1 auto;
  min-width: 0;
}

html[data-kami-skin="senren"] .kami-item-side {
  flex: none;
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
}

/* 卡片头部与标题 */
html[data-kami-skin="senren"] .kami-card-head {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  width: 100%;
  margin-bottom: 6px;
  border-radius: 0;
  background: transparent;
  border: none;
  padding: 0;
  text-align: left;
}

html[data-kami-skin="senren"] .kami-card-title {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="senren"] .kami-card-note {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
  margin-top: 4px;
}

html[data-kami-skin="senren"] .kami-card-body {
  display: block;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
}

/* ==========================================================================
 * 13 · 小标签 / 徽章 / 和风短册与七种语义色
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-chip,
html[data-kami-skin="senren"] .kami-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  flex: none;
  padding: 2px 8px;
  border-radius: var(--kami-r-xs);
  font-size: var(--kami-fs-xs);
  font-weight: var(--kami-fw-title);
  line-height: 1.2;
  border: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-card-2);
  color: var(--kami-fg-dim);
  white-space: nowrap;
}

/* 语义色变量映射 */
html[data-kami-skin="senren"] .kami-root [data-kami-kind="action"]  { --kami-kind-curr: var(--kami-kind-action); }
html[data-kami-skin="senren"] .kami-root [data-kami-kind="persona"] { --kami-kind-curr: var(--kami-kind-persona); }
html[data-kami-skin="senren"] .kami-root [data-kami-kind="plot"]    { --kami-kind-curr: var(--kami-kind-plot); }
html[data-kami-skin="senren"] .kami-root [data-kami-kind="info"]    { --kami-kind-curr: var(--kami-kind-info); }
html[data-kami-skin="senren"] .kami-root [data-kami-kind="fun"]     { --kami-kind-curr: var(--kami-kind-fun); }
html[data-kami-skin="senren"] .kami-root [data-kami-kind="nsfw"]    { --kami-kind-curr: var(--kami-kind-nsfw); }
html[data-kami-skin="senren"] .kami-root [data-kami-kind="other"]   { --kami-kind-curr: var(--kami-kind-other); }

html[data-kami-skin="senren"] .kami-chip[data-kami-kind],
html[data-kami-skin="senren"] .kami-badge[data-kami-kind] {
  color: var(--kami-kind-curr, var(--kami-accent));
  border-color: var(--kami-kind-curr, var(--kami-accent));
  background-color: var(--kami-card);
}

html[data-kami-skin="senren"] .kami-root .kami-card[data-kami-kind],
html[data-kami-skin="senren"] .kami-root .kami-item[data-kami-kind] {
  border-left: var(--kami-accent-mark) solid var(--kami-kind-curr, var(--kami-accent-line));
}

/* 七种语义色在徽章与小标签上的专用视觉呈现 */
html[data-kami-skin="senren"] .kami-root .kami-chip[data-kami-kind="action"],
html[data-kami-skin="senren"] .kami-root .kami-badge[data-kami-kind="action"] {
  border-color: var(--kami-kind-action);
  color: var(--kami-kind-action);
}
html[data-kami-skin="senren"] .kami-root .kami-chip[data-kami-kind="persona"],
html[data-kami-skin="senren"] .kami-root .kami-badge[data-kami-kind="persona"] {
  border-color: var(--kami-kind-persona);
  color: var(--kami-kind-persona);
}
html[data-kami-skin="senren"] .kami-root .kami-chip[data-kami-kind="plot"],
html[data-kami-skin="senren"] .kami-root .kami-badge[data-kami-kind="plot"] {
  border-color: var(--kami-kind-plot);
  color: var(--kami-kind-plot);
}
html[data-kami-skin="senren"] .kami-root .kami-chip[data-kami-kind="info"],
html[data-kami-skin="senren"] .kami-root .kami-badge[data-kami-kind="info"] {
  border-color: var(--kami-kind-info);
  color: var(--kami-kind-info);
}
html[data-kami-skin="senren"] .kami-root .kami-chip[data-kami-kind="fun"],
html[data-kami-skin="senren"] .kami-root .kami-badge[data-kami-kind="fun"] {
  border-color: var(--kami-kind-fun);
  color: var(--kami-kind-fun);
}
html[data-kami-skin="senren"] .kami-root .kami-chip[data-kami-kind="nsfw"],
html[data-kami-skin="senren"] .kami-root .kami-badge[data-kami-kind="nsfw"] {
  border-color: var(--kami-kind-nsfw);
  color: var(--kami-kind-nsfw);
}
html[data-kami-skin="senren"] .kami-root .kami-chip[data-kami-kind="other"],
html[data-kami-skin="senren"] .kami-root .kami-badge[data-kami-kind="other"] {
  border-color: var(--kami-kind-other);
  color: var(--kami-kind-other);
}

/* ==========================================================================
 * 14 · 空态与内联气泡提示（Toast & Empty）
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  font-family: var(--kami-font-title);
  text-align: center;
}

/* 和风落樱花瓣空态装饰点 */
html[data-kami-skin="senren"] .kami-empty::before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50% 0 50% 50%;
  background-color: var(--kami-accent);
  opacity: 0.75;
  transform: rotate(-30deg);
}

html[data-kami-skin="senren"] .kami-toast {
  position: absolute;
  top: 10px;
  right: 14px;
  padding: 5px 12px;
  border-radius: var(--kami-r-sm);
  border: var(--kami-border-w) solid var(--kami-accent);
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-size: var(--kami-fs-xs);
  font-weight: var(--kami-fw-title);
  box-shadow: var(--kami-shadow);
  z-index: 10;
  animation: kami-senren-in var(--kami-dur) var(--kami-ease-out) backwards;
}

html[data-kami-skin="senren"] .kami-toast.is-bad {
  background-color: var(--kami-warn);
  border-color: var(--kami-warn);
}

/* ==========================================================================
 * 15 · 面板骨架与通用面板规则（不带面板 ID）
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) {
  background: rgba(44, 34, 37, 0.32);
}

html[data-kami-skin="senren"] .kami-drop {
  position: absolute;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background-color: var(--kami-bg);
  background-image: var(--kami-texture);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
}

html[data-kami-skin="senren"] .kami-drop > .kami-head { flex: 0 0 auto; }
html[data-kami-skin="senren"] .kami-drop > .kami-tabs { flex: 0 0 auto; }
html[data-kami-skin="senren"] .kami-drop > .kami-foot { flex: 0 0 auto; }
html[data-kami-skin="senren"] .kami-drop > .kami-body { flex: 1 1 auto; min-height: 0; }

/* 面板标签页行 */
html[data-kami-skin="senren"] .kami-tabs {
  display: flex;
  gap: 4px;
  padding: 0 var(--kami-pad-lg-x);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 24px), transparent 100%);
  mask-image: linear-gradient(90deg, #000 calc(100% - 24px), transparent 100%);
}

html[data-kami-skin="senren"] .kami-tabs::-webkit-scrollbar {
  display: none;
}

html[data-kami-skin="senren"] .kami-tab {
  flex: none;
  position: relative;
  border: var(--kami-border-w) solid transparent;
  border-bottom: 2px solid transparent;
  background-color: transparent;
  color: var(--kami-fg-dim);
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls-title);
  padding: 8px var(--kami-pad-x);
  cursor: pointer;
  transition: all var(--kami-dur-fast) var(--kami-ease);
}

@media (hover: hover) {
  html[data-kami-skin="senren"] .kami-tab:hover {
    color: var(--kami-accent);
  }
}

html[data-kami-skin="senren"] .kami-tab[aria-selected="true"] {
  color: var(--kami-accent);
  font-weight: var(--kami-fw-title);
  border-bottom-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
  border-radius: var(--kami-r-xs) var(--kami-r-xs) 0 0;
}

/* 进度点（Dots） */
html[data-kami-skin="senren"] .kami-dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 0;
}

html[data-kami-skin="senren"] .kami-dots span {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--kami-line-strong);
  transition: all var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="senren"] .kami-dots span.is-on {
  background-color: var(--kami-accent);
  box-shadow: 0 0 4px var(--kami-glow);
  transform: scale(1.25);
}

/* ==========================================================================
 * 16 · 面板网格与自适应列数（核心密集网格规则）
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap-lg);
  align-items: stretch;
}

/* 密集网格基准规则必须调小列宽为 100px */
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-grid:has(> .kami-item, > .kami-item-note) {
  --kami-items-min: 100px;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
}

/* 面板内卡片样式 */
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card {
  border: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-card);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card .kami-card:not(.is-on):not([aria-pressed="true"]) {
  background-color: var(--kami-card-2);
  border-color: var(--kami-line);
}

html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card.is-on,
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item.is-on,
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[aria-pressed="true"] {
  border-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
  box-shadow: 0 0 0 1px var(--kami-accent);
}

/* 面板内条目尺寸 */
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item {
  padding: 10px 12px;
  min-height: 42px;
}

/* 分组卡内部网格的边距控制 */
html[data-kami-skin="senren"] .kami-drop .kami-card:has(> .kami-card-body > .kami-grid) {
  padding-left: 12px;
  padding-right: 12px;
}

html[data-kami-skin="senren"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-head,
html[data-kami-skin="senren"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-title,
html[data-kami-skin="senren"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-note {
  padding-left: 0;
  padding-right: 0;
}

html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) button.kami-card-head.kami-btn {
  width: 100%;
  min-height: 0;
  border-radius: var(--kami-r-xs);
  justify-content: flex-start;
  padding: 6px 8px;
  background: transparent;
  border: none;
}

/* ==========================================================================
 * 17 · 锁死的条目（原生 disabled）：一眼看出点不动
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled],
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover,
html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  border-style: dashed;
  box-shadow: none;
  transform: none;
  opacity: var(--kami-dim-lock, 0.42);
  color: var(--kami-fg-mute);
  cursor: default;
  font-weight: var(--kami-fw);
}

html[data-kami-skin="senren"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled] .kami-item-main,
