}

/* —— 动效档位（皮肤自己响应） —— */
html[data-kami-skin="trpg"][data-kami-motion="calm"] .kami-root {
  --kami-dur-fast: .1s;
  --kami-dur: .16s;
  --kami-dur-slow: .24s;
  --kami-stagger: 0ms;
  --kami-enter-y: 3px;
}
html[data-kami-skin="trpg"][data-kami-motion="off"] .kami-root {
  --kami-dur-fast: 1ms;
  --kami-dur: 1ms;
  --kami-dur-slow: 1ms;
  --kami-enter-y: 0px;
  --kami-enter-scale: 1;
  --kami-stagger: 0ms;
}


/* ==========================================================================
 * 2 · 根与纸面（撕下来的草稿纸）
 * ======================================================================== */
html[data-kami-skin="trpg"] .kami-root {
  position: relative;
  box-sizing: border-box;
  margin: 12px 0 8px;
  text-align: left;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  line-height: var(--kami-lh);
  letter-spacing: var(--kami-ls);
  word-break: break-word;
  -webkit-tap-highlight-color: transparent;
}
html[data-kami-skin="trpg"] .kami-root *,
html[data-kami-skin="trpg"] .kami-root *::before,
html[data-kami-skin="trpg"] .kami-root *::after { box-sizing: border-box; }
html[data-kami-skin="trpg"] .kami-root button,
html[data-kami-skin="trpg"] .kami-root input,
html[data-kami-skin="trpg"] .kami-root textarea { font: inherit; color: inherit; letter-spacing: inherit; }
html[data-kami-skin="trpg"] .kami-root :focus-visible {
  outline: 2px dashed var(--kami-accent);
  outline-offset: 2px;
  border-radius: var(--kami-r-xs);
}

/* 纸叠：外壳底下压着的第二张纸（厚度），撕边与外壳完全同形 */
html[data-kami-skin="trpg"] .kami-root::before {
  content: "";
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  background: var(--kami-trpg-sheet);
  clip-path: var(--kami-surface-clip);
  transform: translateY(var(--kami-trpg-board));
  pointer-events: none;
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"])::before { content: none; }

/* 纸面本体：底色 + 涂鸦 + 稿纸格 + 纸纹，四层一次性画完，之后不再重绘 */
html[data-kami-skin="trpg"] .kami-surface {
  position: relative;
  clip-path: var(--kami-surface-clip);
  background-color: var(--kami-bg);
  background-image: var(--kami-trpg-doodle), var(--kami-trpg-grid), var(--kami-texture);
  background-repeat: repeat, repeat, repeat;
  background-size: 460px 340px, var(--kami-trpg-grid-size) var(--kami-trpg-grid-size), auto;
  background-position: 10px 6px, 0 0, 0 0;
  background-blend-mode: var(--kami-trpg-blend), var(--kami-trpg-blend), normal;
}
/* 注意：.kami-shell 与 .kami-surface 是同一个元素。
   这里绝不能写 background 简写 —— 它会连 background-image / -color 一起重置，
   把上面那四层纸面全部抹掉（皮肤里最容易踩的一脚）。 */
html[data-kami-skin="trpg"] .kami-shell {
  max-width: var(--kami-maxw);
  border: 0;
  border-radius: 0;
  box-shadow: none;
}


/* ==========================================================================
 * 3 · 头部：状态点 / d20 / 三折帷幕标题 / 右侧动作区
 * ======================================================================== */
html[data-kami-skin="trpg"] .kami-head {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  min-height: calc(var(--kami-row-h) + var(--kami-pad-y));
  overflow: visible;
}
html[data-kami-skin="trpg"] .kami-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--kami-accent);
  box-shadow: 0 0 0 2px var(--kami-accent-soft);
}
html[data-kami-skin="trpg"] .kami-dot[data-kami-on="1"] { background: var(--kami-kind-fun); }
/* 骰子在场时它就是状态标记，那个小圆点让位 */
html[data-kami-skin="trpg"] .kami-head:has(> .kami-deco[data-kami-deco="d20"]) > .kami-dot { display: none; }

/* —— d20 装饰槽：容器负责透视与合成层，面片精灵在容器里转 —— */
html[data-kami-skin="trpg"] .kami-deco[data-kami-deco="d20"] {
  display: inline-block;
  position: relative;
  flex: none;
  width: calc(var(--kami-fs) * 2.4 * var(--kami-trpg-die));
  height: calc(var(--kami-fs) * 2.4 * var(--kami-trpg-die));
  margin: 0 1px 0 0;
  pointer-events: none;
  perspective: calc(var(--kami-fs) * 14);
  transform-style: preserve-3d;
  will-change: transform;
  background-image: radial-gradient(ellipse 58% 11% at 50% 93%, var(--kami-trpg-sheet), rgba(0, 0, 0, 0) 72%);
  background-repeat: no-repeat;
}
/* 面片：六边形轮廓 + 六瓣明暗 + 三道折线，全部是渐变，没有位图 */
html[data-kami-skin="trpg"] .kami-deco[data-kami-deco="d20"]::before {
  content: "";
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  clip-path: polygon(50% 1.5%, 91.5% 26%, 91.5% 74%, 50% 98.5%, 8.5% 74%, 8.5% 26%);
  background-image:
    linear-gradient(146deg, rgba(255, 255, 255, .42) 0, rgba(255, 255, 255, 0) 44%, rgba(0, 0, 0, .22) 100%),
    conic-gradient(from 0deg at 50% 50%,
      var(--kami-trpg-die-edge) 0deg .9deg,
      var(--kami-trpg-die-f6) .9deg 60deg,
      var(--kami-trpg-die-f1) 60deg 119.1deg,
      var(--kami-trpg-die-edge) 119.1deg 120.9deg,
      var(--kami-trpg-die-f2) 120.9deg 180deg,
      var(--kami-trpg-die-f3) 180deg 239.1deg,
      var(--kami-trpg-die-edge) 239.1deg 240.9deg,
      var(--kami-trpg-die-f4) 240.9deg 300deg,
      var(--kami-trpg-die-f5) 300deg 359.1deg,
      var(--kami-trpg-die-edge) 359.1deg 360deg);
  transform: translateZ(2px) rotateX(-14deg) rotateY(-26deg) rotateZ(-4deg);
}
/* 中心面：正对镜头的那一面，比周围亮一档 */
html[data-kami-skin="trpg"] .kami-deco[data-kami-deco="d20"]::after {
  content: "";
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  clip-path: polygon(50% 22%, 74.2% 64%, 25.8% 64%);
  background-image: linear-gradient(158deg, var(--kami-trpg-die-face-hi) 0, var(--kami-trpg-die-face-lo) 100%);
  transform: translateZ(2px) rotateX(-14deg) rotateY(-26deg) rotateZ(-4deg);
}
@keyframes kami-trpg-d20 {
  0%   { transform: translateZ(2px) rotateX(-14deg) rotateY(-26deg) rotateZ(-4deg); }
  25%  { transform: translateZ(2px) rotateX(-5deg) rotateY(12deg) rotateZ(3deg); }
  50%  { transform: translateZ(2px) rotateX(-21deg) rotateY(29deg) rotateZ(6deg); }
  75%  { transform: translateZ(2px) rotateX(-9deg) rotateY(-7deg) rotateZ(-2deg); }
  100% { transform: translateZ(2px) rotateX(-14deg) rotateY(-26deg) rotateZ(-4deg); }
}
/* 同屏多颗骰子必须错开相位，否则像一排同步闪的灯 */
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root:is([data-kami-comp="think"],[data-kami-comp="search"]) .kami-deco[data-kami-deco="d20"]::before,
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root:is([data-kami-comp="think"],[data-kami-comp="search"]) .kami-deco[data-kami-deco="d20"]::after {
  animation: kami-trpg-d20 var(--kami-trpg-die-dur) ease-in-out infinite;
  animation-delay: -.4s;
}
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root[data-kami-comp="options"] .kami-deco[data-kami-deco="d20"]::before,
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root[data-kami-comp="options"] .kami-deco[data-kami-deco="d20"]::after {
  animation: kami-trpg-d20 var(--kami-trpg-die-dur) ease-in-out infinite;
  animation-delay: -6.3s;
}
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-deco[data-kami-deco="d20"]::before,
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-deco[data-kami-deco="d20"]::after {
  animation: kami-trpg-d20 var(--kami-trpg-die-dur) ease-in-out infinite;
  animation-delay: -11.6s;
}
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root[data-kami-comp="preview"] .kami-deco[data-kami-deco="d20"]::before,
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root[data-kami-comp="preview"] .kami-deco[data-kami-deco="d20"]::after {
  animation: kami-trpg-d20 var(--kami-trpg-die-dur) ease-in-out infinite;
  animation-delay: -3.1s;
}
/* 面板里的骰子更大 */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-deco[data-kami-deco="d20"] {
  width: calc(var(--kami-fs) * 3.4 * var(--kami-trpg-die));
  height: calc(var(--kami-fs) * 3.4 * var(--kami-trpg-die));
}

/* —— 真 3D d20：槽位被装饰模块升级成 .kami-d20 之后，上面那两颗占位精灵整体让位 ——
   二十面体的 20 个面片由 JS 摆位（几何全在 src/decor/d20.js），皮肤只负责配色：
   外层 .kami-d20-face 是棱边色，内层 i 是面片底色（两个三角形都由模块算进 --kami-d20-clip-i）。 */
html[data-kami-skin="trpg"] .kami-deco.kami-d20 {
  pointer-events: auto;
  cursor: pointer;
  perspective: none;
  transform-style: flat;
  will-change: auto;
}
html[data-kami-skin="trpg"] .kami-deco.kami-d20::before,
html[data-kami-skin="trpg"] .kami-deco.kami-d20::after { content: none; animation: none !important; }
html[data-kami-skin="trpg"] .kami-deco.kami-d20 { --kami-d20-dur: .95s; }
html[data-kami-skin="trpg"] .kami-d20-face { background-color: var(--kami-trpg-die-edge); }
html[data-kami-skin="trpg"] .kami-d20-face > i {
  clip-path: var(--kami-d20-clip-i);
  background-image: linear-gradient(158deg, var(--kami-trpg-die-face-hi) 0, var(--kami-trpg-die-face-lo) 100%);
  color: var(--kami-trpg-die-ink);
  font-family: var(--kami-font-mono);
  font-size: calc(var(--kami-d20-s, 32px) * .34);
  font-weight: 700;
  letter-spacing: -.03em;
  text-shadow: 0 1px 0 var(--kami-trpg-die-num);
}
/* 手涂感：相邻面片轮换色调，和占位精灵的六瓣用的是同一套颜色 */
html[data-kami-skin="trpg"] .kami-d20-face:nth-child(6n+1) > i { background-image: linear-gradient(158deg, var(--kami-trpg-die-f6), var(--kami-trpg-die-f3)); }
html[data-kami-skin="trpg"] .kami-d20-face:nth-child(6n+2) > i { background-image: linear-gradient(158deg, var(--kami-trpg-die-f5), var(--kami-trpg-die-f2)); }
html[data-kami-skin="trpg"] .kami-d20-face:nth-child(6n+3) > i { background-image: linear-gradient(158deg, var(--kami-trpg-die-f1), var(--kami-trpg-die-f4)); }
html[data-kami-skin="trpg"] .kami-d20-face:nth-child(6n+4) > i { background-image: linear-gradient(158deg, var(--kami-trpg-die-f2), var(--kami-trpg-die-f5)); }
html[data-kami-skin="trpg"] .kami-d20-face:nth-child(6n+5) > i { background-image: linear-gradient(158deg, var(--kami-trpg-die-f3), var(--kami-trpg-die-f6)); }
html[data-kami-skin="trpg"] .kami-d20-face:nth-child(6n+6) > i { background-image: linear-gradient(158deg, var(--kami-trpg-die-f4), var(--kami-trpg-die-f1)); }
/* 悬停 / 焦点 / 滚动中 */
html[data-kami-skin="trpg"] .kami-deco.kami-d20:hover .kami-d20-face > i { filter: brightness(1.07); }
html[data-kami-skin="trpg"] .kami-deco.kami-d20:focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
  border-radius: var(--kami-r-sm);
}
html[data-kami-skin="trpg"] .kami-deco.kami-d20[data-kami-d20-rolling="1"] .kami-d20-face > i { filter: brightness(.95); }
/* 桌面上的轻微晃动：只在「骰子转动」特效开着时跑，动效档位交给下面第 8 节统一掐掉 */
@keyframes kami-trpg-d20-idle {
  0%   { transform: rotate(-2.4deg) translateY(0); }
  50%  { transform: rotate(2.4deg) translateY(-5%); }
  100% { transform: rotate(-2.4deg) translateY(0); }
}
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-deco.kami-d20 .kami-d20-stage {
  animation: kami-trpg-d20-idle var(--kami-trpg-die-dur) ease-in-out infinite;
}
/* 同屏多颗骰子错开相位，否则像一排同步闪的灯 */
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root:is([data-kami-comp="think"],[data-kami-comp="search"]) .kami-deco.kami-d20 .kami-d20-stage { animation-delay: -.4s; }
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root[data-kami-comp="options"] .kami-deco.kami-d20 .kami-d20-stage { animation-delay: -6.3s; }
html[data-kami-skin="trpg"][data-kami-effects~="dice"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-deco.kami-d20 .kami-d20-stage { animation-delay: -11.6s; }

/* —— 标题：默认（行动选项 / 面板）是一张写了字的硬纸条 —— */
html[data-kami-skin="trpg"] .kami-title {
  min-width: 0;
  flex: 0 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  letter-spacing: var(--kami-ls-title);
  text-transform: var(--kami-title-transform);
  white-space: nowrap;
}

/* —— 显式思维链的标题：曾经是"三折硬纸板帷幕"（折页 + perspective 翻面）。
   用户看过之后认为效果不佳，2026 本轮整套撤掉：这里不写任何规则，标题就用上面那条
   通用 .kami-title —— 点 + 标题（左）+ 字数与箭头（右），字体/字距/截断沿用本皮肤；
   "纸感"由标题背后的纸面（撕边、稿纸格、涂鸦）承担，不再做立体折板。
   相应的令牌（wing / fold / slope / persp / board-*）也一并删掉了。 */

html[data-kami-skin="trpg"] .kami-actions {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-left: auto;
  flex: none;
}
html[data-kami-skin="trpg"] .kami-sub {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
html[data-kami-skin="trpg"] .kami-chev {
  flex: none;
  width: 0;
  height: 0;
  margin: 0 3px 0 5px;
  font-size: 0;
  border-top: 5px solid rgba(0, 0, 0, 0);
  border-bottom: 5px solid rgba(0, 0, 0, 0);
  border-left: 6px solid var(--kami-fg-mute);
  transform: rotate(0deg);
  transition: transform var(--kami-dur) var(--kami-ease), border-left-color var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="trpg"] .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev {
  transform: rotate(90deg);
  border-left-color: var(--kami-accent);
}
html[data-kami-skin="trpg"] .kami-collapse-head { cursor: pointer; user-select: none; }


/* ==========================================================================
 * 4 · 正文：正文头部的操作行 / 双视图 / 按钮
 * ======================================================================== */
html[data-kami-skin="trpg"] .kami-body { padding: 0 var(--kami-pad-lg-x) var(--kami-pad-lg-y); }
html[data-kami-skin="trpg"] .kami-collapse { display: block; }
html[data-kami-skin="trpg"] .kami-collapse > .kami-body { display: none; }
html[data-kami-skin="trpg"] .kami-collapse[data-kami-open="1"] > .kami-body {
  display: block;
  animation: kami-trpg-drop var(--kami-dur-slow) var(--kami-ease-out) backwards;
}
@keyframes kami-trpg-drop {
  0% { opacity: 0; transform: translateY(calc(var(--kami-enter-y) * -1)); }
  100% { opacity: 1; transform: translateY(0); }
}

/* 组件内的横向操作行：一条手画的下划线把它和正文分开 */
html[data-kami-skin="trpg"] .kami-bar {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  flex-wrap: nowrap;
  margin-bottom: var(--kami-gap-lg);
  padding-bottom: 7px;
  border-bottom: 1px dashed var(--kami-line-strong);
}
html[data-kami-skin="trpg"] .kami-bar > :last-child { margin-left: auto; }

/* 分段切换：两枚小纸片，选中的那枚被墨水描过 */
html[data-kami-skin="trpg"] .kami-seg {
  display: inline-flex;
  flex: none;
  gap: 3px;
  padding: 2px;
  border: 1px dashed var(--kami-line-strong);
  border-radius: 3px;
  background: var(--kami-t1);
}
html[data-kami-skin="trpg"] .kami-seg-item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 2px;
  background: transparent;
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.5;
  padding: 4px 10px;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color var(--kami-dur-fast) var(--kami-ease), color var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="trpg"] .kami-seg-item.is-on {
  background: var(--kami-accent-soft);
  color: var(--kami-fg);
  box-shadow: inset 0 -2px 0 var(--kami-accent-line);
}

/* 按钮：一小块卡纸 */
html[data-kami-skin="trpg"] .kami-btn,
html[data-kami-skin="trpg"] .kami-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  flex: none;
  min-height: calc(var(--kami-row-h) - 4px);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: 1px solid var(--kami-line);
  border-radius: 3px;
  background-color: var(--kami-card);
  color: var(--kami-fg);
  font-size: var(--kami-fs-sm);
  cursor: pointer;
  box-shadow: 0 2px 0 var(--kami-line-strong);
  transition: background-color var(--kami-dur-fast) var(--kami-ease), border-color var(--kami-dur-fast) var(--kami-ease),
              color var(--kami-dur-fast) var(--kami-ease), transform var(--kami-dur-fast) var(--kami-ease),
              box-shadow var(--kami-dur-fast) var(--kami-ease);
}
/* 同 grokbot：底透明 + 硬投影都收掉之后，描边必须走控件那一档，否则面板里只剩一行字（2026-09-21） */
html[data-kami-skin="trpg"] .kami-btn--ghost { background-color: transparent; border-color: var(--kami-line-strong); box-shadow: none; }
html[data-kami-skin="trpg"] .kami-root .kami-btn--primary {
  /* 藤绿底 + 白字只有 3.9:1：把底往墨色里调一档（同一个绿，深一点），白字实测 4.8:1。
     这是「同一支笔写出来的深浅」，不是换颜色。 */
  background-color: color-mix(in srgb, var(--kami-accent) 84%, var(--kami-fg));
  border-color: color-mix(in srgb, var(--kami-accent) 84%, var(--kami-fg));
  color: var(--kami-accent-fg);
}
html[data-kami-skin="trpg"] .kami-btn.is-on {
  background-color: var(--kami-accent-soft);
  border-color: var(--kami-accent-line);
}
html[data-kami-skin="trpg"] .kami-icon-btn {
  min-width: calc(var(--kami-row-h) - 4px);
  padding: 0;
  font-size: var(--kami-icon);
