    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent-line);
  }
  html[data-kami-skin="trpg"] .kami-btn--primary:hover { background-color: var(--kami-accent); }
}

/* 正文纸块：一张干净的纸，左边一道红铅笔线 */
html[data-kami-skin="trpg"] .kami-md {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  padding-left: calc(var(--kami-pad-lg-x) + 12px);
  border-radius: 3px;
  border: 1px solid var(--kami-line);
  background-color: var(--kami-card-2);
  background-image: linear-gradient(90deg, rgba(0, 0, 0, 0) 0 calc(var(--kami-pad-lg-x) * .62), var(--kami-trpg-margin-line) calc(var(--kami-pad-lg-x) * .62) calc(var(--kami-pad-lg-x) * .62 + 1px), rgba(0, 0, 0, 0) calc(var(--kami-pad-lg-x) * .62 + 1px));
  box-shadow: 0 1px 0 var(--kami-t2);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
}
html[data-kami-skin="trpg"] .kami-md > :first-child { margin-top: 0; }
html[data-kami-skin="trpg"] .kami-md > :last-child { margin-bottom: 0; }
html[data-kami-skin="trpg"] .kami-md p { margin: .5em 0; }
html[data-kami-skin="trpg"] .kami-md h1,
html[data-kami-skin="trpg"] .kami-md h2,
html[data-kami-skin="trpg"] .kami-md h3 {
  margin: .9em 0 .4em;
  font-family: var(--kami-font-title);
  font-weight: 700;
  font-size: var(--kami-fs);
  letter-spacing: var(--kami-ls-title);
  color: var(--kami-fg);
}
html[data-kami-skin="trpg"] .kami-md code {
  font-family: var(--kami-font-mono);
  font-size: .88em;
  padding: 1px 5px;
  border-radius: 2px;
  background: var(--kami-t2);
}
html[data-kami-skin="trpg"] .kami-md pre {
  margin: .6em 0;
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border-radius: 3px;
  background: var(--kami-bg-soft);
  border: 1px dashed var(--kami-line-strong);
  overflow-x: auto;
}
html[data-kami-skin="trpg"] .kami-md pre code { background: none; padding: 0; }
html[data-kami-skin="trpg"] .kami-md blockquote {
  margin: .6em 0;
  padding: 2px 0 2px 11px;
  border-left: 2px solid var(--kami-accent-line);
  color: var(--kami-fg-mute);
}
html[data-kami-skin="trpg"] .kami-md ul,
html[data-kami-skin="trpg"] .kami-md ol { margin: .5em 0; padding-left: 1.3em; }
html[data-kami-skin="trpg"] .kami-md li { margin: .18em 0; }
html[data-kami-skin="trpg"] .kami-md strong { color: var(--kami-fg); font-weight: 700; }
html[data-kami-skin="trpg"] .kami-md a { color: var(--kami-accent); text-underline-offset: 2px; }
html[data-kami-skin="trpg"] .kami-md hr { border: 0; border-top: 1px dashed var(--kami-line-strong); margin: .8em 0; }
html[data-kami-skin="trpg"] .kami-md img { max-width: 100%; border-radius: 2px; }
html[data-kami-skin="trpg"] .kami-md table { border-collapse: collapse; width: 100%; font-size: var(--kami-fs-xs); }
html[data-kami-skin="trpg"] .kami-md th,
html[data-kami-skin="trpg"] .kami-md td { border: 1px solid var(--kami-line); padding: 4px 7px; }

/* 原文：方格本上的一页 */
html[data-kami-skin="trpg"] .kami-raw {
  margin: 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: 3px;
  border: 1px solid var(--kami-line);
  background-color: var(--kami-card-2);
  background-image: linear-gradient(rgba(58, 74, 62, .07) 1px, rgba(0, 0, 0, 0) 1px),
                    linear-gradient(90deg, rgba(58, 74, 62, .07) 1px, rgba(0, 0, 0, 0) 1px);
  background-size: 22px 22px, 22px 22px;
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  line-height: 1.75;
  color: var(--kami-fg-dim);
  white-space: pre-wrap;
  overflow-x: auto;
}
html[data-kami-skin="trpg"] .kami-empty { padding: var(--kami-pad-lg-y) 0; color: var(--kami-fg-mute); font-size: var(--kami-fs-sm); }
html[data-kami-skin="trpg"] .kami-toast {
  margin-top: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border-radius: 3px;
  border: 1px dashed var(--kami-line-strong);
  background-color: var(--kami-accent-soft);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-dim);
  animation: kami-trpg-drop var(--kami-dur) var(--kami-ease-out) backwards;
}
html[data-kami-skin="trpg"] .kami-toast.is-bad { color: var(--kami-warn); border-color: currentColor; background-color: transparent; }


/* ==========================================================================
 * 5 · 卡牌：桌游硬纸卡
 * ======================================================================== */
html[data-kami-skin="trpg"] .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  justify-content: var(--kami-justify);
  gap: var(--kami-gap);
}
/* 必须写在 .kami-list 之后：选项卡同时带 kami-grid 与 kami-list 两个类，
   靠文档顺序决定「一列」还是「多列」 */
html[data-kami-skin="trpg"] .kami-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap-lg);
}
html[data-kami-skin="trpg"] .kami-card {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--kami-line-strong);
  border-radius: 4px;
  background-color: var(--kami-card);
  background-image: linear-gradient(158deg, rgba(255, 255, 255, .5) 0, rgba(255, 255, 255, 0) 40%),
                    repeating-linear-gradient(104deg, rgba(255, 255, 255, .05) 0 1px, rgba(255, 255, 255, 0) 1px 4px);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  box-shadow: 0 var(--kami-trpg-board) 0 rgba(120, 102, 68, .34), 0 calc(var(--kami-trpg-board) + 5px) 10px -6px rgba(74, 60, 34, .5);
  transition: background-color var(--kami-dur) var(--kami-ease), border-color var(--kami-dur) var(--kami-ease),
              transform var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}
/* 卡牌磨损：右上角一块磨白 + 左下角一道压痕 */
html[data-kami-skin="trpg"][data-kami-effects~="wear"] .kami-card {
  background-image: linear-gradient(158deg, rgba(255, 255, 255, .5) 0, rgba(255, 255, 255, 0) 40%),
                    linear-gradient(225deg, rgba(255, 255, 255, .85) 0 5px, rgba(190, 172, 136, .45) 5px 6px, rgba(0, 0, 0, 0) 6px),
                    linear-gradient(45deg, rgba(120, 102, 68, .16) 0 7px, rgba(0, 0, 0, 0) 7px),
                    repeating-linear-gradient(104deg, rgba(255, 255, 255, .05) 0 1px, rgba(255, 255, 255, 0) 1px 4px);
}
html[data-kami-skin="trpg"] .kami-item {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 5px;
  width: 100%;
  text-align: left;
  cursor: pointer;
}
html[data-kami-skin="trpg"] .kami-item.is-demo { opacity: .6; cursor: default; }
html[data-kami-skin="trpg"] .kami-item-main { min-width: 0; }
html[data-kami-skin="trpg"] .kami-item-side {
  flex: none;
  margin-left: auto;
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  opacity: .7;
  transition: transform var(--kami-dur) var(--kami-ease), opacity var(--kami-dur) var(--kami-ease);
}
@media (hover: hover) {
  html[data-kami-skin="trpg"] .kami-item:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent-line);
    transform: translateY(-2px);
    box-shadow: 0 calc(var(--kami-trpg-board) + 2px) 0 rgba(120, 102, 68, .34), 0 calc(var(--kami-trpg-board) + 9px) 14px -8px rgba(74, 60, 34, .55);
  }
  html[data-kami-skin="trpg"] .kami-item:hover .kami-item-side { transform: translateX(2px); opacity: 1; }
  html[data-kami-skin="trpg"] .kami-item:hover .kami-badge { transform: rotate(0deg); }
}
html[data-kami-skin="trpg"] .kami-item:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 rgba(120, 102, 68, .34), 0 2px 3px -2px rgba(74, 60, 34, .5);
}
html[data-kami-skin="trpg"] .kami-item.is-done {
  border-color: var(--kami-accent-line);
  background-color: var(--kami-accent-soft);
}
html[data-kami-skin="trpg"] .kami-card-head {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-bottom: 7px;
}
html[data-kami-skin="trpg"] .kami-card-title {
  font-family: var(--kami-font-title);
  font-weight: 700;
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls-title);
  min-width: 0;
}
html[data-kami-skin="trpg"] .kami-card-note { font-size: var(--kami-fs-xs); color: var(--kami-fg-mute); }
html[data-kami-skin="trpg"] .kami-card-body { display: block; font-size: var(--kami-fs-sm); color: var(--kami-fg-dim); }

/* 角落的类型标签：一枚歪着盖上去的章 */
html[data-kami-skin="trpg"] .kami-badge,
html[data-kami-skin="trpg"] .kami-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  padding: 1px 7px 2px;
  border-radius: 2px;
  border: 1px solid currentColor;
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-xs);
  font-weight: 700;
  line-height: 1.5;
  letter-spacing: .06em;
  color: var(--kami-kind-other);
  white-space: nowrap;
}
html[data-kami-skin="trpg"] .kami-badge {
  transform: rotate(-1.4deg);
  background-color: currentColor;
  background-image: linear-gradient(rgba(255, 255, 255, .82), rgba(255, 255, 255, .82));
  background-clip: padding-box;
  transition: transform var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="trpg"] .kami-chip {
  border: 1px dashed var(--kami-line-strong);
  background-color: var(--kami-t1);
  color: var(--kami-fg-dim);
  font-weight: 400;
}
html[data-kami-skin="trpg"] .kami-root [data-kami-kind="action"] { color: var(--kami-kind-action); }
html[data-kami-skin="trpg"] .kami-root [data-kami-kind="persona"] { color: var(--kami-kind-persona); }
html[data-kami-skin="trpg"] .kami-root [data-kami-kind="plot"] { color: var(--kami-kind-plot); }
html[data-kami-skin="trpg"] .kami-root [data-kami-kind="info"] { color: var(--kami-kind-info); }
html[data-kami-skin="trpg"] .kami-root [data-kami-kind="fun"] { color: var(--kami-kind-fun); }
html[data-kami-skin="trpg"] .kami-root [data-kami-kind="nsfw"] { color: var(--kami-kind-nsfw); }
html[data-kami-skin="trpg"] .kami-root [data-kami-kind="other"] { color: var(--kami-kind-other); }
html[data-kami-skin="trpg"] .kami-foot {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-lg-x) var(--kami-pad-lg-y);
  border-top: 1px dashed var(--kami-line-strong);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
}


/* ==========================================================================
 * 6 · 面板：桌上摊开的那张最大的纸
 * ======================================================================== */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) {
  background: rgba(38, 32, 20, .28);
}
/* .kami-drop 也是 .kami-surface：面板几何层给的是 position:absolute，
   而上面 .kami-surface 的 position:relative 特异性更高会把它顶掉 ——
   窄屏抽屉靠 bottom:0 定位，一旦退回 relative 就会跑到屏幕顶端。这里显式压回来。 */
html[data-kami-skin="trpg"] .kami-drop {
  position: absolute;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  clip-path: var(--kami-surface-clip);
  background-color: var(--kami-bg);
  background-image: var(--kami-trpg-doodle), var(--kami-trpg-grid), var(--kami-texture);
  background-repeat: repeat, repeat, repeat;
  background-size: 460px 340px, var(--kami-trpg-grid-size) var(--kami-trpg-grid-size), auto;
  background-position: 6px 4px, 0 0, 0 0;
  background-blend-mode: var(--kami-trpg-blend), var(--kami-trpg-blend), normal;
}
html[data-kami-skin="trpg"] .kami-drop > .kami-head { flex: 0 0 auto; }
html[data-kami-skin="trpg"] .kami-drop > .kami-tabs { flex: 0 0 auto; }
html[data-kami-skin="trpg"] .kami-drop > .kami-foot { flex: 0 0 auto; }
html[data-kami-skin="trpg"] .kami-drop > .kami-body { flex: 1 1 auto; min-height: 0; }

html[data-kami-skin="trpg"] .kami-tabs {
  display: flex;
  gap: 4px;
  padding: 0 var(--kami-pad-lg-x);
  border-bottom: 1px dashed var(--kami-line-strong);
  overflow-x: auto;
  scrollbar-width: none;
}
html[data-kami-skin="trpg"] .kami-tabs::-webkit-scrollbar { display: none; }
/* tab 行放不下时（7 个 tab / 430px 面板、或手机抽屉）要**看得出来还能往右滑**：
   给滚动容器右缘一道 20px 的渐隐遮罩。遮罩挂在滚动容器自己的边框盒上，内容在它下面滚，
   被裁掉的那半个 tab 会淡出成「还有」的暗示；tab 行排得下时渐隐落在右侧内边距与底线上。 */
html[data-kami-skin="trpg"] .kami-tabs {
  -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
  mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
}
html[data-kami-skin="trpg"] .kami-tab {
  flex: none;
  position: relative;
  top: 1px;
  border: 1px solid var(--kami-line);
  border-bottom: 0;
  border-radius: 3px 3px 0 0;
  background-color: var(--kami-t1);
  color: var(--kami-fg-mute);
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls-title);
  padding: 7px var(--kami-pad-x) 6px;
  cursor: pointer;
  transition: color var(--kami-dur-fast) var(--kami-ease), background-color var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="trpg"] .kami-tab[aria-selected="true"] {
  color: var(--kami-fg);
  background-color: var(--kami-bg);
  border-color: var(--kami-line-strong);
  box-shadow: inset 0 2px 0 var(--kami-accent);
}

html[data-kami-skin="trpg"] .kami-field {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) 0;
  border-bottom: 1px dotted var(--kami-line);
}
html[data-kami-skin="trpg"] .kami-field-label { flex: 1 1 auto; min-width: 0; font-size: var(--kami-fs-sm); }
html[data-kami-skin="trpg"] .kami-field-value { flex: none; display: flex; align-items: center; gap: 6px; }
html[data-kami-skin="trpg"] .kami-range {
  -webkit-appearance: none;
  appearance: none;
  width: 96px;
  height: 6px;
  border-radius: 1px;
  border: 1px solid var(--kami-line);
  background-color: var(--kami-t2);
  background-image: repeating-linear-gradient(90deg, var(--kami-line) 0 1px, rgba(0, 0, 0, 0) 1px 8px);
  cursor: pointer;
}
html[data-kami-skin="trpg"] .kami-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 13px;
  height: 16px;
  border-radius: 2px;
  background-color: var(--kami-accent);
  border: 1px solid var(--kami-accent-fg);
  box-shadow: 0 2px 0 rgba(0, 0, 0, .22);
}
html[data-kami-skin="trpg"] .kami-range::-moz-range-thumb {
  width: 12px;
  height: 15px;
  border-radius: 2px;
  border: 1px solid var(--kami-accent-fg);
  background-color: var(--kami-accent);
}
html[data-kami-skin="trpg"] .kami-number {
  width: 62px;
  min-height: 28px;
  padding: 2px 6px;
  border: 1px solid var(--kami-line);
  border-radius: 2px;
  background-color: var(--kami-card-2);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg);
}
/* 右对齐是数字框的专属：以前这条写在裸 .kami-number 上，把摘要提示词的正文与角色下拉一起带偏了 */
html[data-kami-skin="trpg"] input.kami-number[type="number"] { text-align: right; }

/* 面板里的数字输入框：字用正文色（--kami-fg）+ 亮底，并给凹槽加一圈内阴影
   （卡片底与输入底只差 0.14 亮度时还看得见，但暗色卡片上光靠底色分不出来）。
   必须点名 input.kami-number：.kami-root input 的 color:inherit 特异性更高，
   会把上面的 color:var(--kami-fg) 压成继承来的 --kami-fg-dim。两块面板共用，panel 限定即可。
   底必须显式写、并且带 !important：酒馆「用户设置 → 自定义 CSS」里那条
    input[type="number"] { background-color: var(--ui-color-sec) !important } 会盖掉
    .kami-number 上的亮底，深色主题下就变成深底压深字（真机实测，见本轮报告）。
    底只能写 background-color：写成 background 简写会把 .kami-select 那枚自绘箭头
    的 background-image 一起重置掉。 */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) input.kami-number,
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) input.kami-text,
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) textarea.kami-textarea,
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
  color: var(--kami-fg) !important;
  background-color: var(--kami-card-2) !important;
  border-color: var(--kami-line-strong) !important;
  color-scheme: light !important;
  box-shadow: inset 0 1px 2px var(--kami-t3);
}

/* 文本 / 多行 / 下拉（契约 §4.2 新登记的三类）：直角小圆角 + 一管墨线的卡纸控件，一律左对齐。
   选择器点名到元素：.kami-root textarea 的 color:inherit 与它同为 (0,2,2)，
   只有源码顺序在后才压得住，否则字会被 .kami-field 的 --kami-fg-dim 接管。 */
html[data-kami-skin="trpg"] input.kami-text,
html[data-kami-skin="trpg"] textarea.kami-textarea,
html[data-kami-skin="trpg"] .kami-select {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-card-2);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}
html[data-kami-skin="trpg"] textarea.kami-textarea { resize: vertical; }
/* 下拉框：抹掉浏览器默认外观，用两层渐变拼一枚 V 形箭头；右内边距给箭头留位 */
html[data-kami-skin="trpg"] .kami-select {
  -webkit-appearance: none;
  appearance: none;
  padding-right: calc(var(--kami-pad-x) + 16px);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg-mute) 50%),
    linear-gradient(135deg, var(--kami-fg-mute) 50%, transparent 50%);
  background-size: 4px 4px, 4px 4px;
  background-position: calc(100% - 13px) calc(50% + 1px), calc(100% - 9px) calc(50% + 1px);
  background-repeat: no-repeat;
  cursor: pointer;
}
html[data-kami-skin="trpg"] .kami-switch { display: inline-flex; align-items: center; cursor: pointer; }
html[data-kami-skin="trpg"] .kami-switch-input { position: absolute; opacity: 0; width: 0; height: 0; }
html[data-kami-skin="trpg"] .kami-switch {
  position: relative;
  width: 40px;
  height: 20px;
  border-radius: 2px;
  border: 1px solid var(--kami-line-strong);
  background-color: var(--kami-t2);
  transition: background-color var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="trpg"] .kami-switch-thumb {
  position: absolute;
  top: 1px;
  left: 1px;
  width: 16px;
  height: 16px;
  border-radius: 2px;
  background-color: var(--kami-fg-mute);
  box-shadow: 0 1px 0 rgba(0, 0, 0, .2);
  transition: transform var(--kami-dur) var(--kami-ease), background-color var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="trpg"] .kami-switch[data-state="checked"] { background-color: var(--kami-accent-soft); border-color: var(--kami-accent-line); }
html[data-kami-skin="trpg"] .kami-switch[data-state="checked"] .kami-switch-thumb { transform: translateX(20px); background-color: var(--kami-accent); }
html[data-kami-skin="trpg"] .kami-switch:focus-visible { outline: 2px dashed var(--kami-accent); outline-offset: 2px; }

html[data-kami-skin="trpg"] .kami-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-t3) transparent;
}
html[data-kami-skin="trpg"] .kami-scroll::-webkit-scrollbar { width: 9px; height: 9px; }
html[data-kami-skin="trpg"] .kami-scroll::-webkit-scrollbar-thumb {
  background-color: var(--kami-t3);
  border-radius: 0;
  border: 3px solid transparent;
  background-clip: content-box;
}
html[data-kami-skin="trpg"] .kami-resize {
  position: absolute;
  right: 3px;
  bottom: 3px;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
  background-image: linear-gradient(135deg, rgba(0, 0, 0, 0) 46%, var(--kami-line-strong) 46%, var(--kami-line-strong) 56%, rgba(0, 0, 0, 0) 56%);
}
html[data-kami-skin="trpg"] .kami-preview {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  border: 1px solid var(--kami-line);
  border-radius: 3px;
  background-color: var(--kami-card);
}
html[data-kami-skin="trpg"] .kami-preview i {
  display: block;
  height: 6px;
  border-radius: 1px;
  background-color: var(--kami-t3);
}
html[data-kami-skin="trpg"] .kami-preview i:first-child { width: 58%; background-color: var(--kami-accent); }
html[data-kami-skin="trpg"] .kami-pv {
  position: relative;
  border: 1px solid var(--kami-line);
  border-radius: 3px;
  background-color: var(--kami-bg);
  overflow: hidden;
}
html[data-kami-skin="trpg"] .kami-pv-frame { display: block; width: 100%; border: 0; }

/* 贴底抽屉：模式由脚本按**酒馆自己的单栏状态**下发（data-kami-layout="sheet"），
   所以这里写属性选择器而不是媒体查询 —— 面板什么时候变成抽屉，跟酒馆什么时候只剩中间栏一致。 */
html[data-kami-skin="trpg"] .kami-drop[data-kami-layout="sheet"] { border-radius: 0; }


/* ==========================================================================
 * 7 · 特效（每个 id 都能被面板单独关掉）
 * ======================================================================== */
html[data-kami-skin="trpg"][data-kami-effects~="grid"] .kami-root {
  --kami-trpg-grid: radial-gradient(circle at 50% 50%, var(--kami-trpg-grid-ink) 0 1.1px, rgba(0, 0, 0, 0) 1.6px);
}
html[data-kami-skin="trpg"][data-kami-effects~="doodle"] .kami-root {
  --kami-trpg-doodle: var(--kami-trpg-art);
}
/* 胶带：两条半透明胶纸压住两个对角，在纸面之上、文字之外 */
html[data-kami-skin="trpg"][data-kami-effects~="tape"] .kami-surface::after {
  content: "";
  position: absolute;
  z-index: 4;
  top: 5px;
  left: -7px;
  width: 42px;
  height: 14px;
  pointer-events: none;
  border-radius: 1px;
  background-image: linear-gradient(90deg, rgba(255, 255, 255, 0) 0 5%, var(--kami-trpg-tape) 9%, var(--kami-trpg-tape) 91%, rgba(255, 255, 255, 0) 95%),
                    linear-gradient(180deg, rgba(255, 255, 255, .35) 0, rgba(255, 255, 255, 0) 100%);
  box-shadow: 0 1px 2px rgba(90, 80, 60, .16);
  transform: rotate(-38deg);
}
html[data-kami-skin="trpg"][data-kami-effects~="tape"] .kami-surface::before {
  content: "";
  position: absolute;
  z-index: 4;
  right: -7px;
  bottom: 6px;
  width: 42px;
  height: 14px;
  pointer-events: none;
  border-radius: 1px;
  background-image: linear-gradient(90deg, rgba(255, 255, 255, 0) 0 5%, var(--kami-trpg-tape) 9%, var(--kami-trpg-tape) 91%, rgba(255, 255, 255, 0) 95%),
                    linear-gradient(180deg, rgba(255, 255, 255, .35) 0, rgba(255, 255, 255, 0) 100%);
  box-shadow: 0 1px 2px rgba(90, 80, 60, .16);
  transform: rotate(-38deg);
}


/* ==========================================================================
 * 8 · 动效降级：不是减速，是停住
 * ======================================================================== */
@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="trpg"] .kami-root *,
  html[data-kami-skin="trpg"] .kami-root *::before,
  html[data-kami-skin="trpg"] .kami-root *::after {
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 1ms !important;
  }
  html[data-kami-skin="trpg"] .kami-deco[data-kami-deco="d20"]::before,
  html[data-kami-skin="trpg"] .kami-deco[data-kami-deco="d20"]::after,
  html[data-kami-skin="trpg"] .kami-deco.kami-d20 .kami-d20-stage { animation: none !important; }
}
html[data-kami-skin="trpg"][data-kami-motion="calm"] .kami-root *,
html[data-kami-skin="trpg"][data-kami-motion="calm"] .kami-root *::before,
html[data-kami-skin="trpg"][data-kami-motion="calm"] .kami-root *::after {
  animation-iteration-count: 1 !important;
}
html[data-kami-skin="trpg"][data-kami-motion="calm"] .kami-deco[data-kami-deco="d20"]::before,
html[data-kami-skin="trpg"][data-kami-motion="calm"] .kami-deco[data-kami-deco="d20"]::after,
html[data-kami-skin="trpg"][data-kami-motion="calm"] .kami-deco.kami-d20 .kami-d20-stage { animation: none !important; }
html[data-kami-skin="trpg"][data-kami-motion="off"] .kami-root *,
html[data-kami-skin="trpg"][data-kami-motion="off"] .kami-root *::before,
html[data-kami-skin="trpg"][data-kami-motion="off"] .kami-root *::after {
  animation-duration: 1ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 1ms !important;
}
html[data-kami-skin="trpg"][data-kami-motion="off"] .kami-deco[data-kami-deco="d20"]::before,
html[data-kami-skin="trpg"][data-kami-motion="off"] .kami-deco[data-kami-deco="d20"]::after,
html[data-kami-skin="trpg"][data-kami-motion="off"] .kami-deco.kami-d20 .kami-d20-stage { animation: none !important; }

/* ==========================================================================
 * 9 · 设置面板里的条目：紧凑网格（手机抽屉 3 列）+ 开着的卡片高亮
 * ------------------------------------------------------------------------
 * ① 皮肤默认的 --kami-items-min（15.5rem ≈ 248px，按 820px 宽的消息区调的）
 *    在设置面板里永远只排得下 1 列 —— 面板里的网格只有 353px 宽。
 *    面板作用域内压到 96px：390px 宽的底部抽屉正好 3 列，桌面 420px 面板 3~4 列。
 * ② 开着（is-on）以前只有右侧那枚「开/关」标签能看出来。这里按本皮肤
 *    「这张牌已经摊在桌上」的语汇点亮它：边框转强调色、纸面染一层淡绿，
 *    与 .kami-item.is-done 同一套令牌，没有新颜色。
 *
 * 三重限定，缺一不可：
 *   · html[data-kami-skin="trpg"] —— 皮肤契约要求的皮肤前缀；
 *   · :is([data-kami-comp="panel"],[data-kami-comp="dialog"])    —— 消息 iframe 里只有 think / options 两种组件，
 *                                   没有 panel。带上它，面板的改动绝不会渗进聊天前端；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 * ======================================================================== */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"])#kami-preset-panel {
  --kami-items-min: 96px;
}

/* 窄屏（手机底部抽屉）下的列宽：96px 会让 375px 的抽屉排出 3 列、卡只有 ~110px，
   「DS/GLM底部破限」这种名字被拦腰断成 DS/GLM 断行。窄屏把列宽调大，宁可两列：
   375px 抽屉 → 2 列（卡 ~166px），320px → 2 列（卡 ~110px）。
   只改令牌，不动脚本结构；桌面 420px 面板不受影响（视口 > 560px 时照旧 3~4 列）。 */
@media (max-width: 560px) {
  html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"])#kami-preset-panel {
    --kami-items-min: 152px;
  }
}
@media (max-width: 380px) {
  html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"])#kami-preset-panel {
    --kami-items-min: 108px;
  }
}

html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card.is-on {
  border-color: var(--kami-accent-line);
  background-color: var(--kami-accent-soft);
}

/* ============================================================
 * 22 · 条目名角标：emoji 摘下来，像桌沿上贴的一枚小签
 * ------------------------------------------------------------
 * 条目名绝大多数是四个汉字，前面那枚 emoji + 空格会把 110px 的紧凑小卡顶成两行。
 * 把 emoji 绝对定位到卡片角上，文字那一行**整行**腾出来，卡片高度不因此变高。
 * 脚本只摘显示，预设里条目名一个字没动。
 *
 * 三重限定，缺一不可（理由同上节）：
 *   · html[data-kami-skin="trpg"] —— 皮肤前缀；
 *   · :is([data-kami-comp="panel"],[data-kami-comp="dialog"])    —— 消息 iframe 里只有 think / options，没有 panel；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 * 只用本皮肤已有令牌；把这一枚上「整块铺色」的跑纸底纹收掉，角上只留 emoji 本身。
 * ============================================================ */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item.kami-card {
  position: relative;
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge {
  position: absolute;
  top: 1px;
  right: 4px;
  left: auto;
  z-index: 2;
  padding: 0;
  border: 0;
  border-radius: 0;
  background-color: transparent;
  background-image: none;
  font-size: var(--kami-fs-xs);
  line-height: 1.2;
  letter-spacing: 0;
  color: var(--kami-fg-dim);
  transform: rotate(-1.4deg);
  pointer-events: none;
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="tl"],
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 4px;
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="br"],
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 1px;
}
/* 角标**不占宽度**：文字始终拿整张卡的宽度；只在上下方向让出角标的高度。
   有上角标（tl/tr）就加上边距，有下角标（bl/br）就加下边距 —— 卡片略高一点点，
   文字那一行永远是整宽的（用户裁定：角标可以占高度，不能占宽度）。 */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
  padding-top: calc(var(--kami-pad-lg-y) + 0.4em);
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-lg-y) + 0.4em);
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:hover > .kami-badge {
  transform: rotate(0deg);
}

/* ============================================================
 * 24 · 非当前模型的模型专属条目：锁死
 * ------------------------------------------------------------
 * 面板「🤖 模型」tab 里，不属于「当前模型」的模型专属条目一律禁用（脚本写 HTML 原生的
 * disabled，条目卡本来就是 button）。外观也要给出「锁死」的样子：变暗 + 去掉悬停反馈
 * + 鼠标禁止符号。颜色只用本文件已有的「最弱文字色」令牌 --kami-fg-mute，不引入新颜色。
 *
 * 三重限定，缺一不可（理由同上面 22 节）：
 *   · html[data-kami-skin="trpg"] —— trpg 的作用域前缀；
 *   · :is([data-kami-comp="panel"],[data-kami-comp="dialog"])    —— 消息 iframe 里只有 think / options，没有 panel；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 * ============================================================ */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled],
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover,
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: .42;
  color: var(--kami-fg-mute);
  cursor: not-allowed;
}
/* 悬停才会冒出来的装饰（角标转正 / 左缘竖条 / 湿痕横线）在锁死时一律不许动 */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover::before,
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover::after {
  transform: scale(0);
  opacity: 0;
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover > .kami-badge { transform: none; }

/* 注释标记 + 展开出来的注释正文：**不得用面板 id 限定**（契约 §4.4 硬规则），
   否则后加的面板（如引导 ）一条都匹配不上。
   标记元素 = span.kami-card-note[data-kami-note-mark]，与 🌟 预设面板同构。 */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note-mark] {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.4em;
  height: 1.4em;
  margin-left: 5px;
  border: var(--kami-border-w) solid var(--kami-accent);
  border-radius: var(--kami-r-pill);
  background: var(--kami-accent-soft);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note-mark]:hover,
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note-mark]:focus-visible {
  background: var(--kami-accent);
  color: var(--kami-bg);
  border-color: var(--kami-accent);
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note] {
  display: block;
  margin: 5px 0 0;
  padding: 5px 7px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background: var(--kami-t2);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  text-align: left;
}
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note][hidden] { display: none; }

/* ============================================================
 * · 面板里的控件边界：描边抬到「看得见」那一档
 * ------------------------------------------------------------
 * 面板里的条目卡底与外面那层卡片底是同一个色，唯一的边界就是那 1px 描边；
 * 原来的 --kami-line 实测只有 1.3~1.6:1，卡片会连成一片、看不出是一张一张的按钮。
 * 面板内的控件描边统一提到 --kami-line-strong（同一个色，只是更实），卡片边界实测 >= 3:1。
 * 只用本皮肤已有令牌，没有新颜色；不开 --kami-line 本身：聊天前端的细线该细还是细。
 * 不带面板 id（契约 §4.4）：三块面板与以后的新面板共用这一条。
 * ============================================================ */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:not(.is-on):not([aria-pressed="true"]),
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card:not(.kami-item),
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-btn:not(.is-on):not(.kami-btn--primary) {
  border-color: var(--kami-line-strong);
}

/* ============================================================
 * 注释标记 ⓘ 做成右上角角标 + 注释外包层的等高拉伸（2026-09-21 用户裁定）
 * ------------------------------------------------------------
 * 1) 条目卡里的 ⓘ 现在是**右上角角标**：构建器给它 data-kami-corner="tr"
 *    （契约 §4.4 已登记的角标机制，与 emoji 角标同一套定位）。它不再占名字那一行的
 *    宽度 —— 行内记号会把约 100px 宽的条目卡里的名字挤到换行，同一行卡片因此被撑高。
 *    卡片头里的 ⓘ（卡片组标题、变量卡）没有这个属性，仍是行内记号，不受影响。
 *    角标位置与本皮肤 emoji 角标同值；pointer-events 必须是 auto（emoji 角标是 none，
 *    ⓘ 要能点）。上角标的内边距补偿在上面的 .kami-item:has(...) 里一起算了。
 * 2) .kami-item-note 是网格项、会被同行最高的卡拉伸；里面的卡片不跟着伸的话，
 *    带注释的卡就比同行其它卡矮一截（网格 stretch 只拉外包层，不拉它的子元素）。
 *    flex:1 1 auto 让卡片撑满外包层；注释展开时外包层被内容撑高，卡片照旧拿自然高度。
 * ============================================================ */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-card-note[data-kami-note-mark][data-kami-corner] {
  position: absolute;
  top: 1px;
  right: 4px;
  left: auto;
  z-index: 2;
  margin-left: 0;
  pointer-events: auto;
}
html[data-kami-skin="trpg"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
html[data-kami-skin="trpg"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}


/* 列表符号：显式声明，不依赖环境继承（酒馆楼层的列表样式可能被整链重置成 none，
   皮肤只给 ::marker 上色是不够的，符号必须自己声明、自己真的画出来）。
   无序：一级 disc / 二级 circle / 三级起 square；有序：decimal → lower-alpha → lower-roman */
html[data-kami-skin="trpg"] .kami-md ul { list-style-type: disc; }
html[data-kami-skin="trpg"] .kami-md ul ul { list-style-type: circle; }
html[data-kami-skin="trpg"] .kami-md ul ul ul { list-style-type: square; }
html[data-kami-skin="trpg"] .kami-md ol { list-style-type: decimal; }
html[data-kami-skin="trpg"] .kami-md ol ol { list-style-type: lower-alpha; }
html[data-kami-skin="trpg"] .kami-md ol ol ol { list-style-type: lower-roman; }
html[data-kami-skin="trpg"] .kami-md li::marker { color: var(--kami-accent); }
html[data-kami-skin="trpg"] .kami-md li li::marker { color: var(--kami-fg-mute); }

/* 特效页说明（.kami-field 里的那枚 .kami-sub）：375px 窄屏必须能换行读全。
   结构层的 .kami-sub 是 white-space:nowrap（标题栏计数确实要单行），
   这里只对「字段标签里的说明」这一处放开，不碰标题栏 / 页脚的。 */
html[data-kami-skin="trpg"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-field .kami-field-label .kami-sub {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  min-width: 0;
}

/* ============================================================
 * · 正文美化包裹层 [data-kami-comp="body"]（已退役，2026-09-26）
 *   本节原样保留到 2026-09-26：给「只美化 <content> 标签内正文」包出来的
 *   div.kami-root[data-kami-comp="body"] 上皮（容器底 / 描边 / 圆角 / 字色）。
 *   那套功能已按用户裁定整体退役（改为直接在酒馆的消息楼层上做皮肤排版，
 *   见 src/skin/tavern.css 第 ⑤ 段与契约 §9.8），包裹层不再产生，故本节删除。
