  background-color: var(--kami-fg) !important;
  font-weight: 600;
}
html[data-kami-skin="trpg"] .kami-root select option:disabled:not(:checked) { color: var(--kami-fg-dim) !important; }/* Shared component roles: descriptions follow the selectable surface foreground. */
html[data-kami-skin="trpg"] .kami-root [data-kami-ui="choiceCard"][data-kami-card-role="choice"] > .kami-card-note { color:inherit; opacity:1; }
html[data-kami-skin="trpg"] .kami-root [data-kami-ui="field"] > .kami-card-note { color:var(--kami-fg-dim); opacity:1; }
html[data-kami-skin="trpg"] .kami-root [data-kami-ui="tabs"] .kami-tab[aria-selected="true"] { color:var(--kami-fg); }
html[data-kami-skin="trpg"] .kami-root [data-kami-ui="choiceCard"][aria-pressed="true"] { color:var(--kami-fg); }
html[data-kami-skin="trpg"] .kami-root [data-kami-ui="choiceCard"][aria-pressed="true"] .kami-item-main { color:inherit; }

html[data-kami-skin="trpg"] .kami-root [data-kami-ui="empty"] { color:var(--kami-fg-dim); }
html[data-kami-skin="trpg"] .kami-root [data-kami-ui="steps"] .is-current :is(strong,small) { color:var(--kami-fg); }

