}
html[data-kami-skin="wod"] .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev {
  transform: rotate(90deg);
  color: var(--kami-accent);
}
/* 折叠体：入场动画（位移量走 --kami-enter-y，动效档位会把它归零） */
html[data-kami-skin="wod"] .kami-collapse[data-kami-open="1"] > .kami-collapse-body {
  animation: kami-wod-in var(--kami-dur-slow) var(--kami-ease-out) backwards;
}

/* ==========================================================================
 * 3 · 按钮与分段控件
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-btn,
html[data-kami-skin="wod"] .kami-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-bg-soft);
  background-image: none;
  color: var(--kami-fg);
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-sm);
  letter-spacing: .03em;
  cursor: pointer;
  transition: background-color var(--kami-dur-fast) var(--kami-ease),
              border-color var(--kami-dur-fast) var(--kami-ease),
              color var(--kami-dur-fast) var(--kami-ease),
              box-shadow var(--kami-dur-fast) var(--kami-ease),
              transform var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="wod"] .kami-icon-btn {
  min-width: max(var(--kami-row-h), 40px);
  padding: 0;
  font-size: var(--kami-icon);
  line-height: 1;
  color: var(--kami-fg-dim);
}
/* 触屏也要有非 hover 的可点提示：icon 按钮常态就带骨线边 + 底色 */
@media (hover: hover) {
  html[data-kami-skin="wod"] .kami-btn:hover,
  html[data-kami-skin="wod"] .kami-icon-btn:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent-line);
    color: var(--kami-fg);
  }
  html[data-kami-skin="wod"] .kami-icon-btn[data-kami-act="close"]:hover {
    background-color: var(--kami-warn);
    border-color: var(--kami-warn);
    color: #2b1114;
  }
  html[data-kami-skin="wod"] .kami-root .kami-btn--primary:hover {
    filter: brightness(1.1);
    box-shadow: 0 3px 14px rgba(181, 26, 43, .55);
  }
}
html[data-kami-skin="wod"] .kami-btn:active,
html[data-kami-skin="wod"] .kami-icon-btn:active {
  transform: translateY(1px);
}
html[data-kami-skin="wod"] .kami-btn--ghost {
  background-color: transparent;
  border-color: var(--kami-line-strong);
}
html[data-kami-skin="wod"] .kami-root .kami-btn--primary {
  background-color: var(--kami-accent);
  background-image: linear-gradient(150deg, #cd2c3e 0%, var(--kami-accent) 55%, #8c1220 100%);
  border-color: rgba(255, 255, 255, .28);
  color: var(--kami-accent-fg);
  box-shadow: 0 2px 9px rgba(181, 26, 43, .42);
  font-weight: var(--kami-fw-title);
  text-shadow: 0 1px 1px rgba(0, 0, 0, .35);
}
/* 选中按钮：换深红底 → 文字一族成对翻到 accent-fg（暗底压暗字是这套最大的风险） */
html[data-kami-skin="wod"] .kami-btn.is-on,
html[data-kami-skin="wod"] .kami-btn[aria-pressed="true"],
html[data-kami-skin="wod"] .kami-icon-btn[aria-pressed="true"] {
  --kami-fg: var(--kami-accent-fg);
  --kami-fg-dim: var(--kami-accent-fg);
  --kami-fg-mute: var(--kami-accent-fg);
  --kami-line: var(--kami-accent-fg);
  --kami-line-strong: var(--kami-accent-fg);
  background-color: var(--kami-accent);
  background-image: linear-gradient(150deg, #c22a3c 0%, var(--kami-accent) 60%, #8c1220 100%);
  border-color: rgba(255, 255, 255, .3);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .18), 0 0 8px rgba(181, 26, 43, .3);
}
/* 完成反馈：一次性落章（不循环），十字是形状不是颜色 */
html[data-kami-skin="wod"] .kami-btn.is-done,
html[data-kami-skin="wod"] .kami-icon-btn.is-done {
  background-color: var(--kami-accent);
  border-color: rgba(255, 255, 255, .3);
  color: var(--kami-accent-fg);
  animation: kami-wod-stamp var(--kami-dur-slow) var(--kami-ease-out);
}
html[data-kami-skin="wod"] .kami-btn.is-done::after {
  content: " ✝";
  color: var(--kami-accent-fg);
}
/* 锁死的按钮（原生 disabled）：一眼看出点不动 */
html[data-kami-skin="wod"] .kami-btn[disabled],
html[data-kami-skin="wod"] .kami-icon-btn[disabled] {
  opacity: var(--kami-dim-lock, .42);
  background-color: var(--kami-bg-soft);
  background-image: none;
  border-color: var(--kami-line);
  color: var(--kami-fg-mute);
  cursor: default;
  transform: none;
  box-shadow: none;
}

/* 分段切换：凹槽 + 封蜡滑块 */
html[data-kami-skin="wod"] .kami-seg {
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background: var(--kami-card-2);
}
html[data-kami-skin="wod"] .kami-seg-item {
  border: 0;
  border-radius: calc(var(--kami-r-sm) - 1px);
  padding: 5px 11px;
  min-height: calc(var(--kami-row-h) - 8px);
  background: transparent;
  color: var(--kami-fg-dim);
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-xs);
  letter-spacing: .04em;
  cursor: pointer;
  transition: background-color var(--kami-dur-fast) var(--kami-ease), color var(--kami-dur-fast) var(--kami-ease);
}
@media (hover: hover) {
  html[data-kami-skin="wod"] .kami-seg-item:hover:not(.is-on) { color: var(--kami-fg); }
}
html[data-kami-skin="wod"] .kami-seg-item.is-on {
  --kami-fg: var(--kami-accent-fg);
  --kami-fg-dim: var(--kami-accent-fg);
  --kami-fg-mute: var(--kami-accent-fg);
  --kami-line: var(--kami-accent-fg);
  --kami-line-strong: var(--kami-accent-fg);
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
  box-shadow: 0 1px 4px rgba(0, 0, 0, .5);
}

/* ==========================================================================
 * 4 · 消息楼层：思维链 (think) 与行动选项 (options)
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="think"],[data-kami-comp="search"]) .kami-collapse > .kami-collapse-body {
  display: none;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="think"],[data-kami-comp="search"]) .kami-collapse[data-kami-open="1"] > .kami-collapse-body {
  display: block;
  animation: kami-wod-in var(--kami-dur-slow) var(--kami-ease-out) backwards;
}

/* 正文头部的操作行：左渲原文切换、右复制 */
html[data-kami-skin="wod"] .kami-bar {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-bottom: var(--kami-gap-lg);
  padding-bottom: var(--kami-pad-y);
  border-bottom: 1px dashed var(--kami-line);
}
html[data-kami-skin="wod"] .kami-bar > :last-child { margin-left: auto; }

/* Markdown 渲染区：古典密契手抄卷 */
html[data-kami-skin="wod"] .kami-md {
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  line-height: var(--kami-lh);
  color: var(--kami-fg);
}
html[data-kami-skin="wod"] .kami-md > :first-child { margin-top: 0; }
html[data-kami-skin="wod"] .kami-md > :last-child { margin-bottom: 0; }
html[data-kami-skin="wod"] .kami-md p { margin: .7em 0; }
html[data-kami-skin="wod"] .kami-md h1,
html[data-kami-skin="wod"] .kami-md h2,
html[data-kami-skin="wod"] .kami-md h3,
html[data-kami-skin="wod"] .kami-md h4,
html[data-kami-skin="wod"] .kami-md h5,
html[data-kami-skin="wod"] .kami-md h6 {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: calc(var(--kami-fs) * 1.1);
  letter-spacing: var(--kami-ls-title);
  color: var(--kami-fg);
  border-bottom: 1px solid var(--kami-line);
  padding-bottom: .22em;
  margin-top: 1.2em;
  margin-bottom: .55em;
}
html[data-kami-skin="wod"] .kami-md h1 { font-size: var(--kami-fs-lg); }
/* 引用块 = 手记里抄录的一段祷文 */
html[data-kami-skin="wod"] .kami-md blockquote {
  margin: .8em 0;
  padding: .5em 1em .5em .9em;
  border-left: var(--kami-accent-mark) solid var(--kami-accent-line);
  background: var(--kami-accent-soft);
  color: var(--kami-fg-dim);
  font-style: italic;
  border-radius: 0 var(--kami-r-sm) var(--kami-r-sm) 0;
}
html[data-kami-skin="wod"] .kami-md code {
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-sm);
  padding: .14em .42em;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-card-2);
  border: 1px solid var(--kami-line);
  color: #e0a3ab;
}
html[data-kami-skin="wod"] .kami-md pre {
  margin: .6em 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
}
html[data-kami-skin="wod"] .kami-md pre code {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--kami-fg);
}
html[data-kami-skin="wod"] .kami-md ul,
html[data-kami-skin="wod"] .kami-md ol { margin: .5em 0; padding-left: 1.35em; }
html[data-kami-skin="wod"] .kami-md li { margin: .2em 0; }
html[data-kami-skin="wod"] .kami-md li::marker { color: var(--kami-accent); }
/* 嵌套层级：缩进加深一档，序号压暗一档，条目行距收紧 */
html[data-kami-skin="wod"] .kami-md li > ul,
html[data-kami-skin="wod"] .kami-md li > ol {
  margin-top: .25em;
  margin-bottom: .15em;
}
html[data-kami-skin="wod"] .kami-md li li::marker { color: var(--kami-fg-mute); }
html[data-kami-skin="wod"] .kami-md strong { color: var(--kami-fg); font-weight: 700; }
html[data-kami-skin="wod"] .kami-md em {
  font-style: italic;
  color: var(--kami-fg-dim);
}
html[data-kami-skin="wod"] .kami-md a {
  color: var(--kami-fg);
  text-decoration-color: var(--kami-accent);
  text-underline-offset: 3px;
}
html[data-kami-skin="wod"] .kami-md hr {
  border: 0;
  border-top: 1px dashed var(--kami-line);
  margin: .85em 0;
}
html[data-kami-skin="wod"] .kami-md img { max-width: 100%; border-radius: var(--kami-r-sm); }
html[data-kami-skin="wod"] .kami-md table {
  border-collapse: collapse;
  width: 100%;
  font-size: var(--kami-fs-xs);
}
html[data-kami-skin="wod"] .kami-md th,
html[data-kami-skin="wod"] .kami-md td {
  border: var(--kami-border-w) solid var(--kami-line);
  padding: 4px 8px;
}
html[data-kami-skin="wod"] .kami-md th {
  font-family: var(--kami-font-title);
  letter-spacing: .04em;
  color: var(--kami-fg);
}
/* 窄屏表格不撑破：手机档把表变成可横滚的块 */
@media (max-width: 560px) {
  html[data-kami-skin="wod"] .kami-md table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
  }
}

/* 原文块：羊皮纸背面 */
html[data-kami-skin="wod"] .kami-raw {
  margin: 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  color: var(--kami-fg-dim);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-x: auto;
}

/* 行动选项 (options)：选项卡入场错峰 */
html[data-kami-skin="wod"] .kami-root[data-kami-comp="options"] .kami-grid > .kami-item {
  animation: kami-wod-in var(--kami-dur-slow) var(--kami-ease-out) backwards;
}
html[data-kami-skin="wod"] .kami-root[data-kami-comp="options"] .kami-grid > .kami-item:nth-child(2) { animation-delay: var(--kami-stagger); }
html[data-kami-skin="wod"] .kami-root[data-kami-comp="options"] .kami-grid > .kami-item:nth-child(3) { animation-delay: calc(var(--kami-stagger) * 2); }
html[data-kami-skin="wod"] .kami-root[data-kami-comp="options"] .kami-grid > .kami-item:nth-child(4) { animation-delay: calc(var(--kami-stagger) * 3); }
html[data-kami-skin="wod"] .kami-root[data-kami-comp="options"] .kami-grid > .kami-item:nth-child(5) { animation-delay: calc(var(--kami-stagger) * 3); }
html[data-kami-skin="wod"] .kami-root[data-kami-comp="options"] .kami-grid > .kami-item:nth-child(n+6) { animation-delay: calc(var(--kami-stagger) * 4); }
/* 正在处理的选项卡：下沉一点、不许再点 */
html[data-kami-skin="wod"] .kami-item[data-kami-busy="1"] {
  opacity: .75;
  pointer-events: none;
}

/* ==========================================================================
 * 5 · 列表 / 网格 / 卡片 / 条目
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
