  background-color: var(--kami-card);
  color: var(--kami-fg);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  cursor: pointer;
  transition: background-color var(--kami-dur-fast) var(--kami-ease),
              border-color var(--kami-dur-fast) var(--kami-ease),
              box-shadow var(--kami-dur-fast) var(--kami-ease),
              transform var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="wod"] .kami-item {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  width: 100%;
}
@media (hover: hover) {
  html[data-kami-skin="wod"] .kami-card:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent-line);
    transform: translateY(-1px);
    box-shadow: var(--kami-shadow-sm);
  }
}
html[data-kami-skin="wod"] .kami-card:active {
  transform: translateY(0);
}
/* 激活态：深红描边 + 内环 + 字重（三条里两条不是颜色），且文字一族照样骨白 */
html[data-kami-skin="wod"] .kami-root .kami-card.is-on,
html[data-kami-skin="wod"] .kami-root .kami-card[aria-pressed="true"] {
  border-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
  color: var(--kami-fg);
  box-shadow: inset 0 0 0 1px var(--kami-accent-line), inset var(--kami-accent-mark) 0 0 rgba(181, 26, 43, .35);
  font-weight: var(--kami-fw-title);
  animation: kami-wod-stamp var(--kami-dur) var(--kami-ease-out);
}
html[data-kami-skin="wod"] .kami-root .kami-card.is-on .kami-card-title,
