}
/* 示例数据 = 还没被封印的观察记录：压淡 + 关掉可点暗示 */
html[data-kami-skin="wod"] .kami-item.is-demo {
  opacity: var(--kami-dim-soft, .58);
  cursor: default;
  border-color: var(--kami-line);
}
html[data-kami-skin="wod"] .kami-item-main {
  flex: 1 1 auto;
  min-width: 0;
  overflow-wrap: anywhere;
}
html[data-kami-skin="wod"] .kami-item-side {
  flex: none;
  margin-left: auto;
  padding-left: 6px;
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-sm);
  line-height: 1;
  color: var(--kami-accent);
}
html[data-kami-skin="wod"] .kami-card-head {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  width: 100%;
  margin-bottom: var(--kami-gap);
}
html[data-kami-skin="wod"] .kami-card-title {
  flex: 1 1 auto;
  min-width: 0;
