}
html[data-kami-skin="wod"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}

/* ==========================================================================
 * 6 · 小标签 / 徽章 / 语义色（七种 type，各在各的位置落印）
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-chip,
html[data-kami-skin="wod"] .kami-root .kami-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  padding: 1px 7px;
  border-radius: var(--kami-r-xs);
  border: 1px solid currentcolor;
  background-color: var(--kami-t1);
  color: var(--kami-fg-dim);
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-xs);
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: .05em;
  white-space: nowrap;
}
html[data-kami-skin="wod"] .kami-chip {
  border-color: var(--kami-line);
  color: var(--kami-fg-dim);
  font-family: var(--kami-font-mono);
}
/* 语义色先落到一颗私有变量上，再由徽章 / 卡缘 / 侧栏一起消费 */
html[data-kami-skin="wod"] .kami-root [data-kami-kind="action"]  { --kami-kind-curr: var(--kami-kind-action); }
html[data-kami-skin="wod"] .kami-root [data-kami-kind="persona"] { --kami-kind-curr: var(--kami-kind-persona); }
html[data-kami-skin="wod"] .kami-root [data-kami-kind="plot"]    { --kami-kind-curr: var(--kami-kind-plot); }
html[data-kami-skin="wod"] .kami-root [data-kami-kind="info"]    { --kami-kind-curr: var(--kami-kind-info); }
html[data-kami-skin="wod"] .kami-root [data-kami-kind="fun"]     { --kami-kind-curr: var(--kami-kind-fun); }
html[data-kami-skin="wod"] .kami-root [data-kami-kind="nsfw"]    { --kami-kind-curr: var(--kami-kind-nsfw); }
html[data-kami-skin="wod"] .kami-root [data-kami-kind="other"]   { --kami-kind-curr: var(--kami-kind-other); }
/* 徽章：同色描边字 + 淡染底（七种各自成标） */
html[data-kami-skin="wod"] .kami-root .kami-badge[data-kami-kind],
html[data-kami-skin="wod"] .kami-root .kami-chip[data-kami-kind] {
  background-color: var(--kami-t2);
  color: var(--kami-kind-curr, var(--kami-fg-dim));
  border-color: var(--kami-kind-curr, var(--kami-line));
}
/* 类型徽章各色实写（audit 要七色各 ≥4 处落墨；这里逐个点名） */
html[data-kami-skin="wod"] .kami-root .kami-badge[data-kami-kind="action"]  { color: var(--kami-kind-action);  border-color: var(--kami-kind-action); }
html[data-kami-skin="wod"] .kami-root .kami-badge[data-kami-kind="persona"] { color: var(--kami-kind-persona); border-color: var(--kami-kind-persona); }
html[data-kami-skin="wod"] .kami-root .kami-badge[data-kami-kind="plot"]    { color: var(--kami-kind-plot);    border-color: var(--kami-kind-plot); }
html[data-kami-skin="wod"] .kami-root .kami-badge[data-kami-kind="info"]    { color: var(--kami-kind-info);    border-color: var(--kami-kind-info); }
html[data-kami-skin="wod"] .kami-root .kami-badge[data-kami-kind="fun"]     { color: var(--kami-kind-fun);     border-color: var(--kami-kind-fun); }
html[data-kami-skin="wod"] .kami-root .kami-badge[data-kami-kind="nsfw"]    { color: var(--kami-kind-nsfw);    border-color: var(--kami-kind-nsfw); }
html[data-kami-skin="wod"] .kami-root .kami-badge[data-kami-kind="other"]   { color: var(--kami-kind-other);   border-color: var(--kami-kind-other); }
/* 选项卡：左缘一道语义色封蜡条 */
html[data-kami-skin="wod"] .kami-root .kami-item[data-kami-kind],
html[data-kami-skin="wod"] .kami-root .kami-card[data-kami-kind] {
  border-left: var(--kami-accent-mark) solid var(--kami-kind-curr, var(--kami-accent-line));
}

/* ==========================================================================
 * 7 · 空态 / 内联提示
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-empty {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  letter-spacing: .02em;
}
/* 空态前缀：一枚封蜡色的小菱形（clip-path 自绘，不用字符画） */
html[data-kami-skin="wod"] .kami-empty::before {
  content: "";
  display: inline-block;
  width: .5em;
  height: .5em;
  margin-right: .5em;
  vertical-align: .04em;
  background-color: var(--kami-accent);
  clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
  box-shadow: 0 0 5px var(--kami-glow);
}
html[data-kami-skin="wod"] .kami-toast {
  margin-top: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-accent);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-xs);
  font-weight: 600;
  text-align: center;
  animation: kami-wod-in var(--kami-dur) var(--kami-ease-out) backwards;
}
html[data-kami-skin="wod"] .kami-toast.is-bad {
  background-color: var(--kami-warn);
  border-color: var(--kami-warn);
  color: #2b1114;
}

/* ==========================================================================
 * 8 · 面板通用（契约 §4.4：组件规则一律 .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) …）
 * ======================================================================== */
/* 面板成员通吃：面板内的卡片描边抬到「看得见」那一档 */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card,
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:not(.is-on):not([aria-pressed="true"]) {
  border-color: var(--kami-line-strong);
}
/* 面板内的条目卡：稍收紧、保证触屏可点高度 */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item {
  position: relative;
  min-height: 42px;
  padding: var(--kami-pad-y) var(--kami-pad-x);
}
/* 卡片头做成整行标题条（button.kami-card-head.kami-btn--ghost 的复用） */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) button.kami-card-head.kami-btn {
  width: 100%;
  min-height: 0;
  border: 0;
  border-radius: var(--kami-r-xs);
  justify-content: flex-start;
  padding: 6px 8px;
  background-color: transparent;
  box-shadow: none;
}
/* 分组卡内部网格：别把内边距叠两层 */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card:not(.kami-item) {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  margin-bottom: var(--kami-gap-lg);
  background-color: var(--kami-card);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card > .kami-card-body {
  padding: 2px 0 0;
}

/* —— 面板网格：密集判据必须把列宽令牌一块儿调小，否则条目一行只排一张 —— */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-grid:has(> .kami-item, > .kami-item-note) {
  --kami-items-min: 100px;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
}
/* 分组卡内部的条目网格：卡身只剩 ~350px，列宽再收半档 */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card .kami-card .kami-grid:has(> .kami-item, > .kami-item-note) {
  --kami-items-min: 88px;
}

/* —— 面板内字段 / 表单控件 —— */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-field {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--kami-gap-lg);
  padding: var(--kami-pad-y) 0;
  border-bottom: 1px solid var(--kami-t1);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-field:last-child {
  border-bottom: 0;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-field-label {
  flex: 1 1 auto;
  min-width: 0;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-field-value {
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
}
/* 滑杆：暗轨 + 封蜡圆钮 + 已走过的一段染色（--kami-value 由脚本下发 0–1） */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: var(--kami-r-pill);
  outline: none;
  border: var(--kami-border-w) solid var(--kami-line);
  background: linear-gradient(90deg,
    var(--kami-accent) 0%, var(--kami-accent) calc(var(--kami-value, 0) * 100%),
    var(--kami-card-2) calc(var(--kami-value, 0) * 100%), var(--kami-card-2) 100%);
  cursor: pointer;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #e05a68 0%, var(--kami-accent) 65%);
  border: 2px solid var(--kami-line-strong);
  cursor: pointer;
  box-shadow: 0 0 4px rgba(0, 0, 0, .6);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-range::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--kami-accent);
  border: 2px solid var(--kami-line-strong);
  cursor: pointer;
}
/* 开关：方角轨道 + 骨白旋钮，选中泛红像烛火点亮 */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-switch {
  position: relative;
  display: inline-block;
  width: 44px;
  height: 24px;
  cursor: pointer;
  user-select: none;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-switch-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-switch {
  position: absolute;
  inset: 0;
  background-color: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-pill);
  transition: background-color var(--kami-dur-fast) var(--kami-ease), border-color var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-switch-thumb {
  position: absolute;
  left: 3px;
  top: 3px;
  width: 16px;
  height: 16px;
  background-color: var(--kami-fg-mute);
  border-radius: 50%;
  transition: transform var(--kami-dur-fast) var(--kami-ease), background-color var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-switch[data-state="checked"] {
  background-color: var(--kami-accent-soft);
  border-color: var(--kami-accent);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-switch[data-state="checked"] .kami-switch-thumb {
  transform: translateX(20px);
  background-color: var(--kami-accent);
  box-shadow: 0 0 6px var(--kami-glow);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-switch:focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

/* 对比度四件套（硬性三项 !important：background-color + color + color-scheme）。
   面板输入一律走「墨井」：暗色深井压骨白字，两档方案同读数（13:1），亮档也不劣化。 */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-number,
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-text,
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-textarea,
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
  background-color: #171119 !important;
  color: #f2e8d5 !important;
  color-scheme: dark !important;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  text-align: left;
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, .6);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-number {
  width: 68px;
  min-height: 30px;
  padding: 2px 7px;
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  font-variant-numeric: tabular-nums;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-textarea { resize: vertical; }
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
  -webkit-appearance: none;
  appearance: none;
  padding-right: calc(var(--kami-pad-x) + 16px);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg-mute) 50%),
    linear-gradient(135deg, var(--kami-fg-mute) 50%, transparent 50%);
  background-size: 4px 4px, 4px 4px;
  background-position: calc(100% - 13px) calc(50% + 1px), calc(100% - 9px) calc(50% + 1px);
  background-repeat: no-repeat;
  cursor: pointer;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) input.kami-number[type="number"] {
  text-align: right;
}

/* —— 面板 Tabs —— */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-tabs {
  display: flex;
  gap: 2px;
  padding: 0 var(--kami-pad-lg-x);
  border-bottom: 1px solid var(--kami-line);
  background: var(--kami-bg-soft);
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
  mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-tabs::-webkit-scrollbar { display: none; }
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-tab {
  flex: none;
  min-height: calc(var(--kami-row-h) - 6px);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: 0;
  border-bottom: var(--kami-accent-mark) solid transparent;
  background: transparent;
  color: var(--kami-fg-dim);
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-sm);
  letter-spacing: .05em;
  white-space: nowrap;
  cursor: pointer;
  transition: color var(--kami-dur-fast) var(--kami-ease), border-color var(--kami-dur-fast) var(--kami-ease);
}
@media (hover: hover) {
  html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-tab:hover { color: var(--kami-fg); }
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-tab[aria-selected="true"] {
  color: var(--kami-fg);
  border-bottom-color: var(--kami-accent);
  font-weight: var(--kami-fw-title);
}

/* —— 拖动抓手 —— */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-head[data-kami-drag] { cursor: grab; }
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-head[data-kami-drag]:active { cursor: grabbing; }

/* —— 缩放手柄 —— */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-resize {
  position: absolute;
  right: 2px;
  bottom: 2px;
  width: 16px;
  height: 16px;
  cursor: se-resize;
  z-index: 3;
  background: linear-gradient(135deg, transparent 50%, var(--kami-line-strong) 50%, var(--kami-line-strong) 70%, transparent 70%, transparent 85%, var(--kami-line-strong) 85%);
}

/* ==========================================================================
 * 9 · 角标与注释（预设 / 引导两块面板同一套 DOM，绝不挂面板 id）
 * ======================================================================== */
/* emoji 角标（条目名里摘出来的那枚）：钉在卡角、不占宽度、不抢点击 */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge {
  position: absolute;
  top: 1px;
  right: 4px;
  left: auto;
  z-index: 2;
  padding: 0;
  border: 0;
  background: none;
  font-size: var(--kami-fs-xs);
  font-family: var(--kami-font);
  line-height: 1.25;
  color: var(--kami-fg-mute);
  pointer-events: none;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="tl"],
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 4px;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="br"],
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 1px;
}
/* ⓘ 注释标记：右上角角标（tr），必须能点（-opposite：emoji 角标是 none） */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-card-note[data-kami-note-mark][data-kami-corner],
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card > .kami-card-head [data-kami-note-mark] {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.45em;
  height: 1.45em;
  margin-left: 4px;
  border: var(--kami-border-w) solid var(--kami-accent);
  border-radius: var(--kami-r-pill);
  background: var(--kami-accent-soft);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-card-note[data-kami-note-mark][data-kami-corner] {
  position: absolute;
  top: 3px;
  right: 4px;
  left: auto;
  z-index: 3;
  margin-left: 0;
  pointer-events: auto;
}
@media (hover: hover) {
  html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note-mark]:hover {
    background: var(--kami-accent);
    color: var(--kami-accent-fg);
  }
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note-mark]:focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 1px;
}
/* 上/下角标的内边距补偿：条目卡里有 tl/tr ⓘ 时顶上让出一格 */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
  padding-top: calc(var(--kami-pad-y) + 1em);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-y) + 1em);
}
/* 注释正文（展开出来的那块）：羊皮纸批注 */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note] {
  display: block;
  margin: 5px 0 0;
  padding: 6px 9px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background: var(--kami-card-2);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
  text-align: left;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card-note[data-kami-note][hidden] { display: none; }

/* ==========================================================================
 * 10 · 锁死的条目（原生 disabled）：一眼看出点不动
 *      预设面板里固定有十几个「非当前模型」的条目带原生 disabled，兜底皮肤的
 *      同类规则被 html:not([data-kami-skin]) 限定，真实皮肤生效时一条都不匹配。
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled],
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover,
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  border-style: dashed;
  box-shadow: none;
  transform: none;
  opacity: var(--kami-dim-lock, .42);
  color: var(--kami-fg-mute);
  cursor: default;
  font-weight: var(--kami-fw);
  animation: none;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled] .kami-item-main,
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled] .kami-card-title,
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled] .kami-item-side {
  color: var(--kami-fg-mute);
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover::before,
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover::after {
  animation: none;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover > .kami-badge {
  transform: none;
}
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled] .kami-item.is-demo {
  opacity: var(--kami-dim-lock, .42);
}

/* ==========================================================================
 * 11 · 预览窗与滚动区
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-pv,
html[data-kami-skin="wod"] .kami-pv-frame,
html[data-kami-skin="wod"] .kami-guide-pv,
html[data-kami-skin="wod"] .kami-guide-pv-frame {
  pointer-events: none;
}
html[data-kami-skin="wod"] .kami-pv {
  position: relative;
  display: block;
  overflow: hidden;
  border-radius: var(--kami-r-sm);
  border: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-card-2);
}
html[data-kami-skin="wod"] .kami-pv-frame {
  display: block;
  width: 100%;
  border: 0;
  filter: saturate(.92);
}
html[data-kami-skin="wod"] .kami-guide-pv {
  position: relative;
  display: block;
  overflow: hidden;
  border-radius: var(--kami-r-sm);
  border: var(--kami-border-w) solid var(--kami-line);
}
html[data-kami-skin="wod"] .kami-guide-pv-frame {
  display: block;
  width: 100%;
  border: 0;
}
html[data-kami-skin="wod"] .kami-preview {
  position: relative;
  border-radius: var(--kami-r-md);
  border: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-card);
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
html[data-kami-skin="wod"] .kami-preview i {
  display: block;
  height: 6px;
  border-radius: var(--kami-r-pill);
  background: var(--kami-t3);
}
html[data-kami-skin="wod"] .kami-preview i:first-child {
  width: 58%;
  background: var(--kami-accent);
}
html[data-kami-skin="wod"] .kami-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-line-strong) transparent;
}
html[data-kami-skin="wod"] .kami-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
html[data-kami-skin="wod"] .kami-scroll::-webkit-scrollbar-track { background: transparent; }
html[data-kami-skin="wod"] .kami-scroll::-webkit-scrollbar-thumb {
  background: var(--kami-line-strong);
  border-radius: var(--kami-r-pill);
}
html[data-kami-skin="wod"] .kami-scroll::-webkit-scrollbar-thumb:hover { background: var(--kami-accent); }

/* ==========================================================================
 * 12 · 面板本体几何与贴底抽屉（唯一允许不带 comp 限定的「骨架」段）
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) {
  background-color: rgba(10, 6, 14, .55);
}
html[data-kami-skin="wod"][data-kami-scheme="light"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) {
  background-color: rgba(58, 40, 28, .28);
}
html[data-kami-skin="wod"] .kami-root .kami-drop.kami-drop {
  position: absolute;
  left: var(--kami-panel-x, 50%);
  top: var(--kami-panel-y, 72px);
  width: var(--kami-panel-w, min(840px, calc(100% - 24px)));
  height: var(--kami-panel-h, 1120px);
  max-height: calc(100% - 24px);
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background-color: var(--kami-bg);
  background-image: var(--kami-texture);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
}
html[data-kami-skin="wod"] .kami-drop > .kami-head {
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-bg-soft);
  min-height: calc(var(--kami-row-h) + var(--kami-pad-y));
}
/* ⚠️ 面板滚动链路（2026-09-23 修「不能上下滑动」）：平台几何层只下发位置与尺寸，
   滚动区必须**被约束高度**才可能滚 —— 头/页签/脚不伸缩，中间页吃掉剩余高度。
   缺这条的表现：内容按自身高度撑开、没有溢出可滚，拖也拖不动（civdawn 真机报过同款）。 */
html[data-kami-skin="wod"] .kami-drop > .kami-head,
html[data-kami-skin="wod"] .kami-drop > .kami-tabs,
html[data-kami-skin="wod"] .kami-drop > .kami-foot { flex: 0 0 auto; }
html[data-kami-skin="wod"] .kami-drop > .kami-body { flex: 1 1 auto; min-height: 0; }
/* 贴底抽屉（脚本下发的 data-kami-layout="sheet"） */
html[data-kami-skin="wod"] .kami-root .kami-drop.kami-drop[data-kami-layout="sheet"] {
  left: 0;
  right: 0;
  top: auto;
  bottom: 0;
  width: auto;
  height: 78%;
  max-height: 78%;
  border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
}

/* ==========================================================================
 * 13 · 引导向导排版层（类名来自 §4.5，皮肤只补材质层面）
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-guide-lead {
  line-height: 1.85;
  color: var(--kami-fg-dim);
}
html[data-kami-skin="wod"] .kami-guide-offnote {
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  line-height: 1.7;
}
html[data-kami-skin="wod"] .kami-guide-sec {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls-title);
  color: var(--kami-fg);
}
html[data-kami-skin="wod"] .kami-guide-doc {
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-sm);
  line-height: 1.75;
}
html[data-kami-skin="wod"] .kami-guide-grid { gap: var(--kami-gap); }
html[data-kami-skin="wod"] .kami-guide-plate {
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  padding-bottom: 4px;
}
html[data-kami-skin="wod"] .kami-guide-plate-glyph {
  color: var(--kami-accent);
  font-size: var(--kami-icon);
  line-height: 1;
}
html[data-kami-skin="wod"] .kami-guide-plate-name {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  color: var(--kami-fg);
}
html[data-kami-skin="wod"] .kami-guide-capdesc {
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-xs);
  line-height: 1.6;
}
html[data-kami-skin="wod"] .kami-guide-skins { gap: var(--kami-gap-lg); }
html[data-kami-skin="wod"] .kami-guide-cap {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  letter-spacing: var(--kami-ls-title);
  color: var(--kami-fg);
}
html[data-kami-skin="wod"] .kami-guide-grid-cards,
html[data-kami-skin="wod"] .kami-guide-grid-models { gap: var(--kami-gap-lg); }
/* 模型卡里的条目网格：卡内条目别被通用列宽挤成竖排单字 */
html[data-kami-skin="wod"] .kami-guide-grid-models .kami-grid:has(> .kami-item, > .kami-item-note) {
  --kami-items-min: 150px;
}
html[data-kami-skin="wod"] .kami-guide-switchrow {
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
}
html[data-kami-skin="wod"] .kami-guide-switchrow.is-on {
  border-color: var(--kami-accent-line);
  background: var(--kami-accent-soft);
}
html[data-kami-skin="wod"] .kami-guide-rowname {
  color: var(--kami-fg);
  font-size: var(--kami-fs-sm);
}
html[data-kami-skin="wod"] .kami-guide-rowstate {
  color: var(--kami-fg-mute);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  font-variant-numeric: tabular-nums;
}
html[data-kami-skin="wod"] .kami-guide-switchrow.is-on .kami-guide-rowstate { color: var(--kami-accent); }
html[data-kami-skin="wod"] .kami-guide-varrow { gap: var(--kami-gap); }
/* 引导进度点（.kami-dots 里复用 .kami-dot） */
html[data-kami-skin="wod"] .kami-dots {
  display: flex;
  align-items: center;
  gap: 7px;
}
html[data-kami-skin="wod"] .kami-dots .kami-dot {
  width: 7px;
  height: 7px;
  box-shadow: none;
  opacity: .38;
}
html[data-kami-skin="wod"] .kami-dots .kami-dot[data-kami-on="1"] {
  opacity: 1;
  box-shadow: 0 0 6px var(--kami-glow);
}

/* ==========================================================================
 * 14 · 关键帧（入场 / 强调 / 循环，三件套 + 落章）
 * ======================================================================== */
@keyframes kami-wod-in {
  from { opacity: 0; transform: translateY(calc(var(--kami-enter-y) * -1)) scale(var(--kami-enter-scale)); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes kami-wod-stamp {
  0%   { transform: scale(1); }
  45%  { transform: scale(1.035); }
  100% { transform: scale(1); }
}
@keyframes kami-wod-flicker {
  0%, 100% { box-shadow: 0 0 calc(4px + 2px * var(--kami-wod-candle) / 50) var(--kami-glow), inset 0 0 0 1px rgba(255, 255, 255, .22); }
  33%      { box-shadow: 0 0 calc(8px + 3px * var(--kami-wod-candle) / 50) var(--kami-glow), inset 0 0 0 1px rgba(255, 255, 255, .3); }
  61%      { box-shadow: 0 0 calc(3px + 1px * var(--kami-wod-candle) / 50) var(--kami-glow), inset 0 0 0 1px rgba(255, 255, 255, .18); }
}
@keyframes kami-wod-seep {
  0%, 100% { opacity: calc(.6 + .3 * var(--kami-wod-mist) / 100); }
  50%      { opacity: calc(.85 + .1 * var(--kami-wod-mist) / 100); }
}

/* ==========================================================================
 * 15 · 动效降级（off 档循环动画一律 none；1ms 无位移由令牌管）
 * ======================================================================== */
@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="wod"] .kami-root *,
  html[data-kami-skin="wod"] .kami-root *::before,
  html[data-kami-skin="wod"] .kami-root *::after {
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 1ms !important;
  }
}
html[data-kami-skin="wod"][data-kami-motion="off"] .kami-root *,
html[data-kami-skin="wod"][data-kami-motion="off"] .kami-root *::before,
html[data-kami-skin="wod"][data-kami-motion="off"] .kami-root *::after {
  animation: none !important;
  transition-duration: 1ms !important;
}
html[data-kami-skin="wod"][data-kami-motion="calm"] .kami-dot,
html[data-kami-skin="wod"][data-kami-motion="calm"] .kami-shell::after {
  animation: none !important;
}
html[data-kami-skin="wod"][data-kami-motion="off"] .kami-dot,
html[data-kami-skin="wod"][data-kami-motion="off"] .kami-shell::after {
  animation: none !important;
}

/* ==========================================================================
 * 16 · 装饰：d10 真 3D 十面骰（平台装饰模块升级出的 DOM，五角偏方二十四面体）
 *      面片是风筝形（十面体的风筝面，宽高比与二十面体的三角面不同），
 *      配色 / 描边 / 字型与原 d20 规则逐条对应。
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-deco[data-kami-deco="d10"] {
  display: inline-block;
  position: relative;
  flex: none;
  width: calc(var(--kami-fs) * 2.2);
  height: calc(var(--kami-fs) * 2.2);
  margin: 0 4px 0 0;
  pointer-events: auto;
  cursor: pointer;
}
html[data-kami-skin="wod"] .kami-deco.kami-d10::before,
html[data-kami-skin="wod"] .kami-deco.kami-d10::after {
  content: none;
  animation: none !important;
}
html[data-kami-skin="wod"] .kami-d10-stage {
  display: inline-flex;
  width: 100%;
  height: 100%;
}
html[data-kami-skin="wod"] .kami-d10-face {
  background-color: var(--kami-wod-d10-edge);
}
html[data-kami-skin="wod"] .kami-d10-face > i {
  clip-path: var(--kami-d10-clip-i);
  background-image: linear-gradient(145deg, #2a1f2d 0%, #120e14 100%);
  color: var(--kami-wod-d10-gold);
  font-family: var(--kami-font-title);
  font-size: calc(var(--kami-d10-s, 32px) * .36);
  font-weight: 700;
  text-shadow: 0 0 3px rgba(181, 26, 43, .8);
}
html[data-kami-skin="wod"] .kami-d10-face:nth-child(even) > i {
  background-image: linear-gradient(145deg, #36151e 0%, #170d11 100%);
  color: #f2e6d0;
}
@media (hover: hover) {
  html[data-kami-skin="wod"] .kami-d10-face:hover > i { filter: brightness(1.18); }
}
html[data-kami-skin="wod"] .kami-d10[data-kami-d10-rolling="1"] { cursor: progress; }
html[data-kami-skin="wod"] .kami-d10-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

/* ==========================================================================
 * 15 · 特效实现（每个 id 都在 skin.json 的 effects 里登记）
 * ======================================================================== */
/* 1. 血契红光 (blood)：状态点 / 头部封线 / 选中态的出血感 */
html[data-kami-skin="wod"][data-kami-effects~="blood"] .kami-dot {
  box-shadow: 0 0 calc(6px * var(--kami-wod-blood) / 50) var(--kami-glow), 0 0 1px #fff;
}
html[data-kami-skin="wod"][data-kami-effects~="blood"] .kami-shell {
  box-shadow: var(--kami-shadow), 0 0 calc(12px * var(--kami-wod-blood) / 50) rgba(181, 26, 43, .22);
}
html[data-kami-skin="wod"][data-kami-effects~="blood"] .kami-card.is-on,
html[data-kami-skin="wod"][data-kami-effects~="blood"] .kami-btn.is-on {
  box-shadow: inset 0 0 calc(12px * var(--kami-wod-blood) / 50) rgba(181, 26, 43, .3), 0 0 8px rgba(181, 26, 43, .2);
}
html[data-kami-skin="wod"][data-kami-effects~="blood"] .kami-root .kami-btn--primary {
  box-shadow: 0 2px 9px rgba(181, 26, 43, .42), 0 0 calc(10px * var(--kami-wod-blood) / 50) rgba(181, 26, 43, .35);
}
/* 2. 玫瑰花窗 (rose)：外壳铺玫瑰花窗暗纹，卡片右下角一角 */
html[data-kami-skin="wod"][data-kami-effects~="rose"] .kami-surface::before {
  content: "";
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  background-image: var(--kami-wod-rose-pattern);
  background-repeat: repeat;
  background-size: 160px 160px;
  background-position: center top;
  opacity: calc(var(--kami-wod-rose) * .01);
  pointer-events: none;
  mix-blend-mode: overlay;
  z-index: 0;
}
html[data-kami-skin="wod"][data-kami-effects~="rose"] .kami-card::after {
  content: "";
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  background-image: var(--kami-wod-rose-pattern);
  background-size: 120px 120px;
  background-position: right bottom;
  opacity: calc(var(--kami-wod-rose) * .006);
  pointer-events: none;
}
/* 3. 夜雾流转 (mist)：外壳边缘沉下一圈暗角 + 长周期呼吸（循环动画） */
html[data-kami-skin="wod"][data-kami-effects~="mist"] .kami-shell::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(circle at 50% 40%, transparent 55%, rgba(5, 2, 9, calc(.55 * var(--kami-wod-mist) / 100)) 100%);
  animation: kami-wod-seep 9s ease-in-out infinite;
}
/* 4. 羊皮纸痕 (parchment)：正文横线 + 表面细噪 */
html[data-kami-skin="wod"][data-kami-effects~="parchment"] .kami-md {
  background-image: repeating-linear-gradient(0deg, rgba(220, 190, 150, calc(.03 * var(--kami-wod-aging) / 100)) 0 1px, transparent 1px 24px);
}
html[data-kami-skin="wod"][data-kami-effects~="parchment"] .kami-shell {
  background-image:
    var(--kami-texture),
    radial-gradient(circle at 18% 24%, rgba(220, 190, 150, calc(.04 * var(--kami-wod-aging) / 100)) 0%, transparent 26%),
    radial-gradient(circle at 82% 70%, rgba(120, 70, 40, calc(.05 * var(--kami-wod-aging) / 100)) 0%, transparent 30%);
}
/* 5. 烛影摇曳 (candle)：状态点烛火起伏 + 标题微光呼吸（循环动画） */
html[data-kami-skin="wod"][data-kami-effects~="candle"] .kami-dot {
  animation: kami-wod-flicker 3.4s ease-in-out infinite;
}
html[data-kami-skin="wod"][data-kami-effects~="candle"] .kami-title {
  text-shadow: 0 1px 2px rgba(0, 0, 0, .72), 0 0 calc(2px + 6px * var(--kami-wod-candle) / 100) rgba(236, 224, 213, .22);
}
/* 6. 封蜡印痕 (seal)：选中卡片盖下右下角血印 */
html[data-kami-skin="wod"][data-kami-effects~="seal"] .kami-card.is-on::before {
  content: "";
  position: absolute;
  right: 5px;
  bottom: 5px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  clip-path: polygon(50% 0%, 84% 16%, 100% 50%, 84% 84%, 50% 100%, 16% 84%, 0% 50%, 16% 16%);
  background: radial-gradient(circle at 40% 36%, #dd4152 0%, var(--kami-accent) 55%, #6d0a16 100%);
  box-shadow: 0 1px 3px rgba(0, 0, 0, .5);
  pointer-events: none;
  animation: kami-wod-stamp var(--kami-dur) var(--kami-ease-out);
}

/* ==========================================================================
 * 16 · 容器查询（外壳窄到一定程度时收敛排版）
 * ======================================================================== */
@container kami-shell (max-width: 21rem) {
  html[data-kami-skin="wod"] .kami-root .kami-title { --kami-ls-title: .05em; }
  html[data-kami-skin="wod"] .kami-root .kami-bar { flex-wrap: wrap; }
}
