  background-color: var(--kami-card) !important;
  color: var(--kami-fg) !important;
  color-scheme: light !important;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  padding: 6px 10px;
  transition: border-color var(--kami-dur-fast) var(--kami-ease), box-shadow var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-number:focus,
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-text:focus,
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-textarea:focus,
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select:focus {
  border-color: var(--kami-accent);
  box-shadow: 0 0 0 2px var(--kami-accent-soft);
}

html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) input.kami-number[type="number"] {
  text-align: right;
}

html[data-kami-skin="xianyun"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-number,
html[data-kami-skin="xianyun"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-text,
html[data-kami-skin="xianyun"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-textarea,
html[data-kami-skin="xianyun"][data-kami-scheme="dark"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-select {
  color-scheme: dark !important;
}

/* 控件通用排版 */
html[data-kami-skin="xianyun"] input.kami-text,
html[data-kami-skin="xianyun"] textarea.kami-textarea,
html[data-kami-skin="xianyun"] .kami-select {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="xianyun"] textarea.kami-textarea {
  resize: vertical;
}

/* 下拉选单自绘箭头 */
html[data-kami-skin="xianyun"] .kami-select {
  -webkit-appearance: none;
  appearance: none;
  padding-right: calc(var(--kami-pad-x) + 18px);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg-mute) 50%),
    linear-gradient(135deg, var(--kami-fg-mute) 50%, transparent 50%);
  background-size: 4px 4px, 4px 4px;
  background-position: calc(100% - 14px) calc(50% + 1px), calc(100% - 10px) calc(50% + 1px);
  background-repeat: no-repeat;
  cursor: pointer;
}

/* 禁用与锁死状态（契约 §4.2 & 用户友好性） */
html[data-kami-skin="xianyun"] .kami-root .kami-btn[disabled],
html[data-kami-skin="xianyun"] .kami-root .kami-icon-btn[disabled] {
  opacity: .42;
  cursor: default;
  pointer-events: none;
  transform: none !important;
  box-shadow: none !important;
}

html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled],
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover,
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: .42;
  color: var(--kami-fg-mute);
  cursor: default;
}

html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover::before,
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover::after {
  transform: scale(0);
  opacity: 0;
