html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item[disabled]:hover > .kami-badge {
  transform: none;
}

/* ==========================================================================
 * 6 · 结构与等高约束（契约 §4.2 硬规则）
 * ======================================================================== */
html[data-kami-skin="xianyun"] .kami-root .kami-item-note {
