/* 面板内选中态：朱砂方印边线与印晕 */
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-card.is-on,
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item.is-on,
