/* 面板卡头：与卡同宽的矩形条，不做悬空胶囊 */
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) button.kami-card-head.kami-btn {
