/* 条目卡在面板里的排版与注释角标 */
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item {
  padding: 10px 12px;
  min-height: 42px;
}

/* ⓘ 注释标记：右上角角标，只占高度不占宽度；必须能点。
   margin:0 —— .kami-card-note 的 margin-top:4px 会把角标整体推低，压到条目名。
   尺寸收成 1.4em 的方框（行内记号是整行 line-box，1.68 行高下会有 19.6px 高，
   比补偿量还大，紧凑密度档会重新压住名字）。 */
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-card-note[data-kami-note-mark][data-kami-corner] {
  position: absolute;
  top: 6px;
  right: 6px;
  left: auto;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.4em;
  height: 1.4em;
  line-height: 1;
  margin: 0;
  pointer-events: auto;
  cursor: pointer;
}

/* ── 2026-09-25 修「emoji 角标挡住条目名」─────────────────────────────────
   旧写法：条目卡里那枚 emoji 角标继续吃 `.kami-badge` 的「朱砂小短签」造型
   （padding:2px 7px ＋ 1px 描边 ＋ --kami-card-2 米白底），而且是**行内 flex 项**，
   不是绝对定位 —— 它和条目名挤在同一行，把名字的可用宽度吃掉。
   预览台实测（1280×900、面板 420×560、条目卡 112×227）：
     · ⓘ ∩ "DS/GLM底部破限" = 11.5 × 19.6 = 226.8px²，名字只剩 13.4px 宽；
     · ⓘ ∩ "DeepSeek强强" 等 5 例 = 5.9 × 19.6 = 116.5px²；
     · 112 张条目卡里 39 张有重叠，最大 226.8px²（全项目唯一的重灾）。
   修法（与兜底皮肤 src/skin/base.css:851-886 同一套机制）：
     · 角标退成「一枚纯字形」——去掉内边距 / 描边 / 底色，并绝对定位到卡角，
       点不中的部分不接事件；
     · 角标**只占高度不占宽度**（契约 §4.4）：有上角标就补卡片上内边距，
       有下角标就补下内边距，条目名那一行永远拿整张卡的宽度。 */
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner] {
  position: absolute;
  top: 6px;
  right: 6px;
  left: auto;
  z-index: 2;
  padding: 0;
  border: 0;
  background: none;
  font-size: var(--kami-fs-xs);
  line-height: 1.2;
  color: var(--kami-fg-mute);
  pointer-events: none;
}
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="tl"],
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 6px;
}
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="br"],
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 6px;
}
/* 让出高度：1.4em 取的是**卡片**的字号（--kami-fs-sm），ⓘ 的 1.4em 取的是它自己的
   --kami-fs-xs；fs-sm > fs-xs，所以这一项必然盖过角标本体的高，再加 --kami-pad-y
   盖过角标的 top 偏移 —— 紧凑密度档（pad-y 5px）下也仍然成立。 */
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
  padding-top: calc(var(--kami-pad-y) + 1.4em);
}
html[data-kami-skin="xianyun"] .kami-root:is([data-kami-comp="panel"],[data-kami-comp="dialog"]) .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-y) + 1.4em);
}

html[data-kami-skin="xianyun"] .kami-root .kami-item-note > .kami-card-note[data-kami-note] {
  margin-top: 4px;
}

/* —— 设置项一行（.kami-field） —— */
html[data-kami-skin="xianyun"] .kami-field {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--kami-gap-lg);
