  border-bottom: var(--kami-border-w) solid var(--kami-line);
}

html[data-kami-skin="xianyun"] .kami-field:last-child {
  border-bottom: none;
}

html[data-kami-skin="xianyun"] .kami-field-label {
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="xianyun"] .kami-field-value {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
}

/* —— 开关 Switch —— */
html[data-kami-skin="xianyun"] .kami-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  user-select: none;
}

html[data-kami-skin="xianyun"] .kami-switch-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

html[data-kami-skin="xianyun"] .kami-switch {
  width: 38px;
  height: 22px;
  border-radius: var(--kami-r-pill);
