  transition: transform var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="xianyun"] .kami-range::-webkit-slider-thumb:hover {
  transform: scale(1.15);
}

html[data-kami-skin="xianyun"] .kami-range::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: var(--kami-accent);
  border: 2px solid #ffffff;
  box-shadow: 0 1px 4px rgba(28, 28, 30, 0.35);
