}

/* —— 进度点容器 —— */
html[data-kami-skin="xianyun"] .kami-dots {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* —— 滚动条 —— */
html[data-kami-skin="xianyun"] .kami-scroll {
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-line-strong) transparent;
}

html[data-kami-skin="xianyun"] .kami-scroll::-webkit-scrollbar {
  width: 6px;
}

html[data-kami-skin="xianyun"] .kami-scroll::-webkit-scrollbar-track {
  background: transparent;
}

html[data-kami-skin="xianyun"] .kami-scroll::-webkit-scrollbar-thumb {
  background-color: var(--kami-line-strong);
  border-radius: var(--kami-r-pill);
}

/* —— 尺寸把手 —— */
html[data-kami-skin="xianyun"] .kami-resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 14px;
  height: 14px;
  cursor: nwse-resize;
  background-image: linear-gradient(135deg, transparent 50%, var(--kami-line-strong) 50%, var(--kami-line-strong) 65%, transparent 65%, transparent 80%, var(--kami-line-strong) 80%);
}

/* —— 移动端抽屉（Sheet） —— */
html[data-kami-skin="xianyun"] .kami-drop[data-kami-layout="sheet"] {
