}

/* ==========================================================================
 * 10 · 特效实现（四大水墨修仙特效）
 * ======================================================================== */
/* 1. 水墨晕染（inkwash）：边缘多层淡墨径向渐变渗透 */
html[data-kami-skin="xianyun"][data-kami-effects~="inkwash"] .kami-shell::before,
html[data-kami-skin="xianyun"][data-kami-effects~="inkwash"] .kami-drop::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 140px;
  height: 140px;
  pointer-events: none;
  background-image: radial-gradient(circle at 85% 15%, rgba(28, 28, 30, calc(.14 * var(--kami-xy-ink) / 100)) 0%, transparent 65%),
                    radial-gradient(ellipse at 95% 5%, rgba(70, 70, 73, calc(.18 * var(--kami-xy-ink) / 100)) 0%, transparent 45%);
  z-index: 0;
}

/* 2. 宣纸帘纹（xuanzhi）：微细宣纸横竖纹理肌理 */
html[data-kami-skin="xianyun"][data-kami-effects~="xuanzhi"] .kami-surface {
  background-image:
    repeating-linear-gradient(0deg, rgba(28, 28, 30, calc(.018 * var(--kami-xy-xuan) / 100)) 0 1px, transparent 1px 4px),
    repeating-linear-gradient(90deg, rgba(28, 28, 30, calc(.012 * var(--kami-xy-xuan) / 100)) 0 1px, transparent 1px 12px),
    var(--kami-texture);
}

/* 3. 朱砂印章（seal）：标题古印微芒与卡片朱印边线 */
html[data-kami-skin="xianyun"][data-kami-effects~="seal"] .kami-title {
  text-shadow: 0 0 6px rgba(184, 36, 36, calc(.25 * var(--kami-xy-seal) / 100));
}

html[data-kami-skin="xianyun"][data-kami-effects~="seal"] .kami-item.is-on {
  box-shadow: 0 0 0 1px rgba(184, 36, 36, calc(.45 * var(--kami-xy-seal) / 100)), var(--kami-shadow-sm);
}

/* 4. 云烟飘渺（mist）：外壳与浮层底部淡雅修仙闲云意象 */
html[data-kami-skin="xianyun"][data-kami-effects~="mist"] .kami-shell::after,
html[data-kami-skin="xianyun"][data-kami-effects~="mist"] .kami-drop::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60px;
  pointer-events: none;
  background-image: linear-gradient(to top, rgba(28, 28, 30, calc(.03 * var(--kami-xy-ink) / 100)), transparent);
  z-index: 0;
}

/* ==========================================================================
 * 11 · 窄屏与移动端适配（320px 必须成立）
 * ======================================================================== */
@media (max-width: 560px) {
  html[data-kami-skin="xianyun"] .kami-root {
