  /* 独立容器（div）：它现在是卡片/包裹层的兄弟节点，不再是按钮的子节点 */
  var t = pcMake(doc, 'div', 'kami-card-note');
  t.setAttribute('data-kami-note', '1');
  t.setAttribute('hidden', 'hidden');
  t.textContent = note;
  return t;
