     所以调用方不传就是 null；模式卡（🎛 [模式切换]）传 '单选' 才有单选标记。 */
  body.appendChild(buildItemsGrid(doc, items, { key: key, mode: opts.mode || null }, opts));
  box.appendChild(body);
  return box;
