    })();
    var list = [], curId = null;
    try { list = api.skins() || []; curId = api.skin; } catch (e) { }
    var grid = el('div', 'kami-guide-skins');
    for (var i = 0; i < list.length; i++) {
      (function (s) {
        var b = el('button', 'kami-item kami-card');
