ight:24px;cursor:nwse-resize;touch-action:none;}\n@media(max-width:600px){.kami-root[data-kami-container=\"panel\"] .kami-resize{display:none;}}\n\n/* New semantic components own readable text; themes still supply every color token. */\n.kami-root [data-kami-ui=\"sources\"] a{color:var(--kami-fg);text-decoration:underline;text-underline-offset:.18em;overflow-wrap:anywhere;}\n.kami-root [data-kami-ui=\"field\"] .kami-ui-field-error{color:var(--kami-fg);border-inline-start:3px solid var(--kami-warn);padding-inline-start:.65em;flex-basis:100%;}\n\n/* Long modal content scrolls in its body; theme shell decoration cannot change this structure. */\n.kami-root.kami-root[data-kami-container=\"dialog\"]>.kami-shell.kami-shell{display:flex;flex-direction:column;max-height:90dvh;min-height:0;margin:0;overflow:hidden;}\n.kami-root.kami-root[data-kami-container=\"dialog\"]>.kami-shell>.kami-body{flex:1 1 auto;min-height:0;overflow:auto;}\n.kami-root.kami-root[data-kami-container=\"dialog\"]>.kami-shell>:is(.kami-head,.kami-foot){flex:0 0 auto;}\n\n.kami-root.kami-root[data-kami-container=\"dialog\"]{position:relative;width:100%;max-width:100%;height:auto;min-height:0;margin:0;pointer-events:auto;}\n\n/* Tab navigation is a one-row scrolling rail, never a wrapping action group. */\n.kami-root .kami-tabs{display:flex;flex-direction:row;flex-wrap:nowrap;min-width:0;max-width:100%;overflow-x:auto;overflow-y:hidden;align-items:center;white-space:nowrap;touch-action:pan-x;overscroll-behavior-x:contain;}\n.kami-root .kami-tabs>.kami-tab{flex:0 0 auto;white-space:nowrap;overflow-wrap:normal;word-break:normal;}\n:where(.kami-root .kami-tab){appearance:none;font:inherit;color:var(--kami-fg-dim);background:transparent;border:0;border-radius:0;padding:var(--kami-pad-y) var(--kami-pad-x);cursor:pointer;}\n:where(.kami-root .kami-tab[aria-selected=\"true\"]){color:var(--kami-accent-fg);background-color:var(--kami-accent);border-bottom:var(--kami-accent-mark) solid var(--kami-accent);}\n.kami-root .kami-tabs>[data-kami-slot=\"tab-actions\"]{display:flex;align-items:center;position:sticky;inset-inline-end:0;margin-inline-start:auto;flex:0 0 auto;max-width:50%;min-width:0;}\n.kami-root .kami-tabs>[data-kami-slot=\"tab-actions\"] .kami-select{width:auto;max-width:100%;min-width:0;}\n\n.kami-root .kami-tabs[data-kami-tabs-mode=\"fit\"]>.kami-tab{flex:1 0 0;min-width:max-content;}\n\n/* ── Radix 控件的基础结构（2026-10-26 换框架）─────────────────────────\n   这些规则只管「换框架后必须存在」的结构与定位，**外观归皮肤**：\n     · .kami-select 现在是按钮（触发者），不是原生 <select>\n     · 选项弹层被 Radix Portal 挂到 body 上，层级/滚动只能在这儿定\n     · .kami-switch 现在是 button[role=switch]，要显式清掉按钮默认外观\n   21 套皮肤里的 .kami-select / .kami-switch 规则负责长得好看。 */\n.kami-select {\n  display: inline-flex; align-items: center; justify-content: space-between;\n  gap: 6px; cursor: pointer; text-align: left;\n}\n.kami-select-icon { flex: none; opacity: .7; font-size: .9em; }\n.kami-select-content {\n  z-index: 100000;\n  min-width: var(--radix-select-trigger-width);\n  max-height: 40vh; overflow-y: auto; overscroll-behavior: contain;\n  padding: 4px;\n  background: var(--kami-bg-soft, #17171c);\n  color: var(--kami-fg, #f2f2f4);\n  border: var(--kami-border-w, 1px) solid var(--kami-line, #3a3a44);\n  border-radius: var(--kami-r-sm, 8px);\n  box-shadow: 0 8px 28px rgba(0, 0, 0, .45);\n  font-family: var(--kami-font, inherit);\n  font-size: var(--kami-fs-sm, 13px);\n}\n.kami-select-item {\n  padding: 6px 10px; border-radius: var(--kami-r-xs, 6px);\n  cursor: pointer; outline: none; white-space: nowrap;\n}\n.kami-select-item[data-highlighted] { background: var(--kami-accent-soft, rgba(122, 162, 247, .25)); }\n.kami-select-item[data-state=\"checked\"] { color: var(--kami-accent, #7aa2f7); }\n.kami-switch {\n  -webkit-appearance: none; appearance: none;\n  display: inline-flex; align-items: center;\n  margin: 0; padding: 0; border: 0; background: none;\n  cursor: pointer; position: relative;\n}\n.kami-switch[disabled] { opacity: .5; cursor: not-allowed; }\n\n/* ============================================================\n * 卡密预设 · 兜底皮肤 (Kami Base Skin)  v0.1\n * ------------------------------------------------------------\n * 作用域：html:not([data-kami-skin]) .kami-root\n *   —— 皮肤管理脚本一运行（<html data-kami-skin> 出现），本文件整体失效，\n *      由选中皮肤包完全接管；皮肤管理被关闭/删除时，本文件重新生效。\n *\n * 构建时会被内联进：两个正则前端、皮肤管理面板、预设设置面板、引导面板。\n * 契约见 docs/皮肤契约.md —— 本文件是 §3 全部令牌的参考实现。\n *\n * ------------------------------------------------------------\n * 配色：清新的毛玻璃（2026-09-21 换掉原来那套紫 + 蓝）\n *   · 强调色是石墨灰蓝：暗档 #93a8bb（提亮一档，压在深色玻璃上才看得见），\n *     亮档 #5b6b7a（用户指定值）。\n *   · 表面一律半透明：暗档 70%~72% 的冷灰再叠 5%~10% 的白，亮档 58%~68% 的白。\n *     半透明是毛玻璃的前提 —— 底写死成不透明色，backdrop-filter 就什么也透不出来。\n *   · 七个 kind 色只留下「互相分得开」的色相：石墨蓝灰 / 藕粉 / 苔绿 / 青灰 /\n *     琥珀 / 玫红 / 中性灰。暗档提亮、亮档压深，两档在各自的底上都 >= 4.5:1。\n *   · 阴影改成冷灰（rgba(6,10,14,…)），不再是纯黑。\n *\n * 对比度（WCAG 2.1 相对亮度公式实算。玻璃底取「同族页面」的合成值：暗档假设页面是\n *   #14181c、亮档假设页面是 #eef1f4。玻璃底跟着页面走，跨族场景（系统深色配酒馆浅色\n *   主题）下字色不变、底会变浅，这是毛玻璃的固有代价，改令牌治不了）：\n *     暗档  正文 14.42（面板）/ 12.46（卡片）/ 10.72（悬停卡，最坏一档）；\n *           次要 9.28 / 8.02 / 6.90；最弱 5.91 / 5.11 / 4.40；\n *           强调底上的字 7.42；强调色当文字用 6.98 / 6.03；警示红 7.23。\n *     亮档  正文 14.86 / 15.37；次要 7.21 / 7.46；最弱 4.81 / 4.97；\n *           强调底上的字 5.48；强调色当文字用 5.20 / 5.38；警示红 5.25。\n *   描边强档（--kami-line-strong）对卡片底：暗档 3.02、亮档 3.24，§22 那条 >= 3:1 仍然成立。\n * ============================================================ */\n\n/* ---------- 令牌：暗色（默认） ---------- */\nhtml:not([data-kami-skin]) .kami-root {\n  --kami-fg: #e8ecf0;\n  --kami-fg-dim: #b7c0c8;\n  --kami-fg-mute: #8f99a3;\n  --kami-accent: #93a8bb;\n  --kami-accent-fg: #10161c;\n  --kami-accent-soft: rgba(147, 168, 187, .16);\n  --kami-accent-line: rgba(147, 168, 187, .50);\n\n  --kami-bg: rgba(26, 30, 35, .70);\n  --kami-bg-soft: rgba(30, 35, 41, .72);\n  --kami-card: rgba(255, 255, 255, .055);\n  --kami-card-2: rgba(14, 18, 22, .36);\n  --kami-card-hover: rgba(255, 255, 255, .10);\n  --kami-line: rgba(255, 255, 255, .12);\n  --kami-line-strong: rgba(255, 255, 255, .34);\n  --kami-t1: rgba(255, 255, 255, .05);\n  --kami-t2: rgba(255, 255, 255, .09);\n  --kami-t3: rgba(255, 255, 255, .16);\n  --kami-warn: #ff8a8a;\n  --kami-shadow: 0 10px 30px rgba(6, 10, 14, .42);\n  --kami-shadow-sm: 0 3px 10px rgba(6, 10, 14, .30);\n  --kami-blur: 18px;\n\n  --kami-r-xs: 6px;\n  --kami-r-sm: 9px;\n  --kami-r-md: 12px;\n  --kami-r-lg: 16px;\n  --kami-r-pill: 999px;\n  --kami-border-w: 1px;\n  --kami-pad-x: 10px;\n  --kami-pad-y: 7px;\n  --kami-pad-lg-x: 14px;\n  --kami-pad-lg-y: 12px;\n  --kami-gap: 8px;\n  --kami-gap-lg: 12px;\n  --kami-row-h: 34px;\n  --kami-icon: 15px;\n  --kami-maxw: none;\n  --kami-items-min: 240px;\n  --kami-panel-w: 840px;\n  --kami-panel-h: 1120px;\n  --kami-list-dir: column;\n  --kami-justify: stretch;\n\n  --kami-fs-scale: 1;\n  --kami-fs: calc(15px * var(--kami-fs-scale));\n  --kami-fs-xs: calc(var(--kami-fs) * .74);\n  --kami-fs-sm: calc(var(--kami-fs) * .86);\n  --kami-fs-lg: calc(var(--kami-fs) * 1.12);\n  --kami-lh: 1.62;\n  --kami-ls: .01em;\n  --kami-ls-title: .06em;\n  --kami-font: system-ui, -apple-system, \"Segoe UI\", \"Microsoft YaHei\", \"PingFang SC\", \"Noto Sans SC\", sans-serif;\n  --kami-font-title: var(--kami-font);\n  --kami-font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, \"Liberation Mono\", monospace;\n  --kami-fw: 400;\n  --kami-fw-title: 600;\n  --kami-title-transform: none;\n\n  --kami-texture: none;\n  --kami-glow: rgba(147, 168, 187, .55);\n  --kami-glow-size: 0px;\n  --kami-surface-clip: none;\n  --kami-accent-mark: 2px;\n\n  --kami-dur-fast: .13s;\n  --kami-dur: .2s;\n  --kami-dur-slow: .3s;\n  --kami-ease: cubic-bezier(.22, .61, .36, 1);\n  --kami-ease-out: cubic-bezier(.16, 1, .3, 1);\n  --kami-enter-y: 4px;\n  --kami-enter-scale: 1;\n  --kami-stagger: 24ms;\n\n  --kami-kind-action: #93b7d1;\n  --kami-kind-persona: #e0b0bf;\n  --kami-kind-plot: #9ccb96;\n  --kami-kind-info: #96c8c8;\n  --kami-kind-fun: #dfc06a;\n  --kami-kind-nsfw: #e08aa0;\n  --kami-kind-other: #a8b2bc;\n\n  /* ---- RPG 界面层（2026-10-07 新增，状态栏重构用；名字不带 status，四个面板都能用）----\n     这些**全部可选**：皮肤不定义就走下面的默认值。\n     build/lint-skins.mjs 的必填清单已把它们排除（见该文件 OPTIONAL_TOKENS）。 */\n  --kami-surface-2: var(--kami-card, rgba(40, 42, 52, .96));      /* L1 抬起层（卡片面） */\n  --kami-surface-3: var(--kami-card-hover, rgba(52, 55, 66, .96));/* L2 再抬一层 */\n  --kami-surface-4: var(--kami-bg-soft, rgba(26, 28, 36, .97));   /* 浮层 / 抽屉面 */\n  --kami-sunken: rgba(0, 0, 0, .30);            /* 凹陷槽底（条轨道 / 空槽 / 输入框） */\n  --kami-sunken-line: rgba(255, 255, 255, .10); /* 凹陷槽描边 */\n  --kami-edge: var(--kami-line-strong, rgba(255, 255, 255, .28)); /* 卡片外描边 */\n  --kami-edge-in: rgba(255, 255, 255, .07);     /* 内高光（外深内亮的倒角感） */\n  --kami-bar-h: 14px;                           /* 条高 */\n  --kami-bar-fill: linear-gradient(180deg, #8fb4f0, #5f86d6);\n  --kami-bar-fill-pos: linear-gradient(180deg, #8fd0a8, #4f9d78);\n  --kami-bar-fill-neg: linear-gradient(180deg, #d98f8f, #a85252);\n  --kami-bar-gloss: rgba(255, 255, 255, .28);   /* 填充顶部那 1px 高光 */\n  --kami-rank-bg: rgba(122, 162, 247, .20);     /* 档位菱形底 */\n  --kami-rank-edge: rgba(122, 162, 247, .55);   /* 档位菱形描边 */\n  --kami-rank-fg: #bcd4fb;\n  --kami-ico-size: 16px;\n  --kami-ico-size-sm: 13px;\n  --kami-sb-card-cols: 230px;                   /* 卡片两列的下限（每列至少这么宽） */\n  --kami-sb-row-gap: 3px;                       /* 条与条之间的行距 */\n\n  /* ---- 地图节点图（状态栏地图页专用；其余组件不会用到，放这里是为了能按皮肤配色）---- */\n  --kami-map-void: radial-gradient(circle at 40% 35%, #1e2530, #161b21 70%);\n  --kami-map-node-fill: #232a33;\n  --kami-map-node-edge: var(--kami-accent, #7aa2f7);\n  --kami-map-node-fg: #dbe4ee;\n  --kami-map-fog-fill: #1a1f26;\n  --kami-map-fog-edge: #3a434e;\n  --kami-map-fog-fg: #6b7784;\n  --kami-map-here-fill: rgba(122, 162, 247, .22);\n  --kami-map-here-ring: rgba(122, 162, 247, .50);\n  --kami-map-edge: #4b5563;\n  --kami-map-edge-dash: #3a434e;\n}\n\n/* ---------- 令牌：亮色 ---------- */\n@media (prefers-color-scheme: light) {\n  html:not([data-kami-skin]) .kami-root {\n    --kami-fg: #1e242a;\n    --kami-fg-dim: #4b555f;\n    --kami-fg-mute: #64707b;\n    --kami-accent: #5b6b7a;\n    --kami-accent-fg: #ffffff;\n    --kami-accent-soft: rgba(91, 107, 122, .12);\n    --kami-accent-line: rgba(91, 107, 122, .46);\n    --kami-bg: rgba(255, 255, 255, .58);\n    --kami-bg-soft: rgba(255, 255, 255, .68);\n    --kami-card: rgba(255, 255, 255, .62);\n    --kami-card-2: rgba(246, 249, 252, .55);\n    --kami-card-hover: rgba(255, 255, 255, .92);\n    --kami-line: rgba(30, 40, 50, .12);\n    --kami-line-strong: rgba(30, 40, 50, .52);\n    --kami-t1: rgba(30, 40, 50, .045);\n    --kami-t2: rgba(30, 40, 50, .075);\n    --kami-t3: rgba(30, 40, 50, .14);\n    --kami-warn: #c0392b;\n    --kami-shadow: 0 10px 26px rgba(6, 10, 14, .18);\n    --kami-shadow-sm: 0 2px 8px rgba(6, 10, 14, .12);\n    --kami-kind-action: #3f637e;\n    --kami-kind-persona: #9a5269;\n    --kami-kind-plot: #3f7a3a;\n    --kami-kind-info: #2f6a6a;\n    --kami-kind-fun: #82630c;\n    --kami-kind-nsfw: #a83b5e;\n    --kami-kind-other: #5e6873;\n\n    /* ---- RPG 界面层：亮色档（凹陷与高光方向要反过来，这是最容易做错的地方）---- */\n    --kami-surface-2: var(--kami-card, rgba(255, 255, 255, .62));\n    --kami-surface-3: var(--kami-card-hover, rgba(255, 255, 255, .92));\n    --kami-surface-4: var(--kami-bg-soft, rgba(255, 255, 255, .86));\n    --kami-sunken: rgba(30, 40, 50, .08);\n    --kami-sunken-line: rgba(30, 40, 50, .12);\n    --kami-edge: var(--kami-line-strong, rgba(30, 40, 50, .52));\n    --kami-edge-in: rgba(255, 255, 255, .70);\n    --kami-bar-fill: linear-gradient(180deg, #6f9be0, #4670bd);\n    --kami-bar-fill-pos: linear-gradient(180deg, #6bbd8b, #3d8a63);\n    --kami-bar-fill-neg: linear-gradient(180deg, #cf7a7a, #9a4343);\n    --kami-bar-gloss: rgba(255, 255, 255, .55);\n    --kami-rank-bg: rgba(91, 107, 122, .14);\n    --kami-rank-edge: rgba(91, 107, 122, .45);\n    --kami-rank-fg: #3f5470;\n\n    --kami-map-void: radial-gradient(circle at 40% 35%, #eef2f6, #e3e8ee 7