late-columns: auto 1fr;\n  align-items: start;\n  gap: var(--kami-gap);\n  padding-bottom: var(--kami-gap);\n  border-bottom: var(--kami-border-w) solid var(--kami-line);\n}\nhtml:not([data-kami-skin]) .kami-root[data-kami-comp=\"search\"] .kami-fact:last-child {\n  padding-bottom: 0;\n  border-bottom: 0;\n}\n/* 编号：小圆点数字，主色，不抢文字 */\nhtml:not([data-kami-skin]) .kami-root[data-kami-comp=\"search\"] .kami-fact-n {\n  display: inline-flex;\n  justify-self: start;   /* 网格项默认 stretch，不写就会被拉成扁椭圆 */\n  align-items: center;\n  justify-content: center;\n  min-width: 18px;\n  height: 18px;\n  margin-top: 1px;\n  border-radius: var(--kami-r-pill);\n  background: var(--kami-accent-soft);\n  color: var(--kami-accent);\n  font-size: var(--kami-fs-xs);\n  font-variant-numeric: tabular-nums;\n  line-height: 1;\n}\nhtml:not([data-kami-skin]) .kami-root[data-kami-comp=\"search\"] .kami-fact-text {\n  min-width: 0;\n  overflow-wrap: anywhere;\n  font-size: var(--kami-fs-sm);\n  color: var(--kami-fg);\n  line-height: 1.65;\n}\n/* 事实后面挂的来源标记：小小的方括号文字，别做成按钮 */\nhtml:not([data-kami-skin]) .kami-root[data-kami-comp=\"search\"] .kami-fact-src {\n  display: inline-flex;\n  flex-wrap: wrap;\n  gap: 4px;\n  margin-left: 6px;\n  vertical-align: baseline;\n}\nhtml:not([data-kami-skin]) .kami-root[data-kami-comp=\"search\"] .kami-src-mark {\n  color: var(--kami-accent);\n  font-size: var(--kami-fs-xs);\n  text-decoration: none;\n  border-bottom: 1px dotted var(--kami-accent-line);\n}\n@media (hover: hover) {\n  html:not([data-kami-skin]) .kami-root[data-kami-comp=\"search\"] .kami-src-mark:hover {\n    color: var(--kami-fg);\n    border-bottom-color: var(--kami-line-strong);\n  }\n}\nhtml:not([data-kami-skin]) .kami-root[data-kami-comp=\"search\"] .kami-fact-note {\n  margin: 0;\n  padding-left: 26px;\n}\n\n/* ---- 来源表：底部一块，标题 + 芯片行 ---- */\nhtml:not([data-kami-skin]) .kami-root[data-kami-comp=\"search\"] .kami-src-box {\n  display: flex;\n  flex-direction: column;\n  gap: calc(var(--kami-gap) * .