    var items = skillItemsOf(char, SKILL_SECTIONS[i].src);
    if (items.length) { out.push({ id: SKILL_SECTIONS[i].id, label: cpy(SKILL_SECTIONS[i].copy), icon: SKILL_SECTIONS[i].icon, count: items.length }); }
  }
