    }
    /* "当前"取最后一个已发生节点；没有已发生的就取第一个 */
    var phase = 'future';
    for (j = 0; j < nodes.length; j++) { if (nodes[j].phase && nodes[j].phase !== 'future') { phase = nodes[j].phase; } }
    out.push({
      id: l.id, foldId: 'line:' + l.id, headless: false,
